// ── מיגרציה חד-פעמית — מתקנת נתונים ישנים ──
function runMigrations() {
  const migKey = 'migration_v2_status'; // v2 = גם יוצר הכנסות מתוכניות קיימות
  if (localStorage.getItem(migKey)) return; // כבר רץ

  const todayStr = new Date().toISOString().slice(0, 10);
  let changed = false;

  // תיקון הכנסות ללא status
  const income = load('income');
  income.forEach(i => {
    if (i.status === undefined || i.status === null || i.status === '') {
      // תאריך עתידי = ממתין, עבר = שולם
      i.status = i.date > todayStr ? 'pending' : 'paid';
      changed = true;
    }
  });
  if (changed) save('income', income);

  // תיקון תוכניות תשלום — payment.paid חייב להיות boolean מפורש
  // + צור הכנסות ממתינות לתשלומים שעדיין אין להם incomeId
  changed = false;
  const plans = load('plans');
  const incomeArr = load('income');
  plans.forEach(plan => {
    (plan.payments || []).forEach(p => {
      if (p.paid === undefined || p.paid === null) { p.paid = false; changed = true; }
      if (!p.incomeId) {
        if (p.paid) {
          // תשלום ששולם ואין לו incomeId — בדוק אם קיים כבר ברשימה לפי fromPlan
          const existing = incomeArr.find(i => i.fromPlan === plan.id && i.fromPaymentId === p.id);
          if (existing) { p.incomeId = existing.id; }
          // אחרת אין מה ליצור — תשלום ישן שנמחק
        } else {
          // תשלום ממתין ללא הכנסה — צור עכשיו
          const entry = {
            id: genId(), date: p.dueDate, amount: p.amount,
            clientId: plan.clientId || '', clientName: plan.clientName || '',
            description: `${plan.project} — תשלום ${p.index} מתוך ${plan.count}`,
            category: 'הפקה מוזיקלית', status: 'pending',
            fromPlan: plan.id, fromPaymentId: p.id
          };
          p.incomeId = entry.id;
          incomeArr.push(entry);
        }
        changed = true;
      }
    });
  });
  if (changed) { save('plans', plans); save('income', incomeArr); }

  localStorage.setItem('migration_v1_status', '1'); // backward compat
  localStorage.setItem(migKey, '1');
  console.log('✅ מיגרציה v2 הושלמה');
}

// תיקון חד-פעמי — החזרת סימון "שולם" שנפל מהכנסות (מאי 2026)
function fixPaidStatusesMay2026() {
  const FIX_KEY = 'fix_paid_may2026';
  if (localStorage.getItem(FIX_KEY)) return;
  const paidIds = ['idmot76y89kzk','idmot76y89awd','idmon68wnv52l']; // רן 1, רן 2 (לפי התוכנית) + ארומה/נווה לוי (אושר)
  const income = load('income');
  let changed = false;
  income.forEach(i => {
    if (paidIds.includes(i.id) && i.status !== 'paid') { i.status = 'paid'; changed = true; }
  });
  if (changed) {
    save('income', income);
    const plans = load('plans');
    let pc = false;
    income.filter(i => paidIds.includes(i.id) && i.fromPlan && i.fromPaymentId).forEach(i => {
      const plan = plans.find(p => p.id === i.fromPlan);
      if (!plan) return;
      const pay = (plan.payments || []).find(p => p.id === i.fromPaymentId);
      if (pay && !pay.paid) { pay.paid = true; pay.paidDate = pay.paidDate || i.date; pc = true; }
    });
    if (pc) save('plans', plans);
    console.log('✅ תיקון סטטוסי שולם הוחל');
  }
  localStorage.setItem(FIX_KEY, '1');
}

// תיקון חד-פעמי — התחלה חדשה לתהליך: פתיחה 104 ק"ג, יום 1 (לבקשת
// אליאור 19.7.26). רץ על המכשיר אחרי סנכרון הענן, כך ששום גרסה ישנה
// לא יכולה לדרוס אותו (האיפוס הקודם רץ בענן ונדרס ע"י המכשיר).
function fixProcessRestart104() {
  const KEY = 'fix_reset104_1907';
  try {
    if (localStorage.getItem(KEY)) return;
    if (typeof _mptState !== 'function' || typeof mpSave !== 'function') return;
    const st = _mptState();
    st.weightsArchive = (Array.isArray(st.weightsArchive) ? st.weightsArchive : []).concat(st.weights || []);
    if (st.weightsArchive.length > 800) st.weightsArchive = st.weightsArchive.slice(-800);
    const today = _mpbToday();
    st.processStart = today;
    st.startWeight = 104;
    st.weights = [{ d: today, kg: 104 }];
    mpSave(st);
    localStorage.setItem(KEY, '1');
    console.log('✅ תהליך אופס: יום 1, 104 ק"ג');
  } catch (e) { console.warn('fixProcessRestart104 failed', e); }
}

