function fixProcessDay2() {
  const KEY = 'fix_day2_2107';
  const DAY1 = '2026-07-20';
  try {
    if (localStorage.getItem(KEY)) return;
    if (typeof _mptState !== 'function' || typeof mpSave !== 'function') return;
    const st = _mptState();
    st.processStart = DAY1;
    st.startWeight = 104;
    // his real weigh-ins from day 1 onwards — from archive + current,
    // minus the synthetic 104 seeds the previous fix created
    const seen = {};
    (Array.isArray(st.weightsArchive) ? st.weightsArchive : []).concat(st.weights || [])
      .filter(w => w && w.d >= DAY1 && Number(w.kg) !== 104)
      .forEach(w => { seen[w.d] = Number(w.kg); });
    let weights = Object.keys(seen).sort().map(d => ({ d: d, kg: seen[d] }));
    if (!weights.length) weights = [{ d: DAY1, kg: 104 }];
    st.weights = weights;
    mpSave(st);
    localStorage.setItem(KEY, '1');
    console.log('✅ יום 2 בתהליך: start=' + DAY1, JSON.stringify(weights));
  } catch (e) { console.warn('fixProcessDay2 failed', e); }
}

function initFirebase() {
  _loadPending(); // טען תור שמירה שנשאר מסשן קודם
  try {
    if (!firebase || firebaseConfig.apiKey === 'PASTE_YOUR_API_KEY_HERE') {
      console.warn('Firebase not configured – running in local-only mode');
      return Promise.resolve();
    }
    firebase.initializeApp(firebaseConfig);
    firebaseDB = firebase.database();
    try { firebaseStorage = firebase.storage(); } catch(e) { console.warn('Storage init failed', e); }

    // v611: load ONLY the live data + its timestamps — never the whole database
    // (the root also holds every backup; downloading it on each open burns the
    // free Firebase download allowance and can make the database stop answering)
    return Promise.all([firebaseDB.ref('studio_data').once('value'), firebaseDB.ref('studio_meta').once('value')]).then(([sd, sm]) => {
      const root = { studio_data: sd.val() || {}, studio_meta: sm.val() || {} };
      const cloudData = root.studio_data || {};
      const cloudMeta = root.studio_meta || {};
      ALL_KEYS.forEach(key => {
        if (_pending[key]) {
          // pending changes from a previous session. Only "newer than cloud"
          // if they really are — otherwise merge (6.10, see _syncMerge).
          const pTs = _pending[key].ts || 0, cTs = parseInt(cloudMeta[key] || '0', 10);
          const pBase = parseInt(localStorage.getItem('s_' + key + '_base') || '0', 10);
          if (cloudData[key] != null && cTs > 0 && cTs !== pTs && (cTs > pTs || (pBase > 0 && cTs > pBase))) {
            try { localStorage.setItem('s_' + key + '_base', String(cTs)); } catch (_) {}
            _syncStashConflict(key, _pending[key].data, pTs);
            _pending[key] = { data: _syncMerge(key, _pending[key].data, pTs, cloudData[key], cTs), ts: Date.now(), _checked: true };
            _savePending();
          }
          localStorage.setItem('s_' + key, JSON.stringify(_pending[key].data));
          if (_pending[key].ts) localStorage.setItem('s_' + key + '_ts', String(_pending[key].ts));
          _pushKey(key);
        } else {
          const cloudVal = cloudData[key] ?? null;
          const hasCloud = cloudVal && (Array.isArray(cloudVal) ? cloudVal.length > 0 : Object.keys(cloudVal).length > 0);
          const cloudTs = parseInt(cloudMeta[key] || '0', 10);
          const localTs = parseInt(localStorage.getItem('s_' + key + '_ts') || '0', 10);

          if (hasCloud) {
            // Use cloud only if it's newer OR if we don't have a local timestamp (first load)
            if (cloudTs === 0 || localTs === 0 || cloudTs > localTs) {
              let take = cloudVal;
              if (key === 'fixed_costs') {
                try { take = _fcMerge(cloudVal, JSON.parse(localStorage.getItem('s_fixed_costs') || '[]')); } catch (_) {}
              }
              localStorage.setItem('s_' + key, JSON.stringify(take));
              if (cloudTs > 0) { localStorage.setItem('s_' + key + '_ts', String(cloudTs)); localStorage.setItem('s_' + key + '_base', String(cloudTs)); }
              if (take !== cloudVal && JSON.stringify(take) !== JSON.stringify(cloudVal)) { _markDirty(key, take); _pushKey(key); }
            }
            // else: local is newer, push it back to cloud
            else if (localTs > cloudTs) {
              const localRaw = localStorage.getItem('s_' + key);
              if (localRaw) { _pending[key] = { data: JSON.parse(localRaw), ts: localTs }; _savePending(); _pushKey(key); }
            }
          } else {
            // אין ענן — העלה את המקומי
            const localRaw = localStorage.getItem('s_' + key);
            if (localRaw) {
              const localVal = JSON.parse(localRaw);
              if (localVal && (Array.isArray(localVal) ? localVal.length > 0 : Object.keys(localVal).length > 0)) {
                const ts = localTs || Date.now();
                _pending[key] = { data: localVal, ts };
                _savePending();
                _pushKey(key);
              }
            }
          }
        }
      });
      firebaseReady = true;
      _isFirstSync = false;
      runMigrations();
      fixPaidStatusesMay2026(); // תיקון חד-פעמי לסטטוסי שולם
      setTimeout(autoBackup, 3000); // גיבוי יומי אוטומטי אחרי שהנתונים התייצבו
      console.log('Firebase loaded ✓ pending:', Object.keys(_pending).length);
    }).catch(err => {
      console.warn('Firebase load failed — using local data:', err.message);
    });
  } catch(e) {
    console.warn('Firebase init failed:', e.message);
    return Promise.resolve();
  }
}

const ALL_KEYS = ['income','expenses','clients','plans','proj_notes','proj_done','proj_status','proj_services','proj_next','projects','productions','pending_tx','recurring_expenses','sessions','monthlyGoal','bankDeposit','tasks','daily_tasks','schedule','sketch_songs','workshops','sketch_aliases','sketch_versions','sketch_hidden','contracts','producer_settings','students','proposals','custom_exp_cats','custom_inc_cats','cat_rename_exp','cat_rename_inc','my_path','tx_rules','bank_credits','year_goals','fixed_costs','wedding','wedding_exp','wedding_todo','wedding_meet'];

// ===== SYNC ENGINE — תור שמירה עמיד =====
// כל שמירה נכנסת לתור ב-localStorage.
// לא תימחק עד שהענן מאשר קבלה.
// כך אף שינוי לא יאבד גם אם האפליקציה נסגרת באמצע.

let _pending = {};  // key → {data, ts}

function _loadPending() {
  try { _pending = JSON.parse(localStorage.getItem('_sync_pending') || '{}'); } catch(e) { _pending = {}; }
}

function _savePending() {
  try { localStorage.setItem('_sync_pending', JSON.stringify(_pending)); } catch(e) {}
}

function _markDirty(key, val) {
  _pending[key] = { data: val, ts: Date.now() };
  _savePending();
}

function _markClean(key) {
  if (!_pending[key]) return;
  delete _pending[key];
  _savePending();
}

// ── Conflict-safe sync (6.10) ─────────────────────────────────────────
// A device that sat with an old copy (e.g. the iPhone, whose Firebase
// socket freezes in the background and leaves a stale "pending" save, or
// a computer tab left open) used to push that whole old copy over newer
// edits made elsewhere — that is how a night of fixed-cost charge days
// vanished. Now: before pushing, compare with the cloud's timestamp; if
// the cloud is newer, MERGE instead of overwrite.
//  • fixed_costs — every item carries updatedAt (stamped in save()), so
//    the newer version of each item wins and removals are tombstones.
//  • other lists of {id} items — union by id (newer side wins per id), so
//    nothing either side added is lost.
//  • anything else — the newer timestamp wins (was: the stale one won).
const _SYNC_REST = 'https://elior-studio-default-rtdb.firebaseio.com';
// stamp changed / new fixed-cost items, and turn removed ones into
// tombstones so a merge can't bring them back (6.10)
function _fcStamp(next) {
  if (!Array.isArray(next)) return;
  let prev = []; try { prev = JSON.parse(localStorage.getItem('s_fixed_costs') || '[]'); } catch (_) {}
  if (!Array.isArray(prev)) prev = Object.values(prev || {});
  const strip = x => { const c = Object.assign({}, x); delete c.updatedAt; return JSON.stringify(c); };
  const pm = {}; prev.forEach(x => { if (x && x.id) pm[x.id] = x; });
  const now = Date.now(), seen = {};
  next.forEach(x => { if (!x || !x.id) return; seen[x.id] = 1; const p0 = pm[x.id]; if (!p0 || strip(p0) !== strip(x)) x.updatedAt = now; });
  prev.forEach(x => { if (x && x.id && !seen[x.id] && !x.deleted) next.push({ id: x.id, deleted: true, updatedAt: now }); });
  // keep tombstones that are already there
  prev.forEach(x => { if (x && x.id && !seen[x.id] && x.deleted) next.push(x); });
}
function _fcMerge(a, b) {
  const m = new Map();
  [a, b].forEach(arr => (Array.isArray(arr) ? arr : (arr ? Object.values(arr) : [])).forEach(x => {
    if (!x || !x.id) return;
    const c = m.get(x.id);
    if (!c || (Number(x.updatedAt) || 0) > (Number(c.updatedAt) || 0)) m.set(x.id, x);
  }));
  return [...m.values()];
}
const _isIdList = v => Array.isArray(v) && v.length > 0 && v.every(x => x && typeof x === 'object' && x.id != null);
// Merge my copy with a cloud copy that changed since mine was based on it.
// Per item the newer stamp wins (ties → cloud); items only one side has
// are kept. Non-list values: the cloud (the other device's newer save)
// wins and my version is kept in _sync_conflicts.
function _syncMerge(key, mine, mineTs, cloud, cloudTs) {
  if (key === 'fixed_costs') return _fcMerge(cloud, mine);
  if (_isIdList(mine) && _isIdList(cloud)) {
    const m = new Map(); cloud.forEach(x => m.set(String(x.id), x));
    mine.forEach(x => { const k = String(x.id), c = m.get(k); if (!c || (Number(x._u) || 0) > (Number(c._u) || 0)) m.set(k, x); });
    return [...m.values()];
  }
  return cloud;
}
// stamp changed / new items of a list of {id} objects (6.10)
function _stampList(key, next) {
  if (!_isIdList(next)) return;
  let prev = []; try { prev = JSON.parse(localStorage.getItem('s_' + key) || '[]'); } catch (_) {}
  if (!Array.isArray(prev)) return;
  const strip = x => { const c = Object.assign({}, x); delete c._u; return JSON.stringify(c); };
  const pm = {}; prev.forEach(x => { if (x && x.id != null) pm[String(x.id)] = x; });
  const now = Date.now();
  next.forEach(x => { const p0 = pm[String(x.id)]; if (!p0 || strip(p0) !== strip(x)) x._u = now; });
}
function _syncStashConflict(key, data, ts) {
  try {
    const c = JSON.parse(localStorage.getItem('_sync_conflicts') || '[]');
    c.push({ key, ts, at: Date.now(), data });
    localStorage.setItem('_sync_conflicts', JSON.stringify(c.slice(-6)));
  } catch (_) {}
}
function _pushKey(key) {
  if (!firebaseDB || !_pending[key]) return;
  const snap0 = _pending[key];
  if (snap0._checked) return _pushKeyNow(key);
  // ask the cloud (plain HTTPS — works even when the SDK socket is frozen)
  fetch(_SYNC_REST + '/studio_meta/' + key + '.json', { cache: 'no-store' })
    .then(r => r.json()).catch(() => null)
    .then(async cloudTsRaw => {
      if (_pending[key] !== snap0) return;                    // superseded by a newer save
      const cloudTs = parseInt(cloudTsRaw || '0', 10), myTs = snap0.ts || 0;
      const base = parseInt(localStorage.getItem('s_' + key + '_base') || '0', 10);
      // conflict = the cloud changed since the copy this edit was made on
      if (cloudTs > 0 && base > 0 && cloudTs > base && cloudTs !== myTs) {
        let cloud = null;
        try { cloud = await fetch(_SYNC_REST + '/studio_data/' + key + '.json', { cache: 'no-store' }).then(r => r.json()); } catch (_) {}
        if (_pending[key] !== snap0) return;
        if (cloud != null) {
          _syncStashConflict(key, snap0.data, myTs);
          const merged = _syncMerge(key, snap0.data, myTs, cloud, cloudTs);
          const now = Date.now();
          try { localStorage.setItem('s_' + key, JSON.stringify(merged)); localStorage.setItem('s_' + key + '_ts', String(now)); } catch (_) {}
          if (JSON.stringify(merged) === JSON.stringify(cloud)) {   // cloud already had everything
            try { localStorage.setItem('s_' + key + '_ts', String(cloudTs)); localStorage.setItem('s_' + key + '_base', String(cloudTs)); } catch (_) {}
            _markClean(key);
          } else {
            try { localStorage.setItem('s_' + key + '_base', String(cloudTs)); } catch (_) {}
            _pending[key] = { data: merged, ts: now, _checked: true }; _savePending();
            _pushKeyNow(key);
          }
          try { refreshAll(); } catch (_) {}
          return;
        }
      }
      if (_pending[key] === snap0) { snap0._checked = true; _pushKeyNow(key); }
    });
}
// v612: a list push never deletes items this device didn't delete itself.
// Before writing, read the cloud list; any item there that's missing here and
// was NOT deleted on this device (deletion log) is kept. Protects against a
// device with an old copy wiping newer data (what happened on 16.10).
function _delLog(key) { try { return JSON.parse(localStorage.getItem('_dl_' + key) || '{}') || {}; } catch (_) { return {}; } }
function _delLogAdd(key, ids) {
  if (!ids.length) return; const L = _delLog(key), now = Date.now();
  ids.forEach(id => { L[String(id)] = now; });
  Object.keys(L).forEach(k => { if (now - L[k] > 120 * 864e5) delete L[k]; });
  try { localStorage.setItem('_dl_' + key, JSON.stringify(L)); } catch (_) {}
}
