  const has = k => { try { return !!localStorage.getItem(k); } catch (_) { return false; } };
  return [['Morning', has('morning_api_id') && has('morning_api_secret')], ['וואטסאפ', has('wa_send_secret')], ['Google', has('gcal_ics_url') || has('gcal_w_tokens')]]
