    for (const it of todo) { const gid = await gcalWriteCreateEvent(it); const cur = load('schedule'), sv = cur.find(x => x.id === it.id); if (sv) { delete sv.needsCal; if (gid) sv.gcalEventId = gid; save('schedule', cur); } }
