setInterval(backupDaily, 60 * 60 * 1000);
const _BK_NAMES = { income: 'הכנסות', expenses: 'הוצאות', fixed_costs: 'הוצאות קבועות', clients: 'לקוחות', productions: 'הפקות', schedule: 'לו״ז', plans: 'תשלומים', sessions: 'סשנים', contracts: 'סיכומי הפקה', proposals: 'הצעות מחיר', students: 'תלמידים' };
