window.backupRestore = async function(id, b) {
  if (!confirm('לשחזר מהגיבוי? מה שנמחק יחזור, ושום דבר חדש לא יימחק. לפני כן נשמר גיבוי של המצב הנוכחי.')) return;
  toast('שומר גיבוי ביטחון…');
  if (!(await backupNow('before-restore-' + Date.now()))) { if (!confirm('לא הצלחתי לשמור גיבוי ביטחון (אין אינטרנט?). להמשיך בכל זאת?')) return; }
  const now = Date.now(); let n = 0;
  Object.keys(b.data).forEach(k => {
    const bv = b.data[k]; if (bv == null) return;
    let cv = null; try { cv = JSON.parse(localStorage.getItem('s_' + k)); } catch (_) {}
    let out = bv;
    if (_isIdList(bv)) {
      const m = new Map(); (Array.isArray(cv) ? cv : []).forEach(x => x && x.id != null && m.set(String(x.id), x));
      bv.forEach(x => { if (!x || x.id == null || x.deleted) return; const c = Object.assign({}, x); if ('updatedAt' in c || k === 'fixed_costs') c.updatedAt = now; c._u = now; m.set(String(x.id), c); });
      out = [...m.values()];
    } else if (cv != null) return;              // non-list settings: keep what's there now
    try { save(k, out); n++; } catch (_) {}
  });
  try { refreshAll(); } catch (_) {}
  spDone('שוחזר מהגיבוי', '', n + ' רשימות הוחזרו');
};
function save(key, val) {
  const ts = Date.now();
  if (key === 'fixed_costs') { try { _fcStamp(val); } catch (e) { console.warn('_fcStamp', e); } try { setTimeout(() => { try { fcSnapshot(); } catch (_) {} }, 0); } catch (_) {} }
  else { try { _stampList(key, val); } catch (_) {} }
  try { if (_isIdList(val) || (Array.isArray(val) && !val.length)) { const prev = JSON.parse(localStorage.getItem('s_' + key) || '[]'); if (Array.isArray(prev)) { const nowIds = new Set(val.map(x => String(x && x.id))); _delLogAdd(key, prev.filter(x => x && x.id != null && !nowIds.has(String(x.id))).map(x => x.id)); } } } catch (_) {}
  try { if (localStorage.getItem('s_' + key + '_base') == null) localStorage.setItem('s_' + key + '_base', localStorage.getItem('s_' + key + '_ts') || '0'); } catch (_) {}
  // 1. כתוב מקומית מיד — שמור בתוך try כדי לתפוס QuotaExceededError
  try {
    localStorage.setItem('s_' + key, JSON.stringify(val));
    localStorage.setItem('s_' + key + '_ts', String(ts));
  } catch (e) {
    console.warn('localStorage write failed for', key, e);
    // EMERGENCY SELF-CLEAN — an income entry must never be lost to a
    // full disk. Drop the fat regenerable caches and retry the write.
    try {
      try { localStorage.removeItem('_local_backup'); } catch (_) {}   // full snapshot — the cloud has daily copies
      try {
        const raw = JSON.parse(localStorage.getItem('wa_raw_cache') || '{}');
        const ks = Object.keys(raw).sort();
        if (ks.length > 120) {
          const keep = {};
          ks.slice(-120).forEach(k => { keep[k] = raw[k]; });
          localStorage.setItem('wa_raw_cache', JSON.stringify(keep));
        } else {
          localStorage.removeItem('wa_raw_cache');
        }
      } catch (_) { try { localStorage.removeItem('wa_raw_cache'); } catch (__) {} }
      localStorage.setItem('s_' + key, JSON.stringify(val));
      localStorage.setItem('s_' + key + '_ts', String(ts));
      if (typeof toast === 'function') toast('🧹 האחסון היה מלא — נוקה אוטומטית והנתון נשמר ✓');
    } catch (e2) {
      if (typeof toast === 'function') toast('⚠️ אחסון מקומי מלא — שמור גיבוי ונקה');
      return;
    }
  }
  // 2. הוסף לתור ושמור בdisk — שורד סגירת אפליקציה
  _pending[key] = { data: val, ts };
  _savePending();
  // 3. נסה לדחוף לענן עכשיו
  _pushKey(key);
  // 4. כשמשימות יומיות או פריט בלוז משתנים — סנכרן ל-Home-screen widget
  //    + עדכן את ה-App Icon Badge.
  if ((key === 'daily_tasks' || key === 'schedule') &&
      typeof window.syncTasksToWidget === 'function') {
    window.syncTasksToWidget();
  }
  if ((key === 'daily_tasks' || key === 'schedule') &&
      typeof window.updateAppBadge === 'function') {
    window.updateAppBadge();
  }
  // 5. שינוי בכסף → רענון מנוע התראות הכסף (מתוזמן, מקומי).
  if ((key === 'income' || key === 'recurring_expenses' || key === 'clients') &&
      typeof window._moneyNotifKick === 'function') {
    window._moneyNotifKick();
  }
  // 6. שינוי בלוז → רענון התראות 30-דקות-לפני של האפליקציה.
  if (key === 'schedule' && typeof window._schedNotifKick === 'function') {
    window._schedNotifKick();
  }
  // 7. שינוי בנתונים שמזינים את תדרוך הבוקר → רענון התדרוך.
  if ((key === 'income' || key === 'schedule' || key === 'my_path') &&
      typeof window._briefKick === 'function') {
    window._briefKick();
  }
}

// ===== גיבוי אוטומטי =====
// בכל טעינה נשמר עותק מלא של כל הנתונים בצומת נפרד בענן (studio_backups)
// וגם עותק מקומי. הגיבוי לא נוגע בנתונים החיים — רק מוסיף נקודת שחזור.
// שמירה: כל יום מ-30 הימים האחרונים + צ'קפוינט חודשי לכל חודש אחורה (לתמיד).
const BACKUP_KEEP_DAYS = 30;

function _collectAllData() {
  const data = {};
  ALL_KEYS.forEach(k => {
    const v = localStorage.getItem('s_' + k);
    if (v) { try { data[k] = JSON.parse(v); } catch(e){} }
  });
  return data;
}

function _hasMeaningfulData(data) {
  // אל תגבה מצב ריק על גבי גיבוי תקין
  const inc = data.income, exp = data.expenses;
  return (Array.isArray(inc) && inc.length > 0) || (Array.isArray(exp) && exp.length > 0);
}

function autoBackup() {
  try {
    const today = new Date().toISOString().slice(0, 10);
    const data = _collectAllData();
    if (!_hasMeaningfulData(data)) return; // לא נדרוס גיבוי טוב במצב ריק

    // עותק מקומי — תמיד, גם בלי אינטרנט. מוגבל ל-1.5MB — מעבר לזה
    // הוא דוחק את הנתונים החיים החוצה (QuotaExceeded בהוספת הכנסה);
    // הענן ממילא שומר גיבוי יומי מלא.
    try {
      const snap = JSON.stringify({ date: today, ts: Date.now(), data });
      if (snap.length < 1500000) localStorage.setItem('_local_backup', snap);
      else localStorage.removeItem('_local_backup');
    } catch(e) {}

    // עותק לענן — מעדכן את גיבוי היום בכל טעינה כך שהוא תמיד עדכני
    if (firebaseDB) {
      const _inc = Array.isArray(data.income) ? data.income.length : 0;
      firebaseDB.ref('studio_backups/' + today + '/data/income').once('value').then(ps => { const prev = ps.val(); const pn = Array.isArray(prev) ? prev.length : prev ? Object.keys(prev).length : 0;
        return pn > 5 && _inc < pn * 0.8 ? firebaseDB.ref('studio_backups/' + today + '-b' + Date.now()).set({ ts: Date.now(), data }) : firebaseDB.ref('studio_backups/' + today).set({ ts: Date.now(), data }); })
        .then(() => { localStorage.setItem('_last_auto_backup', today); _pruneBackups(); })
        .catch(() => {});
    } else {
      localStorage.setItem('_last_auto_backup', today);
    }
  } catch(e) { console.warn('autoBackup failed', e); }
}

function _pruneBackups() {
  if (!firebaseDB) return;
  // v611: pruning downloads every backup — once a week is plenty
  try { const lp = Number(localStorage.getItem('_last_prune') || 0); if (Date.now() - lp < 7 * 864e5) return; localStorage.setItem('_last_prune', String(Date.now())); } catch (_) {}
  firebaseDB.ref('studio_backups').once('value').then(snap => {
    const all = snap.val() || {};
    const dates = Object.keys(all).sort(); // ישן→חדש, פורמט YYYY-MM-DD
    if (!dates.length) return;
    const cutoff = new Date(); cutoff.setDate(cutoff.getDate() - BACKUP_KEEP_DAYS);
    const cutoffStr = cutoff.toISOString().slice(0, 10);
    const monthKept = {};
    const updates = {};
    dates.forEach(d => {
      if (/-srv$/.test(d)) return;          // v624: nightly server copies are pruned by the server job
      if (d >= cutoffStr) return;            // בתוך החלון היומי — שומרים הכל
      const month = d.slice(0, 7);            // YYYY-MM
      if (!monthKept[month]) monthKept[month] = d;  // צ'קפוינט חודשי — נשמר לתמיד
      else updates['studio_backups/' + d] = null;   // שאר הישנים בחודש — נמחקים
    });
    if (Object.keys(updates).length) firebaseDB.ref().update(updates).catch(() => {});
  }).catch(() => {});
}

function restoreFromAutoBackup() {
  if (!firebaseDB) { toast('❌ אין חיבור לענן לשחזור'); return; }
  toast('טוען רשימת גיבויים…');
  firebaseDB.ref('studio_backups').once('value').then(snap => {
    const all = snap.val() || {};
    const dates = Object.keys(all).sort().reverse(); // חדש → ישן
    if (!dates.length) { toast('אין עדיין גיבויים אוטומטיים'); return; }
    const list = dates.map((d, i) => {
      const bd = all[d] && all[d].data ? all[d].data : {};
      const inc = Array.isArray(bd.income) ? bd.income.length : 0;
      const exp = Array.isArray(bd.expenses) ? bd.expenses.length : 0;
      return (i + 1) + '. ' + d + ' — ' + inc + ' הכנסות, ' + exp + ' הוצאות';
    }).join('\n');
    const choice = prompt('בחר מספר גיבוי לשחזור:\n\n' + list);
    if (!choice) return;
    const idx = parseInt(choice, 10) - 1;
    if (isNaN(idx) || idx < 0 || idx >= dates.length) { toast('בחירה לא תקינה'); return; }
    const backup = all[dates[idx]];
    if (!backup || !backup.data) { toast('גיבוי לא תקין'); return; }
    if (!confirm('לשחזר את הגיבוי מ-' + dates[idx] + '?\nזה יחליף את הנתונים הנוכחיים בכל המכשירים.')) return;
    ALL_KEYS.forEach(k => {
      if (backup.data[k] !== undefined) localStorage.setItem('s_' + k, JSON.stringify(backup.data[k]));
    });
    pushAllToCloud();
    refreshAll();
    toast('✅ שוחזר גיבוי מ-' + dates[idx]);
  }).catch(() => toast('❌ שגיאה בטעינת גיבויים'));
}

const genId = () => 'id' + Date.now().toString(36) + Math.random().toString(36).slice(2,5);

// ===== UTILS =====
const fmtMoney = n => '₪' + Math.abs(n).toLocaleString('he-IL', {minimumFractionDigits:0, maximumFractionDigits:0});
const fmtDate = s => { if(!s) return ''; const d=new Date(s); return d.toLocaleDateString('he-IL',{day:'2-digit',month:'2-digit',year:'numeric'}); };
const inCurMonth = s => { const d=new Date(s); return d.getFullYear()===curYear && d.getMonth()===curMonth; };
const avClass = (i, inactive) => inactive ? 'av-7' : ('av-' + (i%8));

function toast(msg) {
  const t = document.getElementById('toast');
  t.textContent = msg; t.classList.add('show');
  setTimeout(() => t.classList.remove('show'), 2400);
  // Match the haptic to the visual cue — emoji prefix is the simplest
  // signal: ✓/🎉/💾 = success, ⚠/❌ = error, otherwise a soft tap.
  try {
    if (window.haptic) {
      const m = String(msg || '');
      if (/[✓✔🎉💾🟢]/.test(m))      window.haptic.success();
      else if (/[❌⚠🔴]/.test(m))      window.haptic.error();
      else                              window.haptic.tap();
    }
  } catch (e) {}
}

// ===== NAVIGATION =====
let _lastNavPage = null;
let _lastNavTime  = 0;

function showPage(name) {
  const now = Date.now();
  // לחיצה כפולה על אותה כרטיסייה — גלול למעלה
  if (name === _lastNavPage && now - _lastNavTime < 500) {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    document.querySelector('.main')?.scrollTo({ top: 0, behavior: 'smooth' });
    _lastNavTime = 0;
    return;
  }
  _lastNavPage = name;
  _lastNavTime = now;

  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  document.querySelectorAll('#sidebar-nav a').forEach(a => a.classList.remove('active'));
  document.getElementById('page-' + name).classList.add('active');
  const map = {productions:0, income:1, expenses:2, schedule:3, whatsapp:4, installments:5, profiles:6, daily:7, workshops:8, proposals:9, contracts:10, students:11, dashboard:12};
  if (name === 'fixed') { try { fcRender(); } catch (_) {} }
  if (name === 'whatsapp') { try { renderWhatsappPage(); } catch (e) {} }
  if (name === 'daily') _dailyDate = dailyDateStr();
  if (name === 'schedule') {
    _scheduleDate = dailyDateStr();
    try {
      // EventKit refresh — native iOS, no Google setup needed.
      if (typeof gcalRefreshEventKit === 'function') gcalRefreshEventKit();
      // ICS / OAuth read feeds — only if the user explicitly set
      // them up. (EventKit alone already covers reads for users
      // who synced Google via iOS Settings.)
      if (typeof _icsConnected === 'function' && _icsConnected()) {
        fetchGcalIcs(true);
      } else {
        if (typeof gcalLoadToken === 'function' && !_gcalToken) gcalLoadToken();
        if (_gcalToken && (!_gcalEventsCache || !_gcalEventsCache.length) && typeof fetchGoogleEvents === 'function') {
          fetchGoogleEvents(true);
        }
      }
    } catch (e) {}
    if (typeof renderScheduleGcalBar === 'function') renderScheduleGcalBar();
    renderSchedule();
  }
  const navLinks = document.querySelectorAll('#sidebar-nav a[data-page]');   // data-page only: extra tabs (בית/עוד) don't shift the index
  const key = name === 'profile-detail' ? 'profiles' : name;
  const idx = map[key];
  if (idx !== undefined) navLinks[idx]?.classList.add('active');
  if (name === 'gcal') { setTimeout(() => { gcalInitPage(); }, 50); }
  if (name === 'productions') { try { renderProductions(); } catch(_) {} }
  refreshAll();
}

// ===== SWIPE NAV =====
// Horizontal finger swipe on the page area switches between tabs.
// RTL: swipe-left = next tab, swipe-right = previous tab.
(function setupSwipeNav() {
  const BIZ_TABS   = ['productions','income','expenses','schedule','installments','workshops','proposals','contracts','students','dashboard'];
  const MUSIC_TABS = ['released','sketches'];
  const MIN_DX = 70;        // min horizontal distance (px)
  const MAX_DT = 600;       // max swipe duration (ms)
  const MAX_DY_RATIO = 0.6; // |dy| must be < 60% of |dx|

  let sx = 0, sy = 0, st = 0, tracking = false;

  function isInteractive(el) {
    let n = el;
    while (n && n !== document.body && n.nodeType === 1) {
      const tag = n.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || tag === 'CANVAS' || tag === 'BUTTON') return true;
      if (n.isContentEditable) return true;
      if (n.id === 'sidebar-nav' || n.id === 'music-nav') return true;
      if (n.id === 'business-sidebar' || n.id === 'music-sidebar') return true;
      if (n.classList && n.classList.contains('modal') && n.classList.contains('open')) return true;
      const cs = getComputedStyle(n);
      if ((cs.overflowX === 'auto' || cs.overflowX === 'scroll') && n.scrollWidth > n.clientWidth + 4) return true;
      n = n.parentNode;
    }
    return false;
  }

  function activeCtx() {
    const mm = document.getElementById('music-main');
    if (mm && getComputedStyle(mm).display !== 'none') {
      const a = document.querySelector('#music-nav a.active');
      return { list: MUSIC_TABS, current: a?.dataset.mpage, fn: 'showMusicPage' };
    }
    const bm = document.getElementById('business-main');
    if (bm && getComputedStyle(bm).display !== 'none') {
      const a = document.querySelector('#sidebar-nav a.active');
      return { list: BIZ_TABS, current: a?.dataset.page, fn: 'showPage' };
    }
    return null;
  }

  document.addEventListener('touchstart', (e) => {
    if (e.touches.length !== 1) { tracking = false; return; }
    if (isInteractive(e.target)) { tracking = false; return; }
    const t = e.touches[0];
    sx = t.clientX; sy = t.clientY; st = Date.now();
    tracking = true;
  }, { passive: true });

  document.addEventListener('touchmove', (e) => {
    if (!tracking) return;
    if (e.touches.length !== 1) { tracking = false; return; }
    const t = e.touches[0];
    const dy = Math.abs(t.clientY - sy);
    const dx = Math.abs(t.clientX - sx);
    if (dy > 24 && dy > dx) tracking = false; // vertical scroll wins
  }, { passive: true });

  document.addEventListener('touchend', (e) => {
    if (!tracking) return;
    tracking = false;
    const t = e.changedTouches[0];
    const dx = t.clientX - sx;
    const dy = t.clientY - sy;
    const dt = Date.now() - st;
    if (dt > MAX_DT) return;
    if (Math.abs(dx) < MIN_DX) return;
    if (Math.abs(dy) > Math.abs(dx) * MAX_DY_RATIO) return;

    const ctx = activeCtx();
    if (!ctx || !ctx.current) return;
    const idx = ctx.list.indexOf(ctx.current);
    if (idx < 0) return;
    // RTL: dx>0 (swipe right) = next-on-the-left; dx<0 (swipe left) = previous-on-the-right.
    const newIdx = idx + (dx > 0 ? 1 : -1);
    if (newIdx < 0 || newIdx >= ctx.list.length) return;

    try { if (window.haptic) window.haptic.tap(); } catch(_) {}
    try { window[ctx.fn](ctx.list[newIdx]); } catch(_) {}
  }, { passive: true });
})();

// ===== MONTH =====
function changeMonth(dir) {
  curMonth += dir;
  if (curMonth > 11) { curMonth = 0; curYear++; }
  if (curMonth < 0) { curMonth = 11; curYear--; }
  refreshAll();
}

function setMonthLabels() {
  const lbl = MONTHS_HE[curMonth] + ' ' + curYear;
  ['lbl-dash','lbl-income','lbl-expenses','lbl-sessions'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.textContent = lbl;
  });
}

