    + '<div class="fz-big"><div class="k"><button onclick="changeMonth(1)">‹</button>' + MONTHS_HE[curMonth] + '<button onclick="changeMonth(-1)">›</button></div><div class="n">' + fmtMoney(o.totalPaid) + '</div></div>'
    + '<div class="fz-say">' + say + '</div>';
