    + (f.editing && last && f.onDelete ? '<button class="spf-link danger" onclick="spFlowDelete()">' + (f.deleteLabel || 'מחיקה') + '</button>' : '')
    + (f.editing && !last ? '<button class="spf-save2" onclick="spFlowSave()">שמור עכשיו</button>' : '')
    + '<button class="spf-next" onclick="' + (last ? 'spFlowSave()' : 'spFlowNext()') + '">' + (last ? 'שמירה' : (st.optional && !val ? 'דלג' : 'הבא')) + '</button></div>';
  try { const ae = document.activeElement; if (ae && ae !== document.body && ae.blur) ae.blur(); } catch (_) {}
  const inp = document.getElementById('spf-in');
