// ══════════ WEEKLY BODY PHOTO — album with date + weight burned in ══════════
// Stored device-local (own key, NOT in the sync payload) — photos are
// heavy and belong to this phone. Oldest photos are dropped first if
// storage runs out.
const MPT_PHOTO_KEY = 'body_photos';
function _mptPhotos() {
  try { return JSON.parse(localStorage.getItem(MPT_PHOTO_KEY) || '[]') || []; } catch (_) { return []; }
}
function _mptPhotosSave(arr) {
  // Always write — including an EMPTY array (deleting the last photo
  // must persist; the old while(arr.length) loop skipped that write).
  for (;;) {
    try { localStorage.setItem(MPT_PHOTO_KEY, JSON.stringify(arr)); return true; }
    catch (e) {
      if (!arr.length) return false;
      arr.shift();   // quota — drop oldest and retry
    }
  }
}
function _mptDaysAgo(d) {
  return Math.round((new Date(_mpbToday() + 'T12:00:00') - new Date(d + 'T12:00:00')) / 86400000);
}
function _mptDaysAgoTxt(d) {
  const n = _mptDaysAgo(d);
  return n <= 0 ? 'היום' : n === 1 ? 'אתמול' : 'לפני ' + n + ' ימים';
}
function _mptRenderPhotos() {
  const el = document.getElementById('mpt-photo-body');
  if (!el) return;
  const ph = _mptPhotos();
  const last = ph.length ? ph[ph.length - 1] : null;
  const due = !last || _mptDaysAgo(last.d) >= 7;
  let html = '<div class="mp-sub" style="margin-bottom:10px">פעם בשבוע, אותה תאורה ואותה זווית — והשינוי ייראה בעיניים. התאריך והמשקל נטבעים על התמונה.</div>'
    + '<button class="btn ' + (due ? 'btn-primary' : 'btn-ghost') + '" style="width:100%" onclick="mptBodyPhotoStart()">'
    + (last ? ('צלם תמונה חדשה' + (due ? ' — הגיע הזמן' : '')) : 'צלם את תמונת ההתחלה') + '</button>';
  if (ph.length) {
    html += '<div class="mpt-album">' + ph.slice().reverse().map(p =>
      '<div class="mpt-album-item" onclick="mptBodyPhotoView(\'' + p.id + '\')">'
      + '<img src="' + p.img + '" alt=""/>'
      + '<span>' + p.d.split('-').reverse().slice(0, 2).join('.') + (p.kg ? ' · ' + p.kg + ' ק״ג' : '') + '</span></div>'
    ).join('') + '</div>';
  }
  el.innerHTML = html;
}
// Native-first photo grab: on builds that carry the Capacitor Camera
// plugin this uses the real iOS sheet (rock-solid; the WKWebView photo
// picker is flaky). Falls back to the web file input otherwise.
function _mptGrabPhoto(fileInputId, onImg) {
  const Cam = window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.Camera;
  if (Cam && Cam.getPhoto) {
    Cam.getPhoto({
      quality: 82, allowEditing: false, resultType: 'dataUrl', source: 'PROMPT',
      promptLabelHeader: 'תמונה', promptLabelPhoto: 'מהספרייה',
      promptLabelPicture: 'צלם עכשיו', promptLabelCancel: 'בטל'
    }).then(r => {
      if (!r || !r.dataUrl) return;
      const img = new Image();
      img.onload = () => onImg(img);
      img.onerror = () => toast('לא הצלחתי לקרוא את התמונה');
      img.src = r.dataUrl;
    }).catch(() => {});   // user cancelled — silent
    return;
  }
  const inp = document.getElementById(fileInputId);
  if (inp) inp.click();
}
function _mptFileToImg(ev, onImg) {
  const f = ev.target.files && ev.target.files[0];
  if (!f) return;
  toast('⏳ מעבד תמונה…');
  const img = new Image();
  const url = URL.createObjectURL(f);
  img.onload = function() { URL.revokeObjectURL(url); ev.target.value = ''; onImg(img); };
  img.onerror = function() {
    URL.revokeObjectURL(url); ev.target.value = '';
    toast('לא הצלחתי לקרוא את התמונה — נסה תמונה אחרת');
  };
  img.src = url;
}
window.mptBodyPhotoStart = function() { _mptGrabPhoto('mpt-bodyphoto-file', _mptProcessBodyImage); };
window.mptBodyPhotoPicked = function(ev) { _mptFileToImg(ev, _mptProcessBodyImage); };
function _mptProcessBodyImage(img) {
  const MAX = 720;
  const sc = Math.min(1, MAX / Math.max(img.width, img.height));
  const c = document.createElement('canvas');
  c.width = Math.round(img.width * sc);
  c.height = Math.round(img.height * sc);
  const ctx = c.getContext('2d');
  ctx.drawImage(img, 0, 0, c.width, c.height);
  // Burn date + latest weight into the frame — his spec: the photo
  // itself carries the number of the moment it was taken.
  const st = _mptState();
  const kg = st.weights.length ? st.weights[st.weights.length - 1].kg : 0;
  const today = _mpbToday();
  const label = today.split('-').reverse().join('.') + (kg ? '  ·  ' + kg + ' ק״ג' : '');
  const barH = Math.max(34, Math.round(c.height * 0.055));
  ctx.fillStyle = 'rgba(0,0,0,0.55)';
  ctx.fillRect(0, c.height - barH, c.width, barH);
  ctx.fillStyle = '#fff';
  ctx.font = '700 ' + Math.round(barH * 0.5) + 'px Heebo, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(label, c.width / 2, c.height - barH / 2);
  const ph = _mptPhotos();
  ph.push({ id: genId(), d: today, kg: kg || 0, img: c.toDataURL('image/jpeg', 0.62) });
  while (ph.length > 60) ph.shift();
  const ok = _mptPhotosSave(ph);
  toast(ok ? '📸 נשמר לאלבום' : 'אין מקום בזיכרון — מחק תמונות ישנות');
  _mptRenderPhotos();
  try { _mptRenderToday(); } catch (_) {}
}
let _mptPhotoView = null;
window.mptBodyPhotoView = function(id) {
  const p = _mptPhotos().find(x => x.id === id);
  if (!p) return;
  _mptPhotoView = id;
  const im = document.getElementById('bodyphoto-full');
  const cap = document.getElementById('bodyphoto-cap');
  if (im) im.src = p.img;
  if (cap) cap.textContent = p.d.split('-').reverse().join('.') + (p.kg ? ' · ' + p.kg + ' ק״ג' : '');
  openModal('bodyphoto');
};
window.mptBodyPhotoDel = function() {
  if (!_mptPhotoView) return;
  if (!confirm('למחוק את התמונה הזו מהאלבום?')) return;
  _mptPhotosSave(_mptPhotos().filter(x => x.id !== _mptPhotoView));
  _mptPhotoView = null;
  closeModal('bodyphoto');
  _mptRenderPhotos();
  try { _mptRenderToday(); } catch (_) {}
};

// ── The AI coach — real Gemini, riding the app's existing ai_api_key ──
function _mptCoachContext() {
  const st = _mptState();
  const wk = _mpbWeekKey();
  const w = st.weights;
  const recent7 = [];
  for (let k = 0; k < 7; k++) {
    const key = _mpbDayKey(new Date(Date.now() - k * 86400000));
    const e = st.health[key];
    if (e) recent7.push({ date: key, steps: e.steps || 0, cal: e.cal || 0 });
  }
  return {
    height_cm: st.body.height || null,
    goal_weight_kg: st.body.goalWeight || null,
    goal_date: st.body.goalDate || null,
    weight_log_recent: w.slice(-10),
    weight_start: w[0] || null,
    workouts_this_week: Number(st.workouts[wk]) || 0,
    steps_calories_last7: recent7,
    daily_targets: { steps: st.healthTargets.steps || null, calories: st.healthTargets.cal || null, protein_g: _mptProteinTarget(st), workouts_per_week: st.healthTargets.workouts || null },
    current_written_plan: (st.plan && st.plan.text) ? { text: st.plan.text, updated_at: st.plan.updatedAt || null } : null,
    food_diary_today: (function() {
      const items = st.meals[_mpbToday()] || [];
      if (!items.length) return null;
      return {
        eaten_cal: items.reduce((s, i) => s + (Number(i.cal) || 0), 0),
        eaten_protein_g: items.reduce((s, i) => s + (Number(i.protein) || 0), 0),
        items: items.map(i => i.name).slice(0, 25)
      };
    })(),
    life_north_star: st.northStar || ''
  };
}
// Resilient HTTP for the coach: prefer Capacitor's NATIVE http layer
// (bypasses WKWebView CORS/fetch-patch issues that surface as the
// generic "Load failed"), falling back to browser fetch on web.
async function _mptHttp(method, url, bodyObj) {
  const CH = window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.CapacitorHttp;
  if (CH && CH.request) {
    const r = await CH.request({
      url, method,
      headers: { 'Content-Type': 'application/json' },
      data: bodyObj || undefined
    });
    let j = r.data;
    if (typeof j === 'string') { try { j = JSON.parse(j); } catch (_) { j = {}; } }
    return { ok: r.status >= 200 && r.status < 300, status: r.status, json: j || {} };
  }
  const res = await fetch(url, {
    method,
    headers: bodyObj ? { 'content-type': 'application/json' } : undefined,
    body: bodyObj ? JSON.stringify(bodyObj) : undefined
  });
  return { ok: res.ok, status: res.status, json: await res.json().catch(() => ({})) };
}
// Model discovery with hard fallbacks — never lets a failed list call
// kill the conversation.
async function _mptModel() {
  const cached = localStorage.getItem('gemini_model');
  if (cached) return cached;
  try {
    const r = await _mptHttp('GET', 'https://generativelanguage.googleapis.com/v1beta/models?key=' + encodeURIComponent(getAIKey()));
    if (r.ok) {
      const all = (r.json.models || []).filter(m => (m.supportedGenerationMethods || []).includes('generateContent'));
      const pref = [/gemini-2\.5-flash$/, /gemini-2\.0-flash$/, /flash/];
      for (const re of pref) {
        const m = all.find(x => re.test(x.name));
        if (m) { localStorage.setItem('gemini_model', m.name); return m.name; }
      }
      if (all[0]) { localStorage.setItem('gemini_model', all[0].name); return all[0].name; }
    }
  } catch (_) {}
  return 'models/gemini-2.0-flash';
}

const MPT_COACH_SYSTEM = 'אתה המאמן האישי של אליאור — מפיק מוזיקלי ישראלי שהחליט לשנות את החיים שלו, בריאותית וכלכלית. '
  + 'אתה מאמן כושר ותזונה: ישיר, חם, דוחף אבל בגובה העיניים. עברית בלבד. תשובות קצרות ופרקטיות (עד ~6 שורות אלא אם ביקש תוכנית מלאה). '
  + 'תמיד תתבסס על הנתונים שלו (JSON מצורף). אם חסר נתון קריטי (גיל, רמת פעילות, פציעות) — שאל שאלה אחת קצרה. '
  + 'אתה לא רופא: בכל נושא רפואי אמיתי תפנה לרופא, בלי להיות רובוטי. '
  + 'כשהוא מעדכן שקילה או אימון — תגיב לזה. תחגוג ניצחונות קטנים, ותהיה כן כשאין התקדמות. '
  + 'יש לו באפליקציה יומן תזונה: הוא מתעד ארוחות (טקסט/צילום) והנתונים של היום מגיעים אליך ב-JSON (food_diary_today). תתייחס למה שהוא באמת אכל — תשבח בחירות טובות, תציע תיקונים קונקרטיים, ותשים לב לחלבון. '
  + 'סנכרון עם האפליקציה: כשאתה קובע או מעדכן המלצה ליעדים — קלוריות ביום, חלבון יומי (גרם), צעדים ביום ו/או אימונים בשבוע — הוסף בסוף התשובה שורה נפרדת בפורמט המדויק: #SET cal=1800 protein=140 steps=10000 workouts=3 (רק הערכים שהמלצת עליהם). האפליקציה תקלוט את השורה ותעדכן את הלוחות אוטומטית. אל תשתמש בפורמט הזה בשום מצב אחר. '
  + 'תוכנית כתובה: יש בדף כרטיס קבוע "התוכנית מהמאמן" שמציג את התוכנית הכתובה שלך. בכל פעם שאתה בונה או מעדכן לו תוכנית (תזונה, צעדים, אימונים, שקילה) — הוסף אחרי שורת ה-#SET בלוק בפורמט המדויק: שורה שמכילה רק #PLAN, אחריה התוכנית עצמה (5–10 שורות תמציתיות ומסודרות: תזונה יומית, צעדים, מבנה שבוע האימונים, שקילה ומעקב), ואז שורה שמכילה רק #END. הבלוק לא מוצג בצ׳אט — הוא נשמר ומחליף את התוכנית הכתובה בדף, אז כתוב אותו שלם ועומד בפני עצמו, לא "כמו שאמרנו". אם current_written_plan קיים ב-JSON — זו התוכנית הנוכחית שלו; עדכן אותה רק כשיש שינוי אמיתי.';

function _mptRenderCoach() {
  const thread = document.getElementById('mpt-coach-thread');
  const sug = document.getElementById('mpt-coach-suggest');
  const nokey = document.getElementById('mpt-coach-nokey');
  const inputRow = document.getElementById('mpt-coach-inputrow');
  if (!thread) return;
  const st = _mptState();
  const hasKey = typeof getAIKey === 'function' && !!getAIKey();

  if (!hasKey) {
    thread.innerHTML = '';
    if (sug) sug.innerHTML = '';
    if (inputRow) inputRow.style.display = 'none';
    if (nokey) nokey.innerHTML =
      '<div class="mpt-nokey">'
      + '<div style="font-weight:800;margin-bottom:6px">חיבור חד-פעמי למאמן</div>'
      + '<div style="font-size:12.5px;color:var(--text-muted);line-height:1.6;margin-bottom:10px">המאמן רץ על Google Gemini (חינם). אותו מפתח משמש גם את העוזרת החכמה באפליקציה — מגדירים פעם אחת וזהו.<br>1. היכנס ל-<b>aistudio.google.com/apikey</b><br>2. צור מפתח (Create API key)<br>3. הדבק כאן:</div>'
      + '<div style="display:flex;gap:8px"><input type="password" id="mpt-key-in" placeholder="AIza..." style="flex:1;padding:10px 12px;border:1.5px solid var(--border);border-radius:10px;background:var(--surface2);color:var(--text);font-size:13px;direction:ltr"/>'
      + '<button class="btn btn-primary btn-sm" onclick="mptSaveKey()">שמור</button></div></div>';
    return;
  }
  if (nokey) nokey.innerHTML = '';
  if (inputRow) inputRow.style.display = 'flex';

  const chat = st.healthChat;
  if (!chat.length) {
    thread.innerHTML = '<div class="mp-empty" style="padding:10px 0">ספר למאמן איפה אתה עומד — או בחר שאלה מוכנה למטה.</div>';
  } else {
    thread.innerHTML = chat.map(m =>
      '<div class="mpt-msg ' + (m.role === 'user' ? 'me' : 'coach') + '">' + _escape(m.text).replace(/\n/g, '<br>') + '</div>'
    ).join('');
    thread.scrollTop = thread.scrollHeight;
  }
  if (sug) {
    const qs = ['תבנה לי תוכנית מלאה — תזונה, צעדים ואימונים', 'תסתכל מה אכלתי היום — תן פידבק', 'אני מתחיל אימונים — איך משלבים את זה בתוכנית?', 'תסתכל על השקילות שלי — איך אני מתקדם?'];
    sug.innerHTML = qs.map(q => '<button class="mpt-chip" onclick="mptCoachAsk(this.dataset.q)" data-q="' + q + '">' + q + '</button>').join('');
  }
}
window.mptSaveKey = function() {
  const inp = document.getElementById('mpt-key-in');
  const v = (inp && inp.value || '').trim();
  if (!v) { toast('הדבק מפתח קודם'); return; }
  if (typeof setAIKey === 'function') setAIKey(v);
  toast('✓ המאמן מחובר');
  _mptRenderCoach();
};
window.mptCoachAsk = function(q) {
  const inp = document.getElementById('mpt-coach-input');
  if (inp) inp.value = q;
  mptCoachSend();
};
let _mptCoachBusy = false;
window.mptCoachSend = async function() {
  if (_mptCoachBusy) return;
  const inp = document.getElementById('mpt-coach-input');
  const text = (inp && inp.value || '').trim();
  if (!text) return;
  const st = _mptState();
  st.healthChat.push({ role: 'user', text });
  if (st.healthChat.length > 30) st.healthChat = st.healthChat.slice(-30);
  mpSave(st);
  if (inp) inp.value = '';
  _mptRenderCoach();
  const thread = document.getElementById('mpt-coach-thread');
  if (thread) {
    const t = document.createElement('div');
    t.className = 'mpt-msg coach thinking'; t.id = 'mpt-thinking'; t.textContent = 'חושב…';
    thread.appendChild(t); thread.scrollTop = thread.scrollHeight;
  }
  _mptCoachBusy = true;
  const sendBtn = document.getElementById('mpt-coach-send');
  if (sendBtn) sendBtn.disabled = true;
  try {
    const sys = MPT_COACH_SYSTEM + '\n\n## הנתונים של אליאור (JSON):\n' + JSON.stringify(_mptCoachContext());
    const contents = st.healthChat.slice(-16).map(m => ({
      role: m.role === 'user' ? 'user' : 'model',
      parts: [{ text: m.text }]
    }));
    const payload = {
      systemInstruction: { parts: [{ text: sys }] },
      contents,
      generationConfig: { temperature: 0.6, maxOutputTokens: 8192 }
    };
    let model = await _mptModel();
    // Gemini 2.5 spends "thinking" tokens inside maxOutputTokens and can
    // truncate the visible answer mid-sentence — turn thinking off there.
    if (/2\.5/.test(model)) payload.generationConfig.thinkingConfig = { thinkingBudget: 0 };
    let r = await _mptHttp('POST', 'https://generativelanguage.googleapis.com/v1beta/' + model + ':generateContent?key=' + encodeURIComponent(getAIKey()), payload);
    if (!r.ok && (r.status === 404 || r.status === 400)) {
      // Cached model may be stale/wrong — reset and retry once on a known model.
      localStorage.removeItem('gemini_model');
      model = 'models/gemini-2.0-flash';
      r = await _mptHttp('POST', 'https://generativelanguage.googleapis.com/v1beta/' + model + ':generateContent?key=' + encodeURIComponent(getAIKey()), payload);
    }
    const data = r.json;
    let reply;
    if (!r.ok) reply = '⚠️ ' + (data?.error?.message || ('שגיאה ' + r.status));
    else reply = (data.candidates?.[0]?.content?.parts || []).map(p => p.text).join('\n') || '…';

    // #PLAN…#END protocol — the coach's written program, saved to the
    // permanent "התוכנית מהמאמן" card. Parsed BEFORE #SET so a missing
    // #END can't swallow anything we append below.
    let planSaved = false;
    const planM = reply.match(/#PLAN\s*\n([\s\S]*?)(?:\n\s*#END\b|$)/i);
    if (planM) {
      const planText = planM[1].replace(/#SET[^\n]*/gi, '').trim();
      if (planText) {
        st.plan = { text: planText, updatedAt: new Date().toISOString().slice(0, 10) };
        planSaved = true;
      }
      reply = reply.replace(/#PLAN[\s\S]*?(?:#END\b|$)/i, '').trim();
    }
    // #SET protocol — the coach updates the app's targets itself.
    const setM = reply.match(/#SET\s+([^\n]+)/i);
    if (setM) {
      const calM = setM[1].match(/cal\s*=\s*(\d{3,5})/i);
      const stepsM = setM[1].match(/steps\s*=\s*(\d{3,6})/i);
      const wM = setM[1].match(/workouts?\s*=\s*(\d{1,2})/i);
      const prM = setM[1].match(/protein\s*=\s*(\d{2,3})/i);
      let applied = [];
      if (calM)   { st.healthTargets.cal   = parseInt(calM[1], 10);   applied.push(st.healthTargets.cal.toLocaleString('he-IL') + ' קק״ל'); }
      if (prM)    { st.healthTargets.protein = parseInt(prM[1], 10);  applied.push(st.healthTargets.protein + ' ג׳ חלבון'); }
      if (stepsM) { st.healthTargets.steps = parseInt(stepsM[1], 10); applied.push(st.healthTargets.steps.toLocaleString('he-IL') + ' צעדים'); }
      if (wM)     { st.healthTargets.workouts = parseInt(wM[1], 10);  applied.push(st.healthTargets.workouts + ' אימונים בשבוע'); }
      reply = reply.replace(/#SET[^\n]*/i, '').trim();
      if (applied.length) reply += '\n\n✅ עדכנתי את היעדים שלך באפליקציה: ' + applied.join(' · ');
    }
    if (planSaved) reply += '\n\n📋 התוכנית המלאה נשמרה בדף — בכרטיס "התוכנית מהמאמן".';
    st.healthChat.push({ role: 'coach', text: reply });
    if (st.healthChat.length > 30) st.healthChat = st.healthChat.slice(-30);
    mpSave(st);
  } catch (e) {
    st.healthChat.push({ role: 'coach', text: '⚠️ בעיית חיבור (' + e.message + '). נסה שוב — ואם זה חוזר, בדוק שהמפתח תקין בהגדרות העוזרת.' });
    mpSave(st);
  } finally {
    _mptCoachBusy = false;
    if (sendBtn) sendBtn.disabled = false;
    document.getElementById('mpt-thinking')?.remove();
    _mptRenderCoach();
    // Everything the coach set must be visible immediately — the plan
    // card, the food budget and the week table all resync.
    try { _mptRenderPlan(); } catch (_) {}
    try { _mptRenderFood(); } catch (_) {}
    try { _mptRenderWeekChips(); } catch (_) {}
  }
};

// ══════════ GOAL TAB ══════════
function _mptRenderGoal(id) {
  const el = document.getElementById('mpt-goal-body');
  if (!el) return;
  const st = _mptState();
  const g = st.goals.find(x => x.id === id);
  if (!g) { el.innerHTML = '<div class="mp-empty">היעד לא נמצא</div>'; return; }
  const idEsc = String(g.id).replace(/'/g, "\\'");
  const done = g.steps.filter(s => s.done).length;
  const pct = g.steps.length ? Math.round((done / g.steps.length) * 100) : (g.done ? 100 : 0);

  el.innerHTML =
    '<div class="table-card mp-card mpt-accent-card">'
    + '<div class="mpt-goal-head">'
    +   '<div style="flex:1;min-width:0"><div class="mpt-goal-title' + (g.done ? ' done' : '') + '">' + _escape(g.title) + '</div>'
    +   '<div class="mp-sub" style="margin:4px 0 0">' + (g.date ? 'עד ' + g.date.split('-').reverse().join('/') : 'בלי תאריך יעד — כדאי לקבוע') + '</div></div>'
    +   '<button class="mpx-move-go" onclick="mptGoalDone(\'' + idEsc + '\')">' + (g.done ? 'החזר לפעיל' : 'סמן שהושג') + '</button>'
    + '</div>'
    + '<div class="mp-bar-wrap" style="margin-top:12px"><div class="mp-bar-head"><span class="mp-bar-name">התקדמות</span><span class="mp-bar-nums">' + done + '/' + g.steps.length + ' · ' + pct + '%</span></div>'
    + '<div class="mp-bar-track"><div class="mp-bar-fill" style="width:' + pct + '%;background:' + (pct >= 100 ? 'var(--green)' : 'var(--accent)') + '"></div></div></div>'
    + '<div class="mp-target-row" style="grid-template-columns:1fr;margin-top:12px"><div class="form-group" style="margin-bottom:0"><label>עד מתי</label>'
    + '<input type="month" value="' + (g.date || '') + '" onchange="mptGoalDate(\'' + idEsc + '\', this.value)"/></div></div>'
    + '</div>'

    + '<div class="table-card mp-card">'
    + '<div class="mp-section-title">אבני דרך</div>'
    + '<div class="mp-sub">תפרק את היעד לצעדים קטנים — כל ✓ מקרב.</div>'
    + (g.steps.length ? g.steps.map(s => {
        const sEsc = String(s.id).replace(/'/g, "\\'");
        return '<div class="mp-goal-row ' + (s.done ? 'done' : '') + '">'
          + '<button class="mp-goal-check ' + (s.done ? 'done' : '') + '" onclick="mptStepToggle(\'' + idEsc + '\',\'' + sEsc + '\')">'
          + '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="4 12 10 18 20 6"/></svg></button>'
          + '<div class="mp-goal-title">' + _escape(s.text) + '</div>'
          + '<button class="row-icon-btn" onclick="mptStepDel(\'' + idEsc + '\',\'' + sEsc + '\')" aria-label="מחק">'
          + '<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><use href="#ic-trash"/></svg></button></div>';
      }).join('') : '<div class="mp-empty">עוד אין אבני דרך</div>')
    + '<div class="mp-add-goal" style="margin-top:10px">'
    + '<input type="text" id="mpt-step-in" placeholder="אבן דרך חדשה…" onkeydown="if(event.key===\'Enter\'){event.preventDefault();mptStepAdd(\'' + idEsc + '\');}"/>'
    + '<button class="btn btn-primary btn-sm" onclick="mptStepAdd(\'' + idEsc + '\')">+ הוסף</button></div>'
    + '</div>'

    + '<div class="table-card mp-card">'
    + '<div class="mp-section-title">התוכנית שלי</div>'
    + '<textarea class="mp-textarea" rows="5" placeholder="איך אני מגיע לזה? מה הצעד הבא? מה עוצר אותי?" oninput="mptGoalNotes(\'' + idEsc + '\', this.value)">' + _escape(g.notes || '') + '</textarea>'
    + '</div>'

    + '<button class="prod-delete-link" onclick="mptGoalDelete(\'' + idEsc + '\')" style="margin-top:4px"><svg class="icon"><use href="#ic-trash"/></svg> מחק יעד</button>';
}
window.mptGoalDone = function(id) {
  const st = _mptState();
  const g = st.goals.find(x => x.id === id); if (!g) return;
  g.done = !g.done;
  mpSave(st);
  if (g.done && window.haptic) window.haptic.success();
  if (g.done) toast('🎉 יעד הושג! ענק.');
  mptRenderAll();
};
window.mptGoalDate = function(id, v) {
  const st = _mptState();
  const g = st.goals.find(x => x.id === id); if (!g) return;
  g.date = v || '';
  mpSave(st);
};
window.mptGoalNotes = function(id, v) {
  clearTimeout(_mpTimers['gnotes-' + id]);
  _mpTimers['gnotes-' + id] = setTimeout(() => {
    const st = _mptState();
    const g = st.goals.find(x => x.id === id); if (!g) return;
    g.notes = v;
    mpSave(st);
  }, 600);
};
window.mptStepAdd = function(gid) {
  const inp = document.getElementById('mpt-step-in');
  const text = (inp && inp.value || '').trim();
  if (!text) return;
  const st = _mptState();
  const g = st.goals.find(x => x.id === gid); if (!g) return;
  g.steps.push({ id: genId(), text, done: false });
  mpSave(st);
  _mptRenderGoal(gid);
  if (window.haptic) window.haptic.tap();
};
window.mptStepToggle = function(gid, sid) {
  const st = _mptState();
  const g = st.goals.find(x => x.id === gid); if (!g) return;
  const s = g.steps.find(x => x.id === sid); if (!s) return;
  s.done = !s.done;
  mpSave(st);
  if (s.done && window.haptic) window.haptic.success();
  _mptRenderGoal(gid);
};
window.mptStepDel = function(gid, sid) {
  const st = _mptState();
  const g = st.goals.find(x => x.id === gid); if (!g) return;
  g.steps = g.steps.filter(x => x.id !== sid);
  mpSave(st);
  _mptRenderGoal(gid);
};
window.mptGoalDelete = function(id) {
  if (!confirm('למחוק את היעד לגמרי?')) return;
  const st = _mptState();
  st.goals = st.goals.filter(x => x.id !== id);
  mpSave(st);
  mptGo('health');
};

// ══════════ PROCESS TAB extras ══════════
function _mptRenderGoalsOverview() {
  const card = document.getElementById('mpt-goals-overview-card');
  const el = document.getElementById('mpt-goals-overview');
  if (!card || !el) return;
  const st = _mptState();
  if (!st.goals.length) { card.style.display = 'none'; return; }
  card.style.display = '';
  const nowKey = _mpbMonthKeySafe(new Date());
  el.innerHTML = st.goals.map(g => {
    const done = g.steps.filter(s => s.done).length;
    const pct = g.done ? 100 : (g.steps.length ? Math.round((done / g.steps.length) * 100) : 0);
    const late = g.date && !g.done && g.date < nowKey;
    const idEsc = String(g.id).replace(/'/g, "\\'");
    return '<div class="mpt-ov-row" onclick="mptGo(\'goal:' + idEsc + '\')">'
      + '<div class="mpt-ov-top"><span class="mpt-ov-name' + (g.done ? ' done' : '') + '">' + _escape(g.title) + '</span>'
      + '<span class="mpt-ov-meta">' + (g.done ? '✓ הושג' : (g.date ? (late ? 'באיחור · ' : 'עד ') + g.date.split('-').reverse().join('/') : pct + '%')) + '</span></div>'
      + '<div class="mp-bar-track" style="height:6px"><div class="mp-bar-fill" style="width:' + pct + '%;background:' + (g.done ? 'var(--green)' : late ? 'var(--red)' : 'var(--accent)') + '"></div></div>'
      + '</div>';
  }).join('');
}

// Re-categorize every pending TX + every confirmed expense currently
// sitting on 'אחר' (or with no category) using the latest dictionary
// + user-trained map. Doesn't touch entries the user already moved
// to a real category — that's a deliberate choice they made.
window.txReclassifyAll = function() {
  let pendCount = 0, expCount = 0;

  // Pending queue
  const pending = txList();
  pending.forEach(t => {
    if ((!t.category || t.category === 'אחר') && t.merchant && t.merchant !== 'תנועה ללא שם') {
      const g = _txGuessCategory(t.merchant);
      if (g.cat !== 'אחר') { t.category = g.cat; t.icon = g.icon; pendCount++; }
    }
  });
  if (pendCount) txSaveAll(pending);

  // Confirmed expenses
  const expenses = load('expenses');
  expenses.forEach(e => {
    if ((!e.category || e.category === 'אחר') && e.description) {
      const g = _txGuessCategory(e.description);
      if (g.cat !== 'אחר') { e.category = g.cat; expCount++; }
    }
  });
  if (expCount) save('expenses', expenses);

  if (window.haptic) window.haptic[(pendCount + expCount) ? 'success' : 'tap']();
  const total = pendCount + expCount;
  if (total === 0) toast('הכל כבר מסווג');
  else toast('✓ סווגו ' + total + ' פריטים (' + pendCount + ' ממתינים, ' + expCount + ' הוצאות)');
  if (typeof renderExpenses === 'function') renderExpenses();
};
window.txCopyShortcutURL = async function() {
  // Matches the current Shortcut spec: amount + merchant as separate
  // sub-properties of the Transaction variable. User pastes this then
  // taps each blue token a second time to pick the field.
  const url = 'ravidstudio://wallet?amount=[Amount]&merchant=[Merchant]';
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(url);
      toast('הקישור הועתק');
    }
  } catch (_) { toast('לא הצלחתי להעתיק'); }
};

// Capacitor App.appUrlOpen — fires when the app is opened/foregrounded
// via the ravidstudio:// URL scheme (set up via iOS Shortcuts).
(function _txAttachUrlListener() {
  // iOS re-delivers the launch URL on every cold start AND on
  // appUrlOpen, so de-dupe needs to survive across app restarts.
  // Persist a small ring buffer of processed URLs to localStorage.
  const DEDUPE_MS = 5 * 60 * 1000; // 5 minutes
  function _wasProcessed(url) {
    try {
      const arr = JSON.parse(localStorage.getItem('_tx_processed_urls') || '[]');
      const now = Date.now();
      return arr.some(x => x.u === url && (now - x.t) < DEDUPE_MS);
    } catch (_) { return false; }
  }
  function _markProcessed(url) {
    try {
      const now = Date.now();
      let arr = JSON.parse(localStorage.getItem('_tx_processed_urls') || '[]');
      arr.push({ u: url, t: now });
      arr = arr.filter(x => (now - x.t) < DEDUPE_MS);
      if (arr.length > 60) arr = arr.slice(-60);
      localStorage.setItem('_tx_processed_urls', JSON.stringify(arr));
    } catch (_) {}
  }

  function handleUrl(url) {
    if (!url) return;
    if (_wasProcessed(url)) {
      try { if (typeof _txDiagPush === 'function') _txDiagPush('url-dupe', url, 'skipped — already processed'); } catch (_) {}
      return;
    }
    _markProcessed(url);
    try { if (typeof _txDiagPush === 'function') _txDiagPush('url-received', url, ''); } catch (_) {}

    try {
      const u = new URL(url);
      const host = (u.host || u.hostname || '').toLowerCase();
      // v594 Siri / Shortcuts: ravidstudio://free · ://today · ://add-event
      if (host === 'free' || host === 'today' || host === 'add-event' || host === 'event') {
        const q = k => u.searchParams.get(k) || '';
        appWhenReady(() => {
          chooseMode('business');
          if (host === 'today') { showPage('schedule'); try { goScheduleToday(); } catch (_) {} return; }
          if (host === 'free') {
            const o = window._freeOpt = window._freeOpt || { from: 600, range: 'next', min: 3, count: 3 };
            const f = /^(\d{1,2}):?(\d{2})?$/.exec(q('from')); if (f) o.from = (+f[1]) * 60 + (+(f[2] || 0));
            if (q('hours')) o.min = Math.max(1, Math.min(8, +q('hours') || 3));
            if (/^\d{4}-\d{2}-\d{2}$/.test(q('date'))) { o.range = 'date'; o.date = q('date'); } else if (['this', 'next', 'month'].indexOf(q('range')) >= 0) o.range = q('range');
            if (q('count')) o.count = Math.max(1, Math.min(4, +q('count') || 3));
            showPage('schedule'); setTimeout(freeTimesOpen, 250); return;
          }
          showPage('schedule'); setTimeout(() => spFlowScheduleAdd(/^\d{4}-\d{2}-\d{2}$/.test(q('date')) ? q('date') : undefined), 250);
        });
        return;
      }
      if (host === 'offer' || host === 'slot') {
        const t = u.searchParams.get('text') || u.searchParams.get('body') || '';
        try { localStorage.setItem('offer_diag', JSON.stringify({ at: Date.now(), len: t.length, head: t.slice(0, 160) })); } catch (_) {}
        offerWhenReady(t);
        return;
      }
      if (host !== 'wallet' && host !== 'expense' && host !== 'tx') {
        try { if (typeof _txDiagPush === 'function') _txDiagPush('url-ignored', url, 'host=' + host); } catch (_) {}
        return;
      }

      // Accept multiple URL shapes (we don't know yet what iOS Shortcuts
      // exposes; build for any of them):
      //   ravidstudio://wallet?text=<freetext>                ← v1
      //   ravidstudio://wallet?amount=5&merchant=Aroma         ← structured
      //   ravidstudio://wallet?amount=5&merchant=Aroma&date=2026-06-21
      //   ravidstudio://wallet?json=<urlencoded JSON>          ← bulk
      const dec = v => { if (!v) return ''; try { return decodeURIComponent(v); } catch (_) { return v; } };

      const amountRaw   = u.searchParams.get('amount');
      const merchantRaw = u.searchParams.get('merchant') || u.searchParams.get('store') || u.searchParams.get('name');
      const dateRaw     = u.searchParams.get('date');
      const categoryRaw = u.searchParams.get('category') || u.searchParams.get('cat');
      const jsonRaw     = u.searchParams.get('json') || u.searchParams.get('data');
      const textRaw     = u.searchParams.get('text') || u.searchParams.get('body');

      // 1) Structured JSON wins if present
      if (jsonRaw) {
        try {
          const obj = JSON.parse(dec(jsonRaw));
          if (obj && typeof obj === 'object') {
            txIngestStructured({
              amount:   Number(obj.amount || obj.Amount || obj.value || 0) || 0,
              merchant: String(obj.merchant || obj.Merchant || obj.store || obj.name || '').trim(),
              date:     String(obj.date     || obj.Date     || '').trim() || null,
              category: String(obj.category || obj.cat      || '').trim() || null,
              raw:      dec(jsonRaw)
            });
            return;
          }
        } catch (_) { /* fall through to other paths */ }
      }

      // 2) Individual structured params (any subset). Pass the RAW
      //    amount string through — _txParseAmount handles the iOS
      //    locale format (₪5.00 / $1,234.56 / etc.) that breaks
      //    a naive parseFloat.
      const amountStr   = dec(amountRaw   || '').trim();
      const merchantStr = dec(merchantRaw || '').trim();
      const aClean = _txParseAmount(amountStr);
      const haveStructured = aClean > 0 || merchantStr.length > 0;
      if (haveStructured) {
        txIngestStructured({
          amount:   amountStr,  // raw — txIngestStructured re-parses with currency-aware logic
          merchant: merchantStr,
          date:     (dec(dateRaw) || '').trim() || null,
          category: (dec(categoryRaw) || '').trim() || null,
          raw:      'amount=' + amountStr + ' merchant=' + merchantStr
        });
        return;
      }

      // 3) Freetext fallback (current Shortcut Input behaviour)
      if (textRaw) {
        txIngest(dec(textRaw));
      }
    } catch (e) {
      console.warn('tx URL parse failed', url, e);
    }
  }
  function attach() {
    try {
      const App = window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.App;
      if (!App || !App.addListener) return false;
      App.addListener('appUrlOpen', data => handleUrl(data && data.url));
      if (App.getLaunchUrl) {
        App.getLaunchUrl().then(r => { if (r && r.url) handleUrl(r.url); }).catch(() => {});
      }
      return true;
    } catch (_) { return false; }
  }
  if (!attach()) { window.addEventListener('load', () => setTimeout(attach, 300)); }
})();

// ───────── Clipboard fallback (the silent-Shortcut rescue) ─────────
// When iOS runs a Wallet Automation with "Run Without Asking" enabled,
// the "Open URLs" action does NOT bring the app to the foreground —
// the URL is dispatched but if the app is suspended, appUrlOpen never
// fires and getLaunchUrl on next launch returns nothing.
// Workaround: have the Shortcut ALSO Copy-to-Clipboard. Then every
// time the user opens the app, we sniff the clipboard for a wallet-
// shaped payload and ingest it. Clipboard is cleared on success so
// the same payment never gets queued twice.
//
// Recognized clipboard formats:
//   ravidstudio://wallet?amount=5&merchant=Aroma     (the URL itself)
//   #wallet:5,Aroma                                  (short form)
//   #wallet:5|Aroma|2026-06-24                       (short with date)
//   any plain Hebrew/English Wallet notification text — _txParseNotification handles it
window._txDiagLog = window._txDiagLog || [];
function _txDiagPush(kind, raw, result) {
  try {
    window._txDiagLog.unshift({
      ts: new Date().toISOString(),
      kind: kind,
      raw: String(raw || '').slice(0, 240),
      result: result || ''
    });
    if (window._txDiagLog.length > 30) window._txDiagLog.length = 30;
    localStorage.setItem('_tx_diag_log', JSON.stringify(window._txDiagLog));
  } catch (_) {}
}
try {
  const cached = JSON.parse(localStorage.getItem('_tx_diag_log') || '[]');
  if (Array.isArray(cached)) window._txDiagLog = cached;
} catch (_) {}

window._txIngestFromClipboardText = function(text) {
  const raw = String(text || '').trim();
  if (!raw) return { ok: false, reason: 'empty' };
  // 1) Our own URL scheme
  if (/^ravidstudio:\/\/(wallet|expense|tx)/i.test(raw)) {
    try {
      const u = new URL(raw);
      const amount   = u.searchParams.get('amount') || '';
      const merchant = u.searchParams.get('merchant') || u.searchParams.get('store') || u.searchParams.get('name') || '';
      const date     = u.searchParams.get('date') || '';
      const category = u.searchParams.get('category') || u.searchParams.get('cat') || '';
      if (amount || merchant) {
        txIngestStructured({ amount, merchant, date, category, raw: raw });
        _txDiagPush('clipboard-url', raw, '✓ ingested');
        return { ok: true, via: 'url' };
      }
    } catch (e) { /* fall through to freetext */ }
  }
  // 2) Short pipe / comma form: #wallet:5,Aroma or #wallet:5|Aroma|2026-06-24
  const shortM = raw.match(/^#?wallet[:\s]+(.+)$/i);
  if (shortM) {
    const parts = shortM[1].split(/[,|]/).map(s => s.trim());
    if (parts.length >= 1) {
      const amount = parts[0];
      const merchant = parts[1] || '';
      const date = parts[2] || '';
      txIngestStructured({ amount, merchant, date, raw: raw });
      _txDiagPush('clipboard-short', raw, '✓ ingested');
      return { ok: true, via: 'short' };
    }
  }
  // 3) Free-text Wallet notification (Hebrew/English)
  const parsed = _txParseNotification(raw);
  if (parsed && (parsed.amount > 0 || parsed.merchant)) {
    txIngest(raw);
    _txDiagPush('clipboard-text', raw, '✓ parsed: ' + (parsed.merchant || '') + ' / ' + (parsed.amount || ''));
    return { ok: true, via: 'text' };
  }
  _txDiagPush('clipboard-skip', raw, '✗ no wallet pattern matched');
  return { ok: false, reason: 'no-match' };
};

// Read the clipboard. Returns Promise<string|null>. Uses Capacitor's
// Clipboard plugin in the native app, falls back to the browser's
// navigator.clipboard.readText() for web/dev.
async function _txReadClipboard() {
  try {
    const Cap = window.Capacitor && window.Capacitor.Plugins;
    if (Cap && Cap.Clipboard && Cap.Clipboard.read) {
      const r = await Cap.Clipboard.read();
      return r && (r.value || r.text || '') || '';
    }
  } catch (_) {}
  try {
    if (navigator.clipboard && navigator.clipboard.readText) {
      return await navigator.clipboard.readText();
    }
  } catch (_) {}
  return null;
}
async function _txWriteClipboard(value) {
  try {
    const Cap = window.Capacitor && window.Capacitor.Plugins;
    if (Cap && Cap.Clipboard && Cap.Clipboard.write) {
      await Cap.Clipboard.write({ string: String(value || '') });
      return true;
    }
  } catch (_) {}
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(String(value || ''));
      return true;
    }
  } catch (_) {}
  return false;
}

// Dedupe clipboard ingests across the 5-min window
function _txClipboardSeen(raw) {
  try {
    const arr = JSON.parse(localStorage.getItem('_tx_clip_seen') || '[]');
    const now = Date.now();
    const live = arr.filter(x => (now - x.t) < 5 * 60 * 1000);
    if (live.some(x => x.r === raw)) return true;
    live.push({ r: raw, t: now });
    while (live.length > 30) live.shift();
    localStorage.setItem('_tx_clip_seen', JSON.stringify(live));
    return false;
  } catch (_) { return false; }
}

window._txScanClipboard = async function(opts) {
  opts = opts || {};
  const text = await _txReadClipboard();
  if (text == null) {
    _txDiagPush('clipboard-read', '', '✗ clipboard API unavailable');
    return { ok: false, reason: 'no-api' };
  }
  if (!text.trim()) {
    if (opts.verbose) toast('הקליפבורד ריק');
    return { ok: false, reason: 'empty' };
  }
  // Only treat as wallet-shaped if it CLEARLY looks like one — otherwise
  // we'd ingest random copied text. The URL prefix / #wallet form is
  // unambiguous; for freetext we require ₪ / ש"ח / NIS / Apple Pay anchor.
  const t = text.trim();
  const looksWalletShaped = /^ravidstudio:\/\/(wallet|expense|tx)/i.test(t)
    || /^#?wallet[:\s]/i.test(t)
    || /(?:₪|ש"?ח|NIS|ILS|Apple ?Pay)/i.test(t);
  if (!looksWalletShaped) {
    if (opts.verbose) toast('הטקסט בקליפבורד לא נראה כמו תשלום');
    return { ok: false, reason: 'not-wallet' };
  }
  if (_txClipboardSeen(t)) {
    if (opts.verbose) toast('עסקה זו כבר נקלטה');
    return { ok: false, reason: 'dupe' };
  }
  const r = _txIngestFromClipboardText(t);
  if (r && r.ok) {
    // Clear clipboard so the next paste isn't this stale payload
    try { await _txWriteClipboard(''); } catch (_) {}
  }
  return r;
};

// NOTE: There used to be an auto-scan IIFE here that read the
// clipboard on every visibilitychange / appStateChange / resume / load.
// On iOS that triggers the "Paste from …" privacy pill EVERY time the
// app comes to the foreground — even when opening the app cold — which
// made the app feel hijacked. Removed in v337. Clipboard scanning is
// still available on demand via the "סרוק קליפבורד" button inside the
// Wallet Diagnostics modal — same pill, but only when the user asks
// for it.

// ── SPENT expenses page (4.10): one clear story instead of six stacked
// widgets — big "יצא החודש", category circles that filter, a list grouped
// by day like a bank app, one fixed-costs card. Classic skin keeps the old
// layout untouched. ──
let _expCatFilter = 'all';
const _SP_PAL = [['#fdede2', '#e0662f'], ['#dfe7fc', '#4b4fe0'], ['#e6f5ec', '#1f9d55'], ['#f4f1d8', '#8a8a1f'], ['#fbe4ef', '#c2407c'], ['#e3f3f6', '#1d8aa0']];
function _spPal(cat) { let h = 0; String(cat).split('').forEach(c => { h = (h * 31 + c.charCodeAt(0)) | 0; }); return _SP_PAL[Math.abs(h) % _SP_PAL.length]; }
function _spDayLabel(iso) {
  const d = new Date(iso + 'T12:00:00'), t = new Date(); t.setHours(12, 0, 0, 0);
  const diff = Math.round((t - d) / 864e5);
  if (diff === 0) return 'היום';
  if (diff === 1) return 'אתמול';
  return 'יום ' + ['א׳','ב׳','ג׳','ד׳','ה׳','ו׳','ש׳'][d.getDay()] + ', ' + d.getDate() + ' ב' + MONTHS_HE[d.getMonth()].slice(0, 4) + (MONTHS_HE[d.getMonth()].length > 4 ? '׳' : '');
}
// ── Monthly story (4.10): SPENT-style full-screen recap of a month —
// colored slides with one big number each and a little "city" whose
// buildings are the month's categories. Opened from the expenses hero. ──
let _stIdx = 0, _stSlides = [];
function _stCity(cats, colors) {
  const max = Math.max(1, ...cats.map(c => c[1]));
  return '<div class="st-city">' + cats.slice(0, 6).map(([c, v], i) => {
    const hpx = 60 + Math.round(170 * v / max), col = colors[i % colors.length];
    const rows = Math.max(2, Math.floor(hpx / 26));
    return '<div class="st-bld" style="height:' + hpx + 'px;background:' + col + '"><div class="st-win" style="grid-template-rows:repeat(' + rows + ',1fr)">' + '<i></i>'.repeat(rows * 2) + '</div></div>';
  }).join('') + '</div>';
}
window.storyOpen = function() {
  const m = curMonth, y = curYear, mName = MONTHS_HE[m];
  const exps = (load('expenses') || []).filter(e => inCurMonth(e.date));
  const incs = (load('income') || []).filter(i => inCurMonth(i.date) && (i.status || 'pending') === 'paid');
  const out = exps.reduce((t, e) => t + (Number(e.amount) || 0), 0);
  const inn = incs.reduce((t, i) => t + (Number(i.amount) || 0), 0);
  const byCat = {}; exps.forEach(e => { const c = e.category || 'אחר'; byCat[c] = (byCat[c] || 0) + (Number(e.amount) || 0); });
  const cats = Object.entries(byCat).sort((a, b) => b[1] - a[1]);
  const top = cats[0], big = exps.slice().sort((a, b) => b.amount - a.amount)[0];
  const byDay = {}; exps.forEach(e => { const k = String(e.date).slice(0, 10); byDay[k] = (byDay[k] || 0) + (Number(e.amount) || 0); });
  const busiest = Object.entries(byDay).sort((a, b) => b[1] - a[1])[0];
  const net = inn - out;
  const S = [];
  if (!exps.length && !incs.length) { toast('עוד אין מספיק נתונים ל' + mName); return; }
  S.push({ bg: '#cfd05e', k: 'יצא ב' + mName, n: fmtMoney(out), t: 'זה הסכום שעבר בעיר החודש.', art: _stCity(cats, ['#f2efe6', '#e4532f', '#4b4fe0', '#ffffff', '#e4532f', '#4b4fe0']) });
  S.push({ bg: '#dfe7fc', k: 'עסקאות החודש', n: String(exps.length), t: exps.length + ' עסקאות נרשמו ב' + mName + '.', art: '<div class="st-tower"><div class="st-grid">' + Array.from({ length: 40 }, (_, i) => '<i class="' + (i < Math.min(40, exps.length) ? 'on' : '') + '"></i>').join('') + '</div></div>' });
  if (top) S.push({ bg: '#fbf1e5', k: 'הרובע הבולט', n: _escape(top[0]), t: fmtMoney(top[1]) + ' · ' + Math.round(top[1] / Math.max(1, out) * 100) + '% מהחודש', art: _stCity([top], ['#e4532f']) });
  if (big) S.push({ bg: '#dfe7fc', k: 'רכישה אחת בלטה מעל כולן', n: fmtMoney(big.amount), t: _escape(big.description || ''), art: _stCity(cats.length > 1 ? [[0, big.amount], ...cats.slice(1, 5).map(c => [0, c[1] * .5])] : [[0, big.amount]], ['#e4532f', '#f2efe6', '#e4532f', '#ffffff', '#e4532f']) });
  if (busiest) S.push({ bg: '#ffffff', k: 'היום הכי עמוס', n: _spDayLabel(busiest[0]).replace('יום ', ''), t: 'יצאו בו ' + fmtMoney(busiest[1]) + '.', art: '<div class="st-street">' + '<span></span>'.repeat(4) + '</div>' });
  S.push({ bg: net >= 0 ? '#e6f5ec' : '#fdece6', k: 'נכנס מול יצא', n: (net >= 0 ? '+' : '−') + fmtMoney(Math.abs(net)), t: 'נכנסו ' + fmtMoney(inn) + ' · יצאו ' + fmtMoney(out), art: '' });
  S.push({ bg: '#fbf1e5', k: 'הסיכום', n: 'זה היה ' + mName + ' שלך.', t: '', small: true, list: [
    fmtMoney(out) + ' · ' + exps.length + ' עסקאות',
    top ? 'רובע מוביל: ' + top[0] + ' · ' + Math.round(top[1] / Math.max(1, out) * 100) + '%' : '',
    big ? 'הכי גדול: ' + (big.description || '') + ' · ' + fmtMoney(big.amount) : '',
    'נכנס ' + fmtMoney(inn) + ' · נטו ' + (net >= 0 ? '+' : '−') + fmtMoney(Math.abs(net))
  ].filter(Boolean), art: _stCity(cats.length ? cats : [['', 1]], ['#1f9d55', '#ffffff', '#e4532f', '#f2efe6', '#4b4fe0', '#e4532f']) });
  _stSlides = S; _stIdx = 0;
  let ov = document.getElementById('story-ov');
  if (!ov) { ov = document.createElement('div'); ov.id = 'story-ov'; document.body.appendChild(ov); }
  ov.classList.add('open'); _stRender();
};
function _stRender() {
  const ov = document.getElementById('story-ov'); const sl = _stSlides[_stIdx]; if (!ov || !sl) return;
  ov.style.background = sl.bg;
  ov.innerHTML = '<div class="st-top"><div class="st-prog">' + _stSlides.map((_, i) => '<span class="' + (i < _stIdx ? 'done' : i === _stIdx ? 'cur' : '') + '"></span>').join('') + '</div>'
    + '<div class="st-bar"><span class="st-brand">RAVID STUDIO</span><span class="st-ct" dir="ltr">' + String(_stIdx + 1).padStart(2, '0') + ' / ' + String(_stSlides.length).padStart(2, '0') + '</span><button class="st-x" onclick="storyClose()">✕</button></div></div>'
    + '<div class="st-body" onclick="storyNext()"><div class="st-k">' + sl.k + '</div><div class="st-n' + (sl.small ? ' sm' : '') + '">' + sl.n + '</div>'
    + (sl.t ? '<div class="st-t">' + sl.t + '</div>' : '')
    + (sl.list ? '<ul class="st-list">' + sl.list.map(x => '<li>' + _escape(x) + '</li>').join('') + '</ul>' : '')
    + '</div><div class="st-art" onclick="storyNext()">' + (sl.art || '') + '</div>'
    + '<div class="st-nav"><button class="st-back" onclick="storyPrev()">→</button><span class="st-hint">הקשה להמשך</span><button class="st-next" onclick="storyNext()">' + (_stIdx === _stSlides.length - 1 ? 'סיום' : 'הבא') + '</button></div>';
}
window.storyNext = function() { if (_stIdx >= _stSlides.length - 1) return storyClose(); _stIdx++; _stRender(); try { if (window.haptic && window.haptic.light) window.haptic.light(); } catch (_) {} };
window.storyPrev = function() { if (_stIdx > 0) { _stIdx--; _stRender(); } };
window.storyClose = function() { const ov = document.getElementById('story-ov'); if (ov) ov.classList.remove('open'); };
window.expSetCat = function(c) { _expCatFilter = c || 'all'; renderExpenses(); try { if (window.haptic && window.haptic.light) window.haptic.light(); } catch (_) {} };
function renderExpensesSpent() {
  const host = document.getElementById('exp-spent'); if (!host) return;
  const monthExp = (load('expenses') || []).filter(e => inCurMonth(e.date));
  const total = monthExp.reduce((t, e) => t + (Number(e.amount) || 0), 0);
  const unpaid = monthExp.filter(e => !e.paid).length;
  // v584: where the money went — by category; anything unknown counts as food
  // unknown → guess from the name first (a few obvious ones), otherwise food
  const _eguess = d => { d = String(d || ''); return /תספור|מספר|ספר |קוסמטי|ציפורנ/.test(d) ? 'טיפוח' : /דלק|פז|סונול|דור אלון|ten|yellow|חניה|חניון|פנגו|סלופארק|רכבת|רב.?קו|מונית|gett|אוטובוס/i.test(d) ? 'תחבורה'
    : /סופר|שופרסל|רמי לוי|יוחננוף|ויקטורי|אושר עד|מחסני|וולט|wolt|תן ביס|קפה|מאפ|פיצ|בורגר|מסעד|שווארמ|פלאפל/i.test(d) ? 'מזון' : /סופר.?פארם|בית מרקחת|מרקחת|רופא|מכבי|כללית/.test(d) ? 'בריאות' : null; };
  const _ecat = e => { const c = String(e.category || '').trim(); return !c || c === 'אחר' || c === 'כללי' || c === 'לא מסווג' ? (_eguess(e.description) || 'מזון') : c; };
  const _edate = ds => { if (!ds) return ''; const d = new Date(String(ds).slice(0, 10) + 'T12:00:00'); if (isNaN(d)) return ''; const t = new Date(); t.setHours(12, 0, 0, 0);
    const n = Math.round((t - d) / 864e5); return n === 0 ? 'היום' : n === 1 ? 'אתמול' : 'יום ' + 'אבגדהוש'[d.getDay()] + '׳ ' + d.getDate() + '.' + (d.getMonth() + 1); };
  const byCat = {}; monthExp.forEach(e => { const c = _ecat(e); byCat[c] = byCat[c] || { n: 0, sum: 0, guess: 0 }; byCat[c].n++; byCat[c].sum += Number(e.amount) || 0; if (c !== String(e.category || '').trim()) byCat[c].guess++; });
  const cats = Object.keys(byCat).map(k => ({ k, ...byCat[k] })).sort((a, b) => b.sum - a.sum);
  const fcat = window._expCat && byCat[window._expCat] ? window._expCat : null;
  const latest = monthExp.filter(e => !fcat || _ecat(e) === fcat).sort((a, b) => String(b.date).localeCompare(String(a.date)) || String(b.id).localeCompare(String(a.id)));
  const allOpen = !!window._expListOpen;
  const say = unpaid ? (unpaid === 1 ? 'הוצאה אחת עוד לא שולמה' : unpaid + ' הוצאות עוד לא שולמו') : monthExp.length ? 'הכל שולם' : 'עוד אין הוצאות החודש';
  let h = '<div class="fz-ttl">כסף</div>' + '<div class="fz-seg"><button onclick="showPage(\'income\')">נכנס</button><button class="on">יצא</button></div>'
    + '<div class="fz-big"><div class="k"><button onclick="changeMonth(1)">‹</button>' + MONTHS_HE[curMonth] + '<button onclick="changeMonth(-1)">›</button></div><div class="n">' + fmtMoney(total) + '</div></div>'
    + '<div class="fz-say">' + say + '</div>';
  try { if (fcList().length) h += '<button class="fz-link" onclick="showPage(\'fixed\')">' + fzIc('repeat', 'violet') + '<span class="fz-m"><b>הוצאות קבועות</b><small>' + fmtMoney(fcTotal()) + ' בחודש</small></span><span class="fz-ch">‹</span></button>'; } catch (_) {}
  if (cats.length > 1 || (cats.length === 1 && monthExp.length > 1)) {
    const top = cats[0].sum || 1, catOpen = !!window._expCatsOpen;
    h += '<div class="fz-lbl">על מה זה יצא</div><div class="fz-card ex-cats">' + (catOpen ? cats : cats.slice(0, 5)).map(c =>
        '<button class="ex-cat' + (fcat === c.k ? ' on' : '') + '" onclick="window._expCat=window._expCat===\'' + _escape(c.k) + '\'?null:\'' + _escape(c.k) + '\';window._expListOpen=!!window._expCat;renderExpensesSpent()">'
        + '<span class="ex-cat-t"><b>' + _escape(c.k) + '</b><small>' + (c.n === 1 ? 'הוצאה אחת' : c.n + ' הוצאות') + (c.guess ? ' · ' + c.guess + ' לפי ניחוש' : '') + '</small></span>'
        + '<span class="ex-cat-v">' + fmtMoney(c.sum) + '<small>' + Math.round(c.sum / (total || 1) * 100) + '%</small></span>'
        + '<span class="ex-cat-bar"><i style="width:' + Math.max(3, Math.round(c.sum / top * 100)) + '%"></i></span></button>').join('')
      + (cats.length > 5 ? '<button class="fz-more" onclick="window._expCatsOpen=!window._expCatsOpen;renderExpensesSpent()">' + (catOpen ? 'פחות' : 'עוד ' + (cats.length - 5) + ' ›') + '</button>' : '') + '</div>';
  }
  if (latest.length) {
    // v591: the latest charges stay folded until opened (opens by itself when a category is picked)
    const lOpen = !!window._expLatestOpen || !!fcat;
    const lsum = latest.reduce((t, e) => t + (Number(e.amount) || 0), 0);
    h += '<div class="fz-card ex-latest' + (lOpen ? ' open' : '') + '"><button class="ex-lhead" onclick="window._expLatestOpen=!' + (lOpen ? 'true' : 'false') + ';if(!window._expLatestOpen)window._expCat=null;renderExpensesSpent()">'
      + '<span class="ex-cat-t"><b>' + (fcat ? _escape(fcat) : 'הורדות אחרונות') + '</b><small>' + (latest.length === 1 ? 'הוצאה אחת' : latest.length + ' הוצאות') + ' · ' + fmtMoney(lsum) + '</small></span>'
      + '<span class="ex-chev">' + (lOpen ? '⌃' : '⌄') + '</span></button>'
      + (lOpen ? '<div class="ex-lbody">' + latest.map(e =>
        '<button class="fz-row" onclick="expRowTap(\'' + e.id + '\')">' + fzIc('coin', e.paid ? 'violet' : 'sun')
        + '<span class="fz-m"><b>' + _escape(e.description || 'הוצאה') + '</b><small>' + _edate(e.date) + ' · ' + _escape(_ecat(e)) + (e.paid ? '' : ' · לא שולם') + '</small></span>'
        + '<span class="fz-v">' + fmtMoney(e.amount) + '</span></button>').join('')
        + (fcat ? '<button class="fz-more" onclick="window._expCat=null;renderExpensesSpent()">כל ההוצאות</button>' : '') + '</div>' : '')
      + '</div>';
  } else h += '<div class="fz-empty">אין הוצאות ב' + MONTHS_HE[curMonth] + '</div>';
  h += '<div class="fz-foot"><button onclick="bankPasteOpen()">ייבוא מהבנק</button></div>';
  host.innerHTML = h;
  try { fcAskRenderAll(); } catch (_) {}
}
// tap an expense → its actions: mark paid / not paid, edit, delete (6.10)
window.expRowTap = function(id) {
  const e = (load('expenses') || []).find(x => x.id === id); if (!e) return;
  spentSheet(e.description || 'הוצאה', fmtMoney(e.amount) + ' · ' + (e.category || 'אחר') + ' · ' + (e.paid ? 'שולם ✓' : 'עוד לא שולם'), [
    e.paid ? { label: 'סמן שעוד לא שולם', run: () => { toggleExpensePaid(id); toast('סומן: עוד לא שולם'); } }
           : { label: '✓ שולם', pri: true, run: () => { toggleExpensePaid(id); spDone('ההוצאה סומנה כשולמה', fmtMoney(e.amount), e.description || ''); } },
    { label: 'עריכה', run: () => editExpense(id) },
    { label: 'מחיקה', danger: true, run: () => deleteExpense(id) }
  ]);
};
function renderExpenses() {
  // Update the pending-TX inbox above the expense list
  _txRenderInbox();
  if (document.documentElement.getAttribute('data-skin') === 'spent') { try { renderExpensesSpent(); } catch (e) { console.warn('renderExpensesSpent', e); } }
  const expenses   = load('expenses');
  const income     = load('income');
  const plans      = load('plans');
  const recurring  = load('recurring_expenses');

  // הוצאות חוזרות שחלות על החודש הנוכחי
  const curMonthKey = `${curYear}-${String(curMonth+1).padStart(2,'0')}`;
  const activeRecurring = recurring.filter(r => {
    if (r.startMonth > curMonthKey) return false;
    if (r.endMonth && r.endMonth < curMonthKey) return false;
    return true;
  });

  // הכנסות החודש בלבד
  const monthIncome = income.filter(i => inCurMonth(i.date));
  // הוצאות החודש בלבד
  const allExpenses = expenses.filter(e => inCurMonth(e.date));

  // הוצאות קבועות — שולמו / לא שולמו החודש
  const recurPaidAmt   = activeRecurring.filter(r => r.paidMonths && r.paidMonths[curMonthKey]).reduce((s,r) => s + _recAmt(r, curMonthKey), 0);
  const recurUnpaidAmt = activeRecurring.filter(r => !(r.paidMonths && r.paidMonths[curMonthKey])).reduce((s,r) => s + _recAmt(r, curMonthKey), 0);

  // סה"כ הוצאות החודש — כולל הוצאות קבועות
  const totalExpenses = allExpenses.reduce((s,e) => s + Number(e.amount), 0) + recurPaidAmt + recurUnpaidAmt;
  const totalIncome   = monthIncome.reduce((s,i) => s + Number(i.amount), 0);
  const netProfit     = totalIncome - totalExpenses;

  // ── כרטיס "בנק העסק" — רק מה שנכנס ויצא בפועל (שולם) ──
  const paidIncAmt   = monthIncome.filter(i => (i.status||'pending') === 'paid').reduce((s,i) => s + Number(i.amount), 0);
  const paidExpAmt   = allExpenses.filter(e => e.paid).reduce((s,e) => s + Number(e.amount), 0) + recurPaidAmt;
  const totalPaidOut = paidExpAmt;
  const balance      = paidIncAmt - totalPaidOut;
  const isPos        = balance >= 0;

  // גם עבור תצוגה "כמה עוד ממתין"
  const unpaidExpAmt   = allExpenses.filter(e => !e.paid).reduce((s,e) => s + Number(e.amount), 0) + recurUnpaidAmt;
  const totalUnpaidOut = unpaidExpAmt;

  const card = document.getElementById('e-balance-card');
  if (card) {
    const cs = getComputedStyle(document.documentElement);
    card.style.background   = isPos ? cs.getPropertyValue('--balance-pos-bg').trim() : cs.getPropertyValue('--balance-neg-bg').trim();
    card.style.borderColor  = isPos ? cs.getPropertyValue('--balance-pos-border').trim() : cs.getPropertyValue('--balance-neg-border').trim();
    document.getElementById('e-balance').textContent        = (isPos?'':'-') + fmtMoney(Math.abs(balance));
    document.getElementById('e-balance').style.color        = isPos ? 'var(--orange)' : 'var(--red)';
    document.getElementById('e-balance-small').textContent  = (isPos?'':'-') + fmtMoney(Math.abs(balance));
    document.getElementById('e-balance-small').style.color  = isPos ? 'var(--orange)' : 'var(--red)';
    document.getElementById('e-inc-ref').textContent        = fmtMoney(paidIncAmt);
    document.getElementById('e-exp-ref').textContent        = fmtMoney(totalPaidOut);
    document.getElementById('e-balance-sub').textContent    = totalUnpaidOut > 0
      ? `עוד ${fmtMoney(totalUnpaidOut)} ממתין לתשלום החודש`
      : 'כל ההוצאות שולמו החודש 🎉';
  }

  document.getElementById('e-total-inc').textContent = fmtMoney(totalIncome);
  document.getElementById('e-total').textContent     = fmtMoney(totalExpenses);
  const netEl = document.getElementById('e-net');
  netEl.textContent  = (netProfit>=0?'':'-') + fmtMoney(netProfit);
  netEl.style.color  = netProfit >= 0 ? 'var(--green)' : 'var(--red)';

  // ── רשימת פרויקטים ──
  const container = document.getElementById('e-projects-list');
  if (!container) return;

  const catBadge = {'ציוד':'badge-blue','שכירות':'badge-red','חשמל/מים':'badge-orange','תוכנות':'badge-purple','שיווק':'badge-green','תחבורה':'badge-blue'};

  function expensesTableHtml(exps) {
    if (!exps || exps.length === 0)
      return `<div style="font-size:14px;color:var(--text-muted);padding:6px 0">אין הוצאות</div>`;
    return exps.map(e => `
      <div style="display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid var(--border);${e.paid?'opacity:0.5':''}">
        <div style="flex:1;min-width:0">
          <span style="font-size:15px;font-weight:700;${e.paid?'text-decoration:line-through;color:var(--text-muted)':''}">${e.description}</span>
          <span style="font-size:13px;color:var(--text-muted);margin-right:6px">${fmtDate(e.date)}</span>
          <span class="badge ${catBadge[e.category]||'badge-orange'}" style="font-size:11px">${e.category}</span>
        </div>
        <span style="font-size:15px;font-weight:800;white-space:nowrap;${e.paid?'text-decoration:line-through;color:var(--text-muted)':'color:var(--red)'}">-${fmtMoney(e.amount)}</span>
        ${e.paid
          ? `<span class="status-pill paid" onclick="toggleExpensePaid('${e.id}')"><span class="status-dot"></span>שולם</span>`
          : `<button class="status-action" onclick="toggleExpensePaid('${e.id}')">סמן כשולם</button>`}
        <button onclick="deleteExpense('${e.id}')" style="border:none;background:none;color:var(--text-muted);cursor:pointer;font-size:18px;padding:2px 4px">×</button>
      </div>`).join('');
  }

  let html = '';

  // ── הוצאות לפי קטגוריה — קופסה לכל קטגוריה ──
  if (allExpenses.length > 0) {
    const byCat = {};
    allExpenses.forEach(e => {
      const cat = e.category || 'אחר';
      if (!byCat[cat]) byCat[cat] = { items: [], total: 0, unpaid: 0 };
      byCat[cat].items.push(e);
      byCat[cat].total  += Number(e.amount) || 0;
      if (!e.paid) byCat[cat].unpaid += Number(e.amount) || 0;
    });
    // Sort items inside each category — unpaid first, then by date asc
    Object.values(byCat).forEach(b => b.items.sort((a, b) => {
      const ap = a.paid ? 1 : 0, bp = b.paid ? 1 : 0;
      if (ap !== bp) return ap - bp;
      return new Date(a.date) - new Date(b.date);
    }));
    // Sort categories by total amount desc (biggest spending first)
    const sortedCats = Object.entries(byCat).sort((a, b) => b[1].total - a[1].total);
    const _icon = c => (typeof _txCatSvg === 'function' ? _txCatSvg(c) : '💳');
    const expandedSet = (function () {
      try { return new Set(JSON.parse(localStorage.getItem('_exp_cat_open') || '[]')); }
      catch (_) { return new Set(); }
    })();
    html += `
      <div class="exp-cat-grid">
        ${sortedCats.map(([cat, data]) => {
          const open = expandedSet.has(cat);
          const catEsc = String(cat).replace(/'/g, "\\'");
          return `
            <div class="exp-cat-box ${open ? 'open' : ''}">
              <button class="exp-cat-head" onclick="toggleExpCatBox('${catEsc}')">
                <span class="exp-cat-icon">${_icon(cat)}</span>
                <span class="exp-cat-name">${cat}</span>
                <span class="exp-cat-count" title="שולמו / סה״כ"><span style="color:var(--green)">${data.items.filter(e => e.paid).length}</span>/${data.items.length}</span>
                <span class="exp-cat-total">${fmtMoney(data.total)}</span>
                <span class="exp-cat-arrow">${open ? '▴' : '▾'}</span>
              </button>
              <div class="exp-cat-body" style="${open ? '' : 'display:none'}">
                ${data.items.map(e => `
                  <div class="exp-cat-row ${e.paid ? 'paid' : ''}">
                    <div class="exp-cat-row-main">
                      <div class="exp-cat-row-desc">${e.description || '—'}</div>
                      <div class="exp-cat-row-meta">${fmtDate(e.date)}${e.projectName ? ' · ' + e.projectName : ''}</div>
                    </div>
                    <div class="exp-cat-row-amt">-${fmtMoney(e.amount)}</div>
                    <div class="exp-cat-row-actions">
                      ${e.paid
                        ? `<span class="status-pill paid" onclick="toggleExpensePaid('${e.id}')"><span class="status-dot"></span>שולם</span>`
                        : `<button class="status-action" onclick="toggleExpensePaid('${e.id}')">סמן כשולם</button>`}
                      <button class="row-icon-btn" onclick="editExpense('${e.id}')" aria-label="ערוך" title="ערוך — שינוי קטגוריה ילמד את האפליקציה">
                        <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><use href="#ic-edit"/></svg>
                      </button>
                      <button class="row-icon-btn" onclick="deleteExpense('${e.id}')" aria-label="מחק">
                        <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2L5 6"/></svg>
                      </button>
                    </div>
                  </div>`).join('')}
              </div>
            </div>`;
        }).join('')}
      </div>`;
  }

  // ── 🔁 הוצאות קבועות (collapsible box, matches category boxes) ──
  const allRecurring = load('recurring_expenses');
  if (allRecurring.length > 0) {
    const recOpen = (function () {
      try { return localStorage.getItem('_recurring_box_open') === '1'; }
      catch (_) { return false; }
    })();
    // Sum of this month's active recurring expenses, and a paid/total count.
    let recMonthlyTotal = 0, recPaidCount = 0, recActiveCount = 0;
    allRecurring.forEach(r => {
      const isActive = r.startMonth <= curMonthKey && (!r.endMonth || r.endMonth >= curMonthKey);
      if (isActive) {
        recActiveCount++;
        recMonthlyTotal += _recAmt(r, curMonthKey);
        if (r.paidMonths && r.paidMonths[curMonthKey]) recPaidCount++;
      }
    });
    html += `
      <div class="exp-cat-box ${recOpen ? 'open' : ''}" style="margin-top:8px">
        <button class="exp-cat-head" onclick="toggleRecurringBox()">
          <span class="exp-cat-icon"><svg viewBox="0 0 24 24"><use href="#ic-repeat"/></svg></span>
          <span class="exp-cat-name">הוצאות קבועות</span>
          <span class="exp-cat-count" title="שולמו / פעילות החודש"><span style="color:var(--green)">${recPaidCount}</span>/${recActiveCount}</span>
          <span class="exp-cat-total">${fmtMoney(recMonthlyTotal)}</span>
          <span class="exp-cat-arrow">${recOpen ? '▴' : '▾'}</span>
        </button>
        <div class="exp-cat-body" style="${recOpen ? '' : 'display:none'};padding:6px 14px 12px;overflow-x:auto">
        <table style="width:100%;border-collapse:collapse">
          <thead><tr>
            <th>תיאור</th>
            <th>קטגוריה</th>
            <th>סכום חודשי</th>
            <th>מאז</th>
            <th>עד</th>
            <th>החודש</th>
            <th></th>
          </tr></thead>
          <tbody>
            ${allRecurring.map(r => {
              const isPaidThisMonth = !!(r.paidMonths && r.paidMonths[curMonthKey]);
              const isActive = r.startMonth <= curMonthKey && (!r.endMonth || r.endMonth >= curMonthKey);
              const monthAmt = _recAmt(r, curMonthKey);
              const hasOverride = monthAmt !== Number(r.amount);
              return `<tr style="${isPaidThisMonth ? 'opacity:0.55;background:var(--surface2)' : ''}">
                <td style="${isPaidThisMonth?'text-decoration:line-through;color:var(--text-muted)':''};font-weight:600">${r.description}</td>
                <td><span class="badge ${catBadge[r.category]||'badge-orange'}">${r.category}</span></td>
                <td style="font-weight:800;${isPaidThisMonth?'text-decoration:line-through;color:var(--text-muted)':'color:var(--red)'}">
                  -${fmtMoney(monthAmt)}
                  ${hasOverride ? `<div style="font-size:11px;font-weight:600;color:var(--text-muted);margin-top:2px">קבוע: ${fmtMoney(r.amount)}</div>` : ''}
                </td>
                <td style="color:var(--text-muted);font-size:14px">${r.startMonth}</td>
                <td style="color:var(--text-muted);font-size:14px">${r.endMonth || '∞ ללא הגבלה'}</td>
                <td>${isActive ? `<button onclick="toggleRecurringPaid('${r.id}')" style="border:none;border-radius:8px;padding:5px 12px;font-size:13px;font-weight:700;cursor:pointer;${isPaidThisMonth?'background:var(--pill-green-bg);color:var(--pill-green-text)':'background:var(--red-light);color:var(--red)'}">${isPaidThisMonth?'✓ שולם':'שולם'}</button>` : '<span style="color:var(--text-muted);font-size:14px">לא פעיל</span>'}</td>
                <td>
                  <div style="display:flex;gap:5px;align-items:center;flex-wrap:wrap">
                    <button class="row-icon-btn" onclick="editRecurringForMonth('${r.id}')" title="סכום שונה לחודש זה"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><use href="#ic-edit"/></svg></button>
                    <button class="row-icon-btn" onclick="deleteRecurring('${r.id}')" title="מחק לחלוטין"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><use href="#ic-trash"/></svg></button>
                  </div>
                </td>
              </tr>`;
            }).join('')}
          </tbody>
        </table>
        </div>
      </div>`;
  }

  container.innerHTML = html;
}

// ===== RENDER DASHBOARD =====
function renderDashboard() {
  const allIncome  = load('income');
  const allExpenses= load('expenses');
  const clients    = load('clients');
  const now        = new Date();
  const thisYear   = now.getFullYear();
  const thisMonth  = now.getMonth();

  // ── מסנן עזר: הכנסה "שהתקבלה" = status paid ──
  // תואם לחישוב "התקבל בפועל" בדף ההכנסה
  const isPaidInc = i => (i.status || 'pending') === 'paid';

  // ── שנה עד היום ──
  // הכנסות = רק שולמו — מתאים ל-"התקבל בפועל" בדף ההכנסה
  // הוצאות = רק שולמו — מתאים לבקשת המשתמש (מה שיצא בפועל מהבנק)
  const ytdInc  = allIncome.filter(i  => isPaidInc(i) && new Date(i.date).getFullYear() === thisYear);
  const ytdExp  = allExpenses.filter(e => e.paid && new Date(e.date).getFullYear() === thisYear);
  const ytdIncTotal = ytdInc.reduce((s,i) => s + Number(i.amount), 0);
  const ytdExpTotal = ytdExp.reduce((s,e) => s + Number(e.amount), 0);
  const ytdProfit   = ytdIncTotal - ytdExpTotal;

  document.getElementById('stat-ytd-inc').textContent     = fmtMoney(ytdIncTotal);
  document.getElementById('stat-ytd-inc-n').textContent   = ytdInc.length + ' עסקאות שולמו';
  document.getElementById('stat-ytd-exp').textContent     = fmtMoney(ytdExpTotal);
  document.getElementById('stat-ytd-exp-n').textContent   = ytdExp.length + ' עסקאות';
  const profEl = document.getElementById('stat-ytd-profit');
  profEl.textContent  = (ytdProfit < 0 ? '-' : '') + fmtMoney(Math.abs(ytdProfit));
  profEl.className    = 'stat-ytd-val ' + (ytdProfit >= 0 ? 'green' : 'red');
  // זהה את החודש הראשון שיש בו נתונים השנה
  const allDatesThisYear = [
    ...ytdInc.map(i => new Date(i.date).getMonth()),
    ...ytdExp.map(e => new Date(e.date).getMonth())
  ];
  const firstActiveMonth = allDatesThisYear.length > 0 ? Math.min(...allDatesThisYear) : thisMonth;
  const rangeLabel = firstActiveMonth === thisMonth
    ? MONTHS_HE[thisMonth] + ' ' + thisYear
    : MONTHS_HE[firstActiveMonth] + '–' + MONTHS_HE[thisMonth] + ' ' + thisYear;
  document.getElementById('stat-ytd-profit-sub').textContent = rangeLabel;

  // ── ממוצעים — 6 חודשים אחרונים ──
  const last6months = [];
  for (let i = 5; i >= 0; i--) {
    let m = thisMonth - i, y = thisYear;
    while (m < 0) { m += 12; y--; }
    last6months.push({ m, y, lbl: MONTHS_HE[m] });
  }
  // הכנסות = שולמו בלבד; הוצאות = שולמו בלבד
  const inc6 = last6months.map(({m,y}) =>
    allIncome.filter(i => { const d=new Date(i.date); return isPaidInc(i) && d.getFullYear()===y && d.getMonth()===m; })
             .reduce((s,i) => s+Number(i.amount), 0));
  const exp6 = last6months.map(({m,y}) =>
    allExpenses.filter(e => { const d=new Date(e.date); return e.paid && d.getFullYear()===y && d.getMonth()===m; })
               .reduce((s,e) => s+Number(e.amount), 0));

  const avgInc = Math.round(inc6.reduce((s,v)=>s+v,0) / 6);
  const avgExp = Math.round(exp6.reduce((s,v)=>s+v,0) / 6);

  // החודש הכי רווחי (מכל הזמנים, הכנסות שולמו בלבד)
  const profitByMonth = {};
  allIncome.filter(isPaidInc).forEach(i => {
    const d = new Date(i.date);
    const key = `${d.getFullYear()}-${d.getMonth()}`;
    profitByMonth[key] = (profitByMonth[key] || 0) + Number(i.amount);
  });
  allExpenses.filter(e => e.paid).forEach(e => {
    const d = new Date(e.date);
    const key = `${d.getFullYear()}-${d.getMonth()}`;
    profitByMonth[key] = (profitByMonth[key] || 0) - Number(e.amount);
  });
  let bestKey = null, bestVal = -Infinity;
  Object.entries(profitByMonth).forEach(([k,v]) => { if (v > bestVal) { bestVal = v; bestKey = k; } });
  let bestMonthStr = '—';
  if (bestKey) {
    const [by, bm] = bestKey.split('-').map(Number);
    bestMonthStr = `${MONTHS_HE[bm]} ${by} (${fmtMoney(bestVal)})`;
  }

  document.getElementById('stat-avg-inc').textContent     = fmtMoney(avgInc);
  document.getElementById('stat-avg-exp').textContent     = fmtMoney(avgExp);
  document.getElementById('stat-best-month').textContent  = bestMonthStr;
  document.getElementById('stat-active-clients').textContent = clients.filter(c=>c.active).length + ' / ' + clients.length;

  // ── גרף עמודות ──
  const chart = document.getElementById('bar-chart');
  const maxV  = Math.max(...inc6, ...exp6, 1);
  chart.innerHTML = last6months.map(({lbl}, i) => {
    const ih = Math.round((inc6[i]/maxV)*115);
    const eh = Math.round((exp6[i]/maxV)*115);
    return `<div class="bar-group">
      <div class="bar-wrap">
        <div class="bar income" style="height:${ih}px" title="הכנסות שהתקבלו: ${fmtMoney(inc6[i])}"></div>
        <div class="bar expense" style="height:${eh}px" title="הוצאות: ${fmtMoney(exp6[i])}"></div>
      </div>
      <div class="bar-lbl">${lbl.slice(0,3)}</div>
    </div>`;
  }).join('');

  // ── לקוחות מובילים (הכנסות שהתקבלו בלבד) ──
  const clientTotals = {};
  allIncome.filter(isPaidInc).forEach(i => {
    const name = i.clientName || 'ללא לקוח';
    clientTotals[name] = (clientTotals[name] || 0) + Number(i.amount);
  });
  const topClients = Object.entries(clientTotals).sort((a,b)=>b[1]-a[1]).slice(0,5);
  const maxClient  = topClients[0]?.[1] || 1;
  const tcEl = document.getElementById('stat-top-clients');
  tcEl.innerHTML = topClients.length === 0
    ? `<div class="empty-state"><p>אין נתונים</p></div>`
    : `<div style="padding:4px 0">` + topClients.map(([name, total]) => `
      <div class="stat-cat-row">
        <div class="stat-cat-top">
          <div class="stat-cat-name">${name}</div>
          <div class="stat-cat-right"><div class="stat-cat-amount green">${fmtMoney(total)}</div></div>
        </div>
        <div class="stat-cat-bar-wrap"><div class="stat-cat-bar" style="width:${Math.round((total/maxClient)*100)}%;background:var(--green)"></div></div>
      </div>`).join('') + `</div>`;

  // ── הכנסות לפי קטגוריה (שולמו בלבד) / הוצאות לפי קטגוריה (הכל) ──
  function renderCats(data, colorVar, elId) {
    const cats = {};
    data.forEach(r => { const c = r.category || 'כללי'; cats[c] = (cats[c]||0) + Number(r.amount); });
    const sorted = Object.entries(cats).sort((a,b)=>b[1]-a[1]);
    const maxCat = sorted[0]?.[1] || 1;
    const total  = sorted.reduce((s,[,v])=>s+v,0);
    document.getElementById(elId).innerHTML = sorted.length === 0
      ? `<div class="empty-state"><p>אין נתונים</p></div>`
      : `<div style="padding:4px 0">` + sorted.map(([cat, val]) => `
        <div class="stat-cat-row">
          <div class="stat-cat-top">
            <div class="stat-cat-name">${cat}</div>
            <div class="stat-cat-right">
              <div class="stat-cat-pct">${Math.round((val/total)*100)}%</div>
              <div class="stat-cat-amount" style="color:${colorVar}">${fmtMoney(val)}</div>
            </div>
          </div>
          <div class="stat-cat-bar-wrap"><div class="stat-cat-bar" style="width:${Math.round((val/maxCat)*100)}%;background:${colorVar}"></div></div>
        </div>`).join('') + `</div>`;
  }
  renderCats(allIncome.filter(isPaidInc),        'var(--green)', 'stat-inc-cats');
  renderCats(allExpenses.filter(e => e.paid),    'var(--red)',   'stat-exp-cats');

  // ── טבלת פירוט חודשי ──
  const yearSel = document.getElementById('stat-year-sel');
  const allYears = [...new Set([
    ...allIncome.map(i => new Date(i.date).getFullYear()),
    ...allExpenses.map(e => new Date(e.date).getFullYear()),
    thisYear
  ])].sort((a,b) => b-a);
  const selYear = yearSel ? (Number(yearSel.value) || thisYear) : thisYear;
  if (yearSel && yearSel.innerHTML === '') {
    yearSel.innerHTML = allYears.map(y => `<option value="${y}" ${y===selYear?'selected':''}>${y}</option>`).join('');
  }
  const monthlyEl = document.getElementById('stat-monthly-table');
  if (monthlyEl) {
    let yearInc = 0, yearExp = 0;
    const rows = MONTHS_HE.map((mName, mi) => {
      // הכנסות = שולמו בלבד; הוצאות = שולמו בלבד
      const mInc = allIncome.filter(i => { const d=new Date(i.date); return isPaidInc(i) && d.getFullYear()===selYear && d.getMonth()===mi; });
      const mExp = allExpenses.filter(e => { const d=new Date(e.date); return e.paid && d.getFullYear()===selYear && d.getMonth()===mi; });
      const incAmt = mInc.reduce((s,i) => s+Number(i.amount), 0);
      const expAmt = mExp.reduce((s,e) => s+Number(e.amount), 0);
      const net    = incAmt - expAmt;
      yearInc += incAmt; yearExp += expAmt;
      const isEmpty = incAmt === 0 && expAmt === 0;
      const isCur   = mi === thisMonth && selYear === thisYear;
      return { mName, mi, incAmt, expAmt, net, isEmpty, isCur, count: mInc.length };
    });
    const maxInc = Math.max(...rows.map(r => r.incAmt), 1);
    monthlyEl.innerHTML = `
      <table style="width:100%;border-collapse:collapse">
        <thead><tr>
          <th style="text-align:right">חודש</th>
          <th style="text-align:right">הכנסות שהתקבלו</th>
          <th style="text-align:right">הוצאות ששולמו</th>
          <th style="text-align:right">רווח נקי</th>
          <th style="text-align:right">מגמה</th>
        </tr></thead>
        <tbody>
          ${rows.map(r => `
            <tr style="${r.isEmpty?'opacity:0.35':''}${r.isCur?';background:var(--accent-light);font-weight:800':''}" onclick="curYear=${selYear}; curMonth=${r.mi}; refreshAll(); showPage('income');" style="cursor:pointer">
              <td style="font-weight:${r.isCur?'900':'700'};color:${r.isCur?'var(--accent)':'var(--text)'};cursor:pointer">
                ${r.isCur ? '▶ ' : ''}${r.mName}${r.isCur ? ' (עכשיו)' : ''}
              </td>
              <td style="color:var(--green);font-weight:800">${r.incAmt > 0 ? fmtMoney(r.incAmt) : '—'}</td>
              <td style="color:var(--red);font-weight:800">${r.expAmt > 0 ? fmtMoney(r.expAmt) : '—'}</td>
              <td style="font-weight:900;color:${r.net>0?'var(--green)':r.net<0?'var(--red)':'var(--text-muted)'}">${r.incAmt>0||r.expAmt>0 ? ((r.net<0?'-':'')+fmtMoney(Math.abs(r.net))) : '—'}</td>
              <td style="min-width:80px">
                ${r.incAmt > 0 ? `<div style="height:6px;background:var(--green-light);border-radius:3px;overflow:hidden"><div style="height:100%;background:var(--green);width:${Math.round((r.incAmt/maxInc)*100)}%;border-radius:3px"></div></div>` : ''}
              </td>
            </tr>`).join('')}
          <tr style="border-top:2px solid var(--border);font-weight:900;background:var(--surface2)">
            <td>סה"כ ${selYear}</td>
            <td style="color:var(--green)">${fmtMoney(yearInc)}</td>
            <td style="color:var(--red)">${fmtMoney(yearExp)}</td>
            <td style="color:${yearInc-yearExp>=0?'var(--green)':'var(--red)'}">${(yearInc-yearExp<0?'-':'')+fmtMoney(Math.abs(yearInc-yearExp))}</td>
            <td></td>
          </tr>
        </tbody>
      </table>`;
  }

  // ── פעולות אחרונות (ממוינות לפי תאריך אמיתי) ──
  const allTx = [
    ...allIncome.filter(isPaidInc).map(i => ({...i, txType:'income'})),
    ...allExpenses.map(e => ({...e, txType:'expense'}))
  ].sort((a,b) => new Date(b.date)-new Date(a.date)).slice(0,10);

  document.getElementById('recent-list').innerHTML = allTx.length === 0
    ? `<div class="empty-state"><div class="ei"><svg><use href="#ic-list"/></svg></div><p>אין פעולות עדיין</p></div>`
    : allTx.map(tx => `
      <div class="recent-item">
        <div class="recent-item-r">
          <div class="ri-icon ${tx.txType==='income'?'in':'out'}">${tx.txType==='income'?'💰':'📤'}</div>
          <div>
            <div class="ri-name">${tx.description}</div>
            <div class="ri-date">${fmtDate(tx.date)}${tx.clientName?' · '+tx.clientName:''}</div>
          </div>
        </div>
        <div class="ri-amount" style="color:${tx.txType==='income'?'var(--green)':'var(--red)'}">
          ${tx.txType==='income'?'+':'-'}${fmtMoney(tx.amount)}
        </div>
      </div>`).join('');
}

// ===== INSTALLMENTS =====

function calcInstallment() {
  const total = parseFloat(document.getElementById('pl-total').value) || 0;
  const count = parseInt(document.getElementById('pl-count').value) || 0;
  const per = count > 0 ? Math.round(total / count) : 0;
  document.getElementById('pl-calc').textContent = fmtMoney(per);
}

function addDays(dateStr, days) {
  const d = new Date(dateStr);
  d.setDate(d.getDate() + days);
  return d.toISOString().split('T')[0];
}

function addMonths(dateStr, months) {
  const d = new Date(dateStr);
  d.setMonth(d.getMonth() + months);
  return d.toISOString().split('T')[0];
}

function generatePaymentDates(startDate, count, freq) {
  const dates = [];
  for (let i = 0; i < count; i++) {
    if (freq === 'monthly')   dates.push(addMonths(startDate, i));
    else if (freq === 'weekly')    dates.push(addDays(startDate, i * 7));
    else if (freq === 'biweekly')  dates.push(addDays(startDate, i * 14));
  }
  return dates;
}

function openPlanModal() {
  openModal('plan');
  populateClientSel('pl-client');
  document.getElementById('pl-start').value = new Date().toISOString().split('T')[0];
  ['pl-project','pl-notes'].forEach(id => document.getElementById(id).value = '');
  document.getElementById('pl-total').value = '';
  document.getElementById('pl-count').value = '';
  document.getElementById('pl-calc').textContent = '₪0';
}

function savePlan() {
  const project = document.getElementById('pl-project').value.trim();
  const clientId = document.getElementById('pl-client').value;
  const total = parseFloat(document.getElementById('pl-total').value);
  const count = parseInt(document.getElementById('pl-count').value);
  const startDate = document.getElementById('pl-start').value;
  const freq = document.getElementById('pl-freq').value;

  if (!project || !total || !count || !startDate) { toast('נא למלא שדות חובה'); return; }

  const clients = load('clients');
  const client = clients.find(c => c.id === clientId);
  const perPayment = Math.round(total / count);
  const dates = generatePaymentDates(startDate, count, freq);

  const payments = dates.map((date, i) => ({
    id: genId(),
    index: i + 1,
    dueDate: date,
    amount: i === count - 1 ? total - perPayment * (count - 1) : perPayment, // last covers rounding
    paid: false,
    paidDate: null,
    incomeId: null
  }));

  const planId = genId();
  const planObj = {
    id: planId,
    project,
    clientId: clientId || '',
    clientName: client ? client.name : '',
    totalAmount: total,
    count,
    freq,
    notes: document.getElementById('pl-notes').value.trim(),
    payments,
    createdAt: new Date().toISOString()
  };

  // צור הכנסה ממתינה לכל תשלום — כך יופיע ברשימת ההכנסות ויחושב בכל האתר
  const income = load('income');
  planObj.payments.forEach(p => {
    const entry = {
      id: genId(),
      date: p.dueDate,
      amount: p.amount,
      clientId: clientId || '',
      clientName: client ? client.name : '',
      description: `${project} — תשלום ${p.index} מתוך ${count}`,
      category: 'הפקה מוזיקלית',
      status: 'pending',
      fromPlan: planId,
      fromPaymentId: p.id
    };
    p.incomeId = entry.id;
    income.push(entry);
  });

  const plans = load('plans');
  plans.push(planObj);
  save('plans', plans);
  save('income', income);
  closeModal('plan');
  toast('✓ תוכנית תשלום נוצרה');
  refreshAll();
}

function markPaymentPaid(planId, paymentId) {
  const plans = load('plans');
  const plan = plans.find(p => p.id === planId);
  if (!plan) return;
  const payment = plan.payments.find(p => p.id === paymentId);
  if (!payment || payment.paid) return;

  const today = new Date().toISOString().split('T')[0];
  payment.paid = true;
  payment.paidDate = today;

  // עדכן את ערך ההכנסה הקיים ל"שולם"
  const income = load('income');
  const entry = income.find(i => i.id === payment.incomeId);
  if (entry) {
    entry.status = 'paid';
    entry.date   = today;
  } else {
    // fallback — צור חדש אם לא קיים (תוכניות ישנות)
    const newEntry = {
      id: genId(), date: today, amount: payment.amount,
      clientId: plan.clientId, clientName: plan.clientName,
      description: `${plan.project} — תשלום ${payment.index} מתוך ${plan.count}`,
      category: 'הפקה מוזיקלית', status: 'paid',
      fromPlan: planId, fromPaymentId: paymentId
    };
    payment.incomeId = newEntry.id;
    income.push(newEntry);
  }

  save('plans', plans);
  save('income', income);

  _spCongrats('התשלום התקבל', payment && payment.amount ? fmtMoney(payment.amount) : '', plan && plan.clientName ? plan.clientName : '');
  refreshAll();
}


// v600: installments — each payment: mark paid, or a friendly WhatsApp nudge
window.planRemindText = function(plan, p) {
  const first = String(plan.clientName || '').split(' ')[0];
  const d = new Date(p.dueDate + 'T12:00:00'), t = new Date(); t.setHours(12, 0, 0, 0);
  const n = Math.round((d - t) / 864e5);
  const when = n === 0 ? 'היום' : n === 1 ? 'מחר' : n > 1 ? 'ב-' + d.getDate() + '.' + (d.getMonth() + 1) : 'מ-' + d.getDate() + '.' + (d.getMonth() + 1);
  return 'היי' + (first ? ' ' + first : '') + ', תזכורת קטנה — תשלום ' + p.index + ' מתוך ' + plan.count + ' על ' + plan.project + ' (' + fmtMoney(p.amount) + ') ' + (n < 0 ? 'שהיה ' + when : when) + '. תודה!';
};
window.planStepTap = function(planId, paymentId) {
  const plan = (load('plans') || []).find(x => x.id === planId); if (!plan) return;
  const p = plan.payments.find(x => x.id === paymentId); if (!p) return;
  const d = new Date(p.dueDate + 'T12:00:00');
  const sub = fmtMoney(p.amount) + ' · ' + d.getDate() + '.' + (d.getMonth() + 1) + ' · ' + (p.paid ? 'שולם' : 'עוד לא שולם');
  const acts = p.paid ? [{ label: 'בעצם עוד לא שולם', run: () => markPaymentUnpaid(planId, paymentId) }]
    : [{ label: 'שולם', pri: true, run: () => markPaymentPaid(planId, paymentId) },
       { label: 'תזכורת בוואטסאפ', run: () => {
          const c = (load('clients') || []).find(x => x.id === plan.clientId) || _clientByName(plan.clientName);
          const ph = c && c.phone ? _waPhone(c.phone) : '';
          const txt = encodeURIComponent(planRemindText(plan, p));
          if (ph) window.open('https://wa.me/' + ph + '?text=' + txt, '_blank');
          else askClientPhone(plan.clientName || 'הלקוח', () => { const c2 = _clientByName(plan.clientName); if (c2 && c2.phone) window.open('https://wa.me/' + _waPhone(c2.phone) + '?text=' + txt, '_blank'); });
        } }];
  spentSheet(plan.project + ' · תשלום ' + p.index + ' מתוך ' + plan.count, sub, acts);
};
// a phone notification on each installment's day (10:00): "רן · תשלום 2 מתוך 4 · היום"
let _plTimer = 0;
function planScheduleNotif() {
  clearTimeout(_plTimer);
  _plTimer = setTimeout(async () => {
    try {
      if (!(window.Capacitor && Capacitor.isNativePlatform && Capacitor.isNativePlatform())) return;
      const LN = Capacitor.Plugins && Capacitor.Plugins.LocalNotifications; if (!LN) return;
      let old = []; try { old = JSON.parse(localStorage.getItem('pl_notif_ids') || '[]'); } catch (_) {}
      if (old.length) await LN.cancel({ notifications: old.map(id => ({ id })) }).catch(() => {});
      localStorage.setItem('pl_notif_ids', '[]');
      const prefs = (typeof getNotifPrefs === 'function') ? getNotifPrefs() : {};
      if (prefs.enabled === false || prefs.income === false) return;
      const now = new Date(), out = [];
      const hid = s => 691000000 + Math.abs(String(s).split('').reduce((h, c) => (h * 31 + c.charCodeAt(0)) | 0, 7)) % 899999;
      (load('plans') || []).forEach(plan => (plan.payments || []).forEach(p => {
        if (p.paid || !p.dueDate) return;
        const at = new Date(p.dueDate + 'T10:00:00'); if (at <= now) return;
        out.push({ id: hid(plan.id + p.id), title: (plan.clientName || plan.project) + ' · תשלום ' + p.index + ' מתוך ' + plan.count, body: fmtMoney(p.amount) + ' היום · ' + plan.project, schedule: { at, allowWhileIdle: true }, sound: _notifSound() });
      }));
      const list = out.sort((a, b) => a.schedule.at - b.schedule.at).slice(0, 24);
      if (list.length) await LN.schedule({ notifications: list }).catch(() => {});
      localStorage.setItem('pl_notif_ids', JSON.stringify(list.map(n => n.id)));
    } catch (_) {}
  }, 1800);
}
document.addEventListener('DOMContentLoaded', () => setTimeout(planScheduleNotif, 5000));
document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'hidden') planScheduleNotif(); });

function markPaymentUnpaid(planId, paymentId) {
  const plans = load('plans');
  const plan = plans.find(p => p.id === planId);
  if (!plan) return;
  const payment = plan.payments.find(p => p.id === paymentId);
  if (!payment || !payment.paid) return;

  // החזר את ערך ההכנסה ל"ממתין" עם תאריך הפירעון המקורי
  const income = load('income');
  const entry = income.find(i => i.id === payment.incomeId);
  if (entry) {
    entry.status = 'pending';
    entry.date   = payment.dueDate;
    save('income', income);
  }
  payment.paid = false;
  payment.paidDate = null;

  save('plans', plans);
  toast('תשלום סומן כלא שולם');
  refreshAll();
}

function deletePlan(planId) {
  const plan = load('plans').find(p => p.id === planId);
  if (!plan) return;
  const paidCount = plan.payments.filter(p => p.paid).length;
  const msg = paidCount > 0
    ? `למחוק את תוכנית "${plan.project}"?\n${paidCount} תשלומים ששולמו כבר יימחקו גם מדף ההכנסות.`
    : `למחוק את תוכנית "${plan.project}"?`;
  if (!confirm(msg)) return;
  // מחק את כל ערכי ההכנסה שנוצרו מהתוכנית (שולמו + ממתינים)
  const planIncomeIds = plan.payments.filter(p => p.incomeId).map(p => p.incomeId);
  if (planIncomeIds.length > 0) {
    save('income', load('income').filter(i => !planIncomeIds.includes(i.id)));
  }
  save('plans', load('plans').filter(p => p.id !== planId));
  toast(`✅ תוכנית "${plan.project}" נמחקה`);
  refreshAll();
}

function getPaymentStatus(payment) {
  if (payment.paid) return 'paid';
  const today = new Date(); today.setHours(0,0,0,0);
  const due = new Date(payment.dueDate);
  return due < today ? 'overdue' : 'pending';
}

function renderInstallments() {
  const plans = load('plans');
  const today = new Date(); today.setHours(0,0,0,0);

  let totalReceived = 0, totalOverdue = 0, thisMonth = 0, activePlans = 0;

  plans.forEach(plan => {
    const allPaid = plan.payments.every(p => p.paid);
    if (!allPaid) activePlans++;
    plan.payments.forEach(p => {
      if (p.paid) {
        totalReceived += p.amount;
      } else {
        const due = new Date(p.dueDate);
        if (due < today) totalOverdue += p.amount;
        if (due.getFullYear() === curYear && due.getMonth() === curMonth) thisMonth += p.amount;
      }
    });
  });

  document.getElementById('pl-active').textContent = activePlans;
  document.getElementById('pl-received').textContent = fmtMoney(totalReceived);
  document.getElementById('pl-this-month').textContent = fmtMoney(thisMonth);
  document.getElementById('pl-overdue').textContent = fmtMoney(totalOverdue);

  const container = document.getElementById('plans-list');
  if (!container) return;

  if (plans.length === 0) {
    container.innerHTML = `<div class="empty-state"><div class="ei"><svg><use href="#ic-calendar"/></svg></div><p>אין תוכניות תשלום עדיין. לחץ "+ תוכנית תשלום חדשה" כדי להתחיל.</p></div>`;
    return;
  }

  const freqLabel = { monthly:'חודשי', weekly:'שבועי', biweekly:'כל שבועיים' };

  container.innerHTML = plans.map(plan => {
    const paidCount = plan.payments.filter(p => p.paid).length;
    const paidAmount = plan.payments.filter(p => p.paid).reduce((s,p) => s+p.amount, 0);
    const progress = Math.round((paidCount / plan.count) * 100);
    const allDone = paidCount === plan.count;

    const stepsHtml = plan.payments.map(p => {
      const status = getPaymentStatus(p);
      const icons = {
        paid:    '<svg><use href="#ic-check-circle"/></svg>',
        pending: '<svg><use href="#ic-hourglass"/></svg>',
        overdue: '<svg><use href="#ic-alert-circle"/></svg>'
      };
      const labels = { paid:'שולם', pending:'צפוי', overdue:'באיחור' };
      const d = new Date(p.dueDate);
      const dateStr = d.toLocaleDateString('he-IL', {day:'2-digit', month:'2-digit'});
      const clickFn = p.paid
        ? `markPaymentUnpaid('${plan.id}','${p.id}')`
        : `markPaymentPaid('${plan.id}','${p.id}')`;
      return `
        <div class="payment-step ${status}" onclick="if(document.documentElement.getAttribute('data-skin')==='spent'){planStepTap('${plan.id}','${p.id}')}else{${clickFn}}" title="${p.paid ? 'לחץ לביטול' : 'לחץ לסימון כשולם'}">
          <div class="ps-icon">${icons[status]}</div>
          <div class="ps-num">תשלום ${p.index}</div>
          <div class="ps-date">${dateStr}</div>
          <div class="ps-amount ${status}">${fmtMoney(p.amount)}</div>
          <div class="ps-badge ${status}">${labels[status]}</div>
        </div>
      `;
    }).join('');

    return `
      <div class="plan-card">
        <div class="plan-card-top">
          <div>
            <div class="plan-title">${plan.project}${allDone ? ' · הושלם' : ''}</div>
            <div class="plan-client">${plan.clientName || 'ללא לקוח'}</div>
          </div>
          <button class="btn btn-danger btn-sm" onclick="deletePlan('${plan.id}')"><svg class="icon"><use href="#ic-trash"/></svg></button>
        </div>
        <div class="plan-meta">
          <div class="plan-meta-item"><svg class="icon"><use href="#ic-coin-bag"/></svg> סה"כ: <strong>${fmtMoney(plan.totalAmount)}</strong></div>
          <div class="plan-meta-item"><svg class="icon"><use href="#ic-calendar"/></svg> תדירות: <strong>${freqLabel[plan.freq]}</strong></div>
          <div class="plan-meta-item"><svg class="icon"><use href="#ic-check-circle"/></svg> שולם: <strong>${fmtMoney(paidAmount)}</strong></div>
          <div class="plan-meta-item"><svg class="icon"><use href="#ic-hourglass"/></svg> נותר: <strong>${fmtMoney(plan.totalAmount - paidAmount)}</strong></div>
        </div>
        <div class="plan-progress-wrap">
          <div class="plan-progress-label">
            <span>התקדמות</span>
            <span>${paidCount} / ${plan.count} תשלומים · ${progress}%</span>
          </div>
          <div class="plan-progress-bar">
            <div class="plan-progress-fill" style="width:${progress}%"></div>
          </div>
        </div>
        <div class="payment-timeline">${stepsHtml}</div>
      </div>
    `;
  }).join('');
}

