// סגירת tooltip בלחיצה בחוץ
document.addEventListener('click', function(e) {
  if (!e.target.closest('.mc-dot')) {
    document.querySelectorAll('.mc-dot.active-tip').forEach(d => d.classList.remove('active-tip'));
  }
});

function onDotTap(el) {
  const wasActive = el.classList.contains('active-tip');
  document.querySelectorAll('.mc-dot.active-tip').forEach(d => d.classList.remove('active-tip'));
  if (!wasActive) el.classList.add('active-tip');
}

function renderTopClients(monthEntries) {
  const listEl = document.getElementById('top-clients-list');
  const monthEl = document.getElementById('top-clients-month');
  if (!listEl) return;

  const monthName = new Date(curYear, curMonth, 1).toLocaleDateString('he-IL', {month:'long', year:'numeric'});
  if (monthEl) monthEl.textContent = monthName;

  const clients = load('clients');
  const totals = {};
  monthEntries.forEach(i => {
    const cId = i.clientId || '__unknown__';
    if (!totals[cId]) totals[cId] = { paid: 0, pending: 0, count: 0 };
    if (i.paid) totals[cId].paid += +i.amount;
    else        totals[cId].pending += +i.amount;
    totals[cId].count++;
  });

  const ranked = Object.entries(totals).map(([cId, t]) => {
    const c = clients.find(x => x.id === cId);
    return { id: cId, name: c?.name || (cId === '__unknown__' ? 'לא ידוע' : 'לקוח נמחק'), photo: c?.photo, ...t, total: t.paid + t.pending };
  }).sort((a,b) => b.total - a.total).slice(0, 5);

  if (ranked.length === 0) {
    listEl.innerHTML = `<div style="text-align:center;padding:30px 20px;color:var(--text-muted);font-size:13px">אין הכנסות החודש</div>`;
    return;
  }

  const max = ranked[0].total || 1;
  listEl.innerHTML = ranked.map((c, i) => {
    const pct = (c.total / max) * 100;
    const medal = ['🥇','🥈','🥉'][i] || `${i+1}.`;
    return `
      <div style="margin-bottom:${i<ranked.length-1?'14px':'0'}">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;gap:8px">
          <div style="display:flex;align-items:center;gap:8px;min-width:0;flex:1">
            ${c.photo ? `<img src="${c.photo}" style="width:24px;height:24px;border-radius:50%;object-fit:cover;flex-shrink:0"/>` : `<span style="font-size:14px;flex-shrink:0">${medal}</span>`}
            <span style="font-size:14px;font-weight:800;color:var(--text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${c.name}</span>
            <span style="font-size:11px;color:var(--text-muted);font-weight:600">${c.count} עסקאות</span>
          </div>
          <span style="font-size:14px;font-weight:900;color:var(--accent);font-variant-numeric:tabular-nums">${fmtMoney(c.total)}</span>
        </div>
        <div style="height:8px;background:var(--surface3);border-radius:99px;overflow:hidden;position:relative">
          ${c.paid > 0 ? `<div style="height:100%;width:${(c.paid/max)*100}%;background:linear-gradient(90deg,var(--green),#22c55e);border-radius:99px;position:absolute;right:0;top:0"></div>` : ''}
          ${c.pending > 0 ? `<div style="height:100%;width:${pct}%;background:linear-gradient(90deg,var(--accent),var(--accent2));border-radius:99px;position:absolute;right:0;top:0;opacity:0.4;z-index:-1"></div>` : ''}
        </div>
      </div>`;
  }).join('');
}

function renderIncomeTrend(allIncome) {
  const chartEl = document.getElementById('income-trend-chart');
  if (!chartEl) return;

  const months = [];
  for (let i = 5; i >= 0; i--) {
    const d = new Date(curYear, curMonth - i, 1);
    months.push({ year: d.getFullYear(), month: d.getMonth(), label: d.toLocaleDateString('he-IL', {month:'short'}), total: 0 });
  }
  allIncome.forEach(it => {
    const d = new Date(it.date);
    const m = months.find(x => x.year === d.getFullYear() && x.month === d.getMonth());
    if (m && it.paid) m.total += +it.amount;
  });

  const max = Math.max(...months.map(m => m.total), 1);
  chartEl.innerHTML = months.map((m, i) => {
    const h = (m.total / max) * 100;
    const isCurrent = i === months.length - 1;
    return `
      <div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:6px;height:100%;justify-content:flex-end;cursor:default" title="${m.label}: ${fmtMoney(m.total)}">
        <div style="font-size:10px;font-weight:800;color:${isCurrent?'var(--accent)':'var(--text-muted)'};font-variant-numeric:tabular-nums">${m.total > 0 ? Math.round(m.total/1000)+'k' : ''}</div>
        <div style="width:100%;max-width:32px;height:${h}%;min-height:4px;background:${isCurrent?'linear-gradient(180deg,var(--accent),var(--accent2))':'linear-gradient(180deg,var(--surface3),var(--border))'};border-radius:6px 6px 2px 2px;transition:height .8s cubic-bezier(.4,0,.2,1);${isCurrent?'box-shadow:0 4px 12px var(--accent-glow)':''}"></div>
        <div style="font-size:11px;font-weight:${isCurrent?'800':'600'};color:${isCurrent?'var(--text)':'var(--text-muted)'}">${m.label}</div>
      </div>`;
  }).join('');
}

function renderMiniCal(incomeData, expensesData) {
  const calGrid = document.getElementById('mini-cal-grid');
  const calTitle = document.getElementById('mini-cal-title');
  if (!calGrid) return;

  calTitle.textContent = MONTHS_HE[curMonth] + ' ' + curYear;

  const todayObj   = new Date(); todayObj.setHours(0,0,0,0);
  const todayDay   = todayObj.getDate();
  const isThisMonth = todayObj.getFullYear() === curYear && todayObj.getMonth() === curMonth;

  // ── מצא את היום הקרוב ביותר עם הכנסה ממתינה ──
  const pendingIncDays = new Set();
  incomeData.forEach(i => {
    if (!inCurMonth(i.date) || (i.status||'pending') === 'paid') return;
    const d = new Date(i.date); d.setHours(0,0,0,0);
    if (!isThisMonth || d >= todayObj) pendingIncDays.add(new Date(i.date).getDate());
  });
  const nextIncDay = pendingIncDays.size > 0 ? Math.min(...pendingIncDays) : null;

  // ── מצא את היום הקרוב ביותר עם הוצאה ממתינה ──
  const pendingExpDays = new Set();
  expensesData.forEach(e => {
    if (!inCurMonth(e.date) || e.paid) return;
    const d = new Date(e.date); d.setHours(0,0,0,0);
    if (!isThisMonth || d >= todayObj) pendingExpDays.add(new Date(e.date).getDate());
  });
  const nextExpDay = pendingExpDays.size > 0 ? Math.min(...pendingExpDays) : null;

  // ── tooltip מלא לכל יום ──
  const incByDay = {}, expByDay = {};
  incomeData.forEach(i => {
    if (!inCurMonth(i.date)) return;
    const d = new Date(i.date).getDate();
    if (!incByDay[d]) incByDay[d] = [];
    incByDay[d].push(`${i.clientName || i.description}: ${fmtMoney(i.amount)}`);
  });
  expensesData.forEach(e => {
    if (!inCurMonth(e.date)) return;
    const d = new Date(e.date).getDate();
    if (!expByDay[d]) expByDay[d] = [];
    expByDay[d].push(`${e.description}: ${fmtMoney(e.amount)}`);
  });

  const dayHeaders = ['א','ב','ג','ד','ה','ו','ש'];
  let html = dayHeaders.map(h => `<div class="mini-cal-header">${h}</div>`).join('');

  const firstDay    = new Date(curYear, curMonth, 1).getDay();
  const daysInMonth = new Date(curYear, curMonth + 1, 0).getDate();

  for (let i = 0; i < firstDay; i++) html += `<div class="mini-cal-day empty"></div>`;

  for (let day = 1; day <= daysInMonth; day++) {
    const isToday = isThisMonth && todayDay === day;
    let dotsHtml = '';

    // נקודה ירוקה רק על היום הקרוב ביותר עם הכנסה ממתינה
    if (day === nextIncDay) {
      const tip = (incByDay[day] || []).join('<br>');
      dotsHtml += `<span class="mc-dot income" onclick="onDotTap(this)"><span class="mc-tooltip">💚 הכנסה קרובה<br>${tip}</span></span>`;
    }

    // נקודה ירוקה (כתום) רק על היום הקרוב ביותר עם הוצאה ממתינה
    if (day === nextExpDay) {
      const tip = (expByDay[day] || []).join('<br>');
      dotsHtml += `<span class="mc-dot" style="background:var(--orange)" onclick="onDotTap(this)"><span class="mc-tooltip">🔴 הוצאה קרובה<br>${tip}</span></span>`;
    }

    html += `
      <div class="mini-cal-day${isToday ? ' today' : ''}">
        <span>${day}</span>
        ${dotsHtml ? `<div class="mini-cal-dots">${dotsHtml}</div>` : ''}
      </div>`;
  }

  calGrid.innerHTML = html;
}

// ===== PROJECTS PAGE =====
function loadObj(key) {
  let v;
  try { v = JSON.parse(localStorage.getItem('s_' + key) || '{}'); }
  catch(e) { console.warn('Corrupted localStorage for', key, '— resetting'); return {}; }
  return (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
}

function renderProjects() {
  const income = load('income');
  const projNotes = loadObj('proj_notes');
  const projDone  = loadObj('proj_done');

  const projectCats = ['הפקה מוזיקלית', 'מיקס ומאסטרינג', 'הקלטה'];
  const projects = income
    .filter(i => projectCats.includes(i.category))
    .sort((a, b) => {
      const aDone = !!projDone[a.id];
      const bDone = !!projDone[b.id];
      if (aDone !== bDone) return aDone ? 1 : -1; // בוצע → למטה
      return 0;
    });

  const total = projects.length;
  const done  = projects.filter(i => projDone[i.id]).length;
  const pct   = total > 0 ? Math.round((done / total) * 100) : 0;

  const labelEl = document.getElementById('proj-progress-label');
  const fillEl  = document.getElementById('proj-progress-fill');
  if (labelEl) labelEl.textContent = `${done} מתוך ${total} פרויקטים הושלמו`;
  if (fillEl)  fillEl.style.width  = pct + '%';

  const grid = document.getElementById('proj-grid');
  if (!grid) return;

  if (projects.length === 0) {
    grid.innerHTML = `<div class="empty-state" style="grid-column:1/-1"><div class="ei"><svg><use href="#ic-music-note"/></svg></div><p>אין פרויקטים עדיין. הוסף הכנסות מסוג הפקה מוזיקלית, מיקס ומאסטרינג או הקלטה.</p></div>`;
    return;
  }

  grid.innerHTML = projects.map(i => {
    const isDone  = !!projDone[i.id];
    const note    = projNotes[i.id] || '';
    return `
      <div class="proj-card${isDone ? ' done' : ''}">
        <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:10px;margin-bottom:10px">
          <div>
            <div style="font-size:17px;font-weight:800;margin-bottom:3px">${i.description}${isDone ? ' ✅ הושלם' : ''}</div>
            <div style="font-size:14px;color:var(--accent);font-weight:600">${i.clientName || 'ללא לקוח'}</div>
          </div>
          <div style="text-align:left;flex-shrink:0">
            <div style="font-size:18px;font-weight:800;color:var(--green)">${fmtMoney(i.amount)}</div>
            <div style="font-size:13px;color:var(--text-muted)">${fmtDate(i.date)}</div>
          </div>
        </div>
        <div style="margin-bottom:4px">
          <span class="badge badge-purple" style="font-size:12px">${i.category}</span>
        </div>
        <div style="margin-bottom:12px;margin-top:10px">
          <label style="font-size:13px;font-weight:700;color:var(--text-muted);display:block;margin-bottom:4px">📝 מצב הפקה</label>
          <textarea
            id="proj-note-${i.id}"
            style="width:100%;background:var(--surface2);border:1.5px solid var(--border);border-radius:10px;padding:8px 12px;font-size:15px;color:var(--text);outline:none;direction:rtl;font-family:inherit;resize:vertical;min-height:60px"
            placeholder="כתוב הערות על מצב הפרויקט..."
            oninput="saveProjectNote('${i.id}', this.value)"
          >${note}</textarea>
        </div>
        <div style="display:flex;align-items:center;gap:12px">
          <button
            class="btn ${isDone ? 'btn-ghost' : 'btn-primary'} btn-sm"
            onclick="toggleProjectDone('${i.id}')"
          >${isDone ? '↩ בטל סיום' : '✅ סיימתי'}</button>
          ${isDone ? '<span class="badge badge-green">הושלם 🎉</span>' : '<span class="badge badge-gray">בתהליך</span>'}
        </div>
      </div>`;
  }).join('');
}

function saveProjectNote(incomeId, note) {
  const notes = loadObj('proj_notes');
  notes[incomeId] = note;
  save('proj_notes', notes);
}

function toggleProjectDone(incomeId) {
  const done = loadObj('proj_done');
  done[incomeId] = !done[incomeId];
  save('proj_done', done);
  renderProjects();
}

