function deleteSession(id) {
  const all = load('sessions');
  const target = all.find(s => s.id === id);
  save('sessions', all.filter(s => s.id !== id));
  renderSessionCal();
  toast('סשן נמחק');
  if (_gcalToken && target?.gcalEventId) deleteGcalEvent(target.gcalEventId);
}

function setSessionStatus(id, status) {
  const sessions = load('sessions');
  const s = sessions.find(x => x.id === id);
  if (!s) return;
  if (status === 'cancelled') {
    // ביטול = מחיקה מוחלטת (כמו גוגל)
    deleteSession(id);
    return;
  }
  s.status = status;
  save('sessions', sessions);
  renderSessionCal();
}

function renderSessionCal() {
  const allSessions = load('sessions');
  const monthKey    = `${curYear}-${String(curMonth+1).padStart(2,'0')}`;

  // filter current month
  const monthSes = allSessions.filter(s => s.date && s.date.startsWith(monthKey));
  const activeSes    = monthSes.filter(s => s.status !== 'cancelled');
  const countedSes   = activeSes.filter(s => s.type !== 'אחר'); // "אחר" לא נספר בסטטיסטיקה

  // ── stats ──
  const totalHrs   = countedSes.reduce((s,x) => s + sesDurationHours(x.startTime, x.endTime), 0);
  const uniqueCli  = new Set(countedSes.filter(s => s.clientId).map(s => s.clientId)).size;
  const avgHrs     = countedSes.length ? (totalHrs / countedSes.length) : 0;

  const setEl = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
  setEl('ses-stat-count',   countedSes.length);
  setEl('ses-stat-hours',   totalHrs % 1 === 0 ? totalHrs : totalHrs.toFixed(1));
  setEl('ses-stat-clients', uniqueCli);
  setEl('ses-stat-avg',     avgHrs % 1 === 0 ? avgHrs : avgHrs.toFixed(1));

  // update month label
  const lblEl = document.getElementById('lbl-sessions');
  if (lblEl) lblEl.textContent = new Date(curYear, curMonth, 1).toLocaleDateString('he-IL', { month:'long', year:'numeric' });

  // ── Next session banner ──
  const todayStr = new Date().toISOString().slice(0,10);
  const nowTime  = new Date().toTimeString().slice(0,5);
  const upcoming = allSessions
    .filter(s => s.status !== 'cancelled' && (s.date > todayStr || (s.date === todayStr && s.endTime > nowTime)))
    .sort((a,b) => a.date.localeCompare(b.date) || a.startTime.localeCompare(b.startTime));
  const banner = document.getElementById('next-ses-banner');
  if (banner && upcoming.length > 0) {
    const ns = upcoming[0];
    const nsDate = new Date(ns.date + 'T12:00:00');
    const dayDiff = Math.round((nsDate - new Date(todayStr + 'T12:00:00')) / 86400000);
    const whenLbl = dayDiff === 0 ? '🔴 היום' : dayDiff === 1 ? '🟡 מחר' : `📅 ${nsDate.toLocaleDateString('he-IL',{weekday:'long',day:'numeric',month:'long'})}`;
    const info = SES_TYPES[ns.type] || SES_TYPES['אחר'];
    document.getElementById('next-ses-when').textContent = whenLbl;
    document.getElementById('next-ses-who').textContent = ns.clientName || '— ללא לקוח —';
    document.getElementById('next-ses-detail').textContent = `${ns.startTime}–${ns.endTime} · ${info.label}${ns.notes ? ' · ' + ns.notes : ''}`;
    document.getElementById('next-ses-btn').onclick = () => openSessionModal(ns.date, ns.id);
    banner.style.display = 'flex';
    const _bcs = getComputedStyle(document.documentElement);
    banner.style.borderColor = dayDiff === 0 ? '#ef4444' : 'var(--accent)';
    banner.style.background = dayDiff === 0 ? _bcs.getPropertyValue('--banner-today-bg').trim() : _bcs.getPropertyValue('--banner-future-bg').trim();
  } else if (banner) {
    banner.style.display = 'none';
  }

  renderWeeklyView();
}

function renderWeeklyView() {
  const container = document.getElementById('weekly-view');
  if (!container) return;

  const allSessions = load('sessions');
  const today       = new Date();
  const todayStr    = today.toISOString().slice(0,10);
  const HE_DAYS     = ['ראשון','שני','שלישי','רביעי','חמישי','שישי','שבת'];

  // GCal events grouped by date
  const gcalByDate = {};
  _gcalEventsCache.forEach(e => {
    if (e.status === 'cancelled' || !e.start?.dateTime) return;
    const d = e.start.dateTime.split('T')[0];
    if (!gcalByDate[d]) gcalByDate[d] = [];
    gcalByDate[d].push(e);
  });

  // Sessions grouped by date
  const sesByDate = {};
  allSessions.forEach(s => {
    if (!s.date || s.status === 'cancelled') return;
    if (!sesByDate[s.date]) sesByDate[s.date] = [];
    sesByDate[s.date].push(s);
  });

  // All days of displayed month
  const daysInMonth = new Date(curYear, curMonth + 1, 0).getDate();
  const allDays = [];
  for (let d = 1; d <= daysInMonth; d++) {
    allDays.push(`${curYear}-${String(curMonth+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`);
  }

  // Week boundaries relative to today
  const todayDow = today.getDay();
  const thisWeekSun = new Date(today); thisWeekSun.setDate(today.getDate() - todayDow); thisWeekSun.setHours(0,0,0,0);
  const nextWeekSun = new Date(thisWeekSun); nextWeekSun.setDate(thisWeekSun.getDate() + 7);
  const weekAfterSun = new Date(thisWeekSun); weekAfterSun.setDate(thisWeekSun.getDate() + 14);

  // Classify each day into a section
  function sectionKey(dateStr) {
    const d = new Date(dateStr + 'T12:00:00');
    if (d >= thisWeekSun && d < nextWeekSun)  return 'this';
    if (d >= nextWeekSun && d < weekAfterSun) return 'next';
    if (d >= weekAfterSun)                    return 'rest';
    return 'past';
  }

  const isCurrentMonth = (curYear === today.getFullYear() && curMonth === today.getMonth());

  const SECTIONS = isCurrentMonth
    ? [
        { key:'this', label:'השבוע',        emoji:'📅' },
        { key:'next', label:'שבוע הבא',      emoji:'📆' },
        { key:'rest', label:'שאר החודש',     emoji:'🗓' },
      ]
    : (() => {
        // past or future month: split into calendar weeks
        const weeks = [];
        let cur = null;
        allDays.forEach(dateStr => {
          const d = new Date(dateStr + 'T12:00:00');
          if (d.getDay() === 0 || !cur) {
            cur = { key: 'w' + weeks.length, label: `שבוע ${weeks.length + 1}`, emoji: '📅', days: [] };
            weeks.push(cur);
          }
          cur.days.push(dateStr);
        });
        return weeks.map(w => ({ key: w.key, label: w.label, emoji: w.emoji, _days: w.days }));
      })();

  // Group days per section
  const grouped = {};
  SECTIONS.forEach(s => { grouped[s.key] = s._days || []; });
  if (isCurrentMonth) {
    allDays.forEach(dateStr => {
      const k = sectionKey(dateStr);
      if (grouped[k]) grouped[k].push(dateStr);
    });
  }

  // ── Render ──
  const fmtHrs = h => h % 1 === 0 ? h : h.toFixed(1);

  function renderEventRow(dateStr, s) {
    const info   = SES_TYPES[s.type] || SES_TYPES['אחר'];
    const dur    = sesDurationLabel(s.startTime, s.endTime);
    const isComp = s.status === 'completed';
    return `
      <div class="session-row" onclick="openSessionModal('${dateStr}','${s.id}')" style="align-items:center">
        <div style="width:4px;min-height:54px;border-radius:2px;flex-shrink:0;background:${info.color}"></div>
        <div style="min-width:48px;text-align:center;flex-shrink:0">
          <div style="font-size:15px;font-weight:900;color:var(--text);font-family:'Rubik',sans-serif;line-height:1.2">${s.startTime}</div>
          <div style="font-size:11px;color:var(--text-muted);margin-top:1px">${s.endTime}</div>
        </div>
        <div style="flex:1;min-width:0;padding:0 6px">
          <div style="font-size:14px;font-weight:800;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${s.clientName || '—'}</div>
          <div style="font-size:12px;color:var(--text-muted);margin-top:1px">${info.label}${dur ? ' · ' + dur : ''}</div>
        </div>
        ${isComp
          ? `<span style="background:var(--pill-green-bg);color:var(--pill-green-text);border-radius:20px;padding:3px 10px;font-size:11px;font-weight:800;white-space:nowrap;flex-shrink:0">✅ הושלם</span>`
          : `<button onclick="event.stopPropagation();setSessionStatus('${s.id}','completed')" style="border:none;border-radius:8px;padding:5px 9px;font-size:11px;font-weight:800;cursor:pointer;background:var(--pill-green-bg);color:var(--pill-green-text);white-space:nowrap;flex-shrink:0;font-family:'Heebo',sans-serif">✓</button>
             <button onclick="event.stopPropagation();setSessionStatus('${s.id}','cancelled')" style="border:none;border-radius:8px;padding:5px 9px;font-size:11px;font-weight:800;cursor:pointer;background:var(--pill-red-bg);color:var(--pill-red-text);white-space:nowrap;flex-shrink:0;font-family:'Heebo',sans-serif">✕</button>`
        }
        <button onclick="event.stopPropagation();deleteSession('${s.id}')" style="border:none;background:none;color:var(--delete-btn-color);cursor:pointer;font-size:20px;padding:2px 4px;line-height:1;flex-shrink:0" title="מחק">×</button>
      </div>`;
  }

  function renderGcalRow(e) {
    const st = e.start.dateTime.split('T')[1]?.slice(0,5) || '';
    const en = e.end?.dateTime?.split('T')[1]?.slice(0,5) || '';
    return `
      <div class="session-row" onclick="showGcalPillMenu('${e.id}',event)" style="align-items:center;cursor:pointer">
        <div style="width:4px;min-height:54px;border-radius:2px;flex-shrink:0;background:var(--gcal-color)"></div>
        <div style="min-width:48px;text-align:center;flex-shrink:0">
          <div style="font-size:15px;font-weight:900;color:var(--gcal-color);font-family:'Rubik',sans-serif;line-height:1.2">${st}</div>
          <div style="font-size:11px;color:var(--text-muted);margin-top:1px">${en}</div>
        </div>
        <div style="flex:1;min-width:0;padding:0 6px">
          <div style="font-size:14px;font-weight:800;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${e.summary || 'אירוע גוגל'}</div>
          <div style="font-size:12px;color:var(--gcal-color);margin-top:1px">גוגל קלנדר</div>
        </div>
        <span style="background:var(--pill-gcal-bg);color:var(--pill-gcal-text);border-radius:20px;padding:3px 10px;font-size:11px;font-weight:800;white-space:nowrap;flex-shrink:0">📅 גוגל</span>
      </div>`;
  }

  function renderDayBlock(dateStr) {
    const d      = new Date(dateStr + 'T12:00:00');
    const isT    = dateStr === todayStr;
    const isPast = dateStr < todayStr;
    const dayNum = d.getDate();
    const dayName = HE_DAYS[d.getDay()];
    const monthName = MONTHS_HE[d.getMonth()];

    const daySes = (sesByDate[dateStr] || []).slice().sort((a,b) => a.startTime.localeCompare(b.startTime));
    const appGcalIds = new Set(daySes.map(s => s.gcalEventId).filter(Boolean));
    const dayGcal = (gcalByDate[dateStr] || []).filter(e => !appGcalIds.has(e.id))
      .sort((a,b) => (a.start.dateTime||'').localeCompare(b.start.dateTime||''));

    const totalEvents = daySes.length + dayGcal.length;
    const dayHrs = daySes.filter(s => s.type !== 'אחר').reduce((acc,s) => acc + sesDurationHours(s.startTime, s.endTime), 0);

    const headerStyle = isPast && !isT ? 'opacity:0.55' : '';
    const circleStyle = isT
      ? 'background:var(--accent);color:#fff;box-shadow:0 2px 10px rgba(108,71,245,0.35)'
      : isPast ? 'background:var(--surface3);color:var(--text-muted)' : 'background:var(--surface2);color:var(--text)';

    let html = `
      <div style="margin-bottom:${totalEvents > 0 ? '18px' : '6px'}">
        <div style="display:flex;align-items:center;gap:10px;padding:8px 0;${headerStyle}">
          <div style="width:40px;height:40px;border-radius:11px;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:17px;font-weight:900;${circleStyle}">${dayNum}</div>
          <div style="flex:1;min-width:0">
            <div style="font-size:15px;font-weight:800;color:${isT ? 'var(--accent)' : 'var(--text)'};display:flex;align-items:center;gap:6px">
              ${dayName}
              ${isT ? '<span style="font-size:10px;background:var(--accent);color:#fff;border-radius:20px;padding:1px 8px">היום</span>' : ''}
            </div>
            <div style="font-size:11px;color:var(--text-muted);margin-top:1px">
              ${dayNum} ${monthName}${dayHrs > 0 ? ' · ' + fmtHrs(dayHrs) + ' שעות' : ''}${totalEvents === 0 ? ' · אין אירועים' : ''}
            </div>
          </div>
          <button onclick="openSessionModal('${dateStr}')" style="border:1.5px solid var(--accent);border-radius:8px;padding:4px 12px;font-size:12px;font-weight:800;cursor:pointer;background:var(--accent-light);color:var(--accent);white-space:nowrap;font-family:'Heebo',sans-serif;flex-shrink:0">+ סשן</button>
        </div>`;

    if (totalEvents > 0) {
      html += `<div style="margin-right:50px">`;
      daySes.forEach(s => { html += renderEventRow(dateStr, s); });
      dayGcal.forEach(e => { html += renderGcalRow(e); });
      html += `</div>`;
    }

    html += `</div>`;
    return html;
  }

  let finalHtml = '';

  SECTIONS.forEach(sec => {
    const days = grouped[sec.key] || [];
    if (days.length === 0) return;

    const f = new Date(days[0] + 'T12:00:00');
    const l = new Date(days[days.length-1] + 'T12:00:00');
    const dateRange = `${f.getDate()}–${l.getDate()} ${MONTHS_HE[l.getMonth()]}`;

    const totalEventsInSection = days.reduce((acc, d) => {
      const ses = (sesByDate[d] || []).length;
      const appIds = new Set((sesByDate[d] || []).map(s => s.gcalEventId).filter(Boolean));
      const gcal = (gcalByDate[d] || []).filter(e => !appIds.has(e.id)).length;
      return acc + ses + gcal;
    }, 0);

    finalHtml += `
      <div style="margin-bottom:32px">
        <div style="display:flex;align-items:baseline;gap:10px;margin-bottom:16px;padding-bottom:10px;border-bottom:2.5px solid var(--accent)">
          <div style="font-size:19px;font-weight:900;color:var(--accent);font-family:'Frank Ruhl Libre','Heebo',serif">${sec.emoji} ${sec.label}</div>
          <div style="font-size:12px;color:var(--text-muted);font-weight:700">${dateRange}</div>
          ${totalEventsInSection > 0
            ? `<div style="margin-right:auto;font-size:12px;color:var(--text-muted);font-weight:700">${totalEventsInSection} אירועים</div>`
            : `<div style="margin-right:auto;font-size:12px;color:var(--text-muted);font-style:italic">אין אירועים</div>`
          }
        </div>
        ${days.map(renderDayBlock).join('')}
      </div>`;
  });

  if (!finalHtml) {
    finalHtml = `<div class="empty-state"><div class="ei"><svg><use href="#ic-calendar"/></svg></div><p>אין אירועים — לחץ "+ סשן חדש" כדי להתחיל</p></div>`;
  }

  container.innerHTML = finalHtml;
}

function selectCalDay(dateStr, noToggle) {
  // toggle: if same day clicked again, close panel
  if (!noToggle && _selDay === dateStr) {
    _selDay = null;
    document.getElementById('day-panel').classList.remove('open');
    renderSessionCal();
    return;
  }
  _selDay = dateStr;

  // highlight selected cell
  document.querySelectorAll('.cal-cell').forEach(c => c.classList.remove('selected'));
  const cells = document.querySelectorAll('.cal-cell');
  cells.forEach(c => {
    const onclick = c.getAttribute('onclick') || '';
    if (onclick.includes(`'${dateStr}'`)) c.classList.add('selected');
  });

  const panel = document.getElementById('day-panel');
  panel.classList.add('open');

  // format date nicely
  const d = new Date(dateStr + 'T12:00:00');
  const dayName = d.toLocaleDateString('he-IL', { weekday:'long', day:'numeric', month:'long' });
  document.getElementById('day-panel-title').textContent = dayName;

  // add button for this day
  const addBtn = document.getElementById('day-panel-add-btn');
  addBtn.onclick = () => openSessionModal(dateStr);

  // show sessions for this day
  const daySes = load('sessions').filter(s => s.date === dateStr)
    .sort((a,b) => a.startTime.localeCompare(b.startTime));
  const cont = document.getElementById('day-panel-sessions');
  if (daySes.length === 0) {
    cont.innerHTML = `<div style="color:var(--text-muted);font-size:15px;padding:8px 0">אין סשנים ביום זה — לחץ "+ סשן ליום זה"</div>`;
  } else {
    cont.innerHTML = daySes.map(s => {
      const info = SES_TYPES[s.type] || SES_TYPES['אחר'];
      const dur  = sesDurationLabel(s.startTime, s.endTime);
      const statusBadge = s.status === 'completed'
        ? `<span class="badge badge-green">הושלם</span>`
        : s.status === 'cancelled'
        ? `<span class="badge badge-gray">❌ בוטל</span>`
        : `<span style="display:flex;gap:6px">
             <button onclick="event.stopPropagation();setSessionStatus('${s.id}','completed')" style="border:none;border-radius:8px;padding:5px 12px;font-size:13px;font-weight:700;cursor:pointer;background:var(--pill-green-bg);color:var(--pill-green-text)">✓ סיום</button>
             <button onclick="event.stopPropagation();setSessionStatus('${s.id}','cancelled')" style="border:none;border-radius:8px;padding:5px 12px;font-size:13px;font-weight:700;cursor:pointer;background:var(--pill-red-bg);color:var(--pill-red-text)">✕ ביטול</button>
           </span>`;
      return `
        <div class="session-row" onclick="openSessionModal('${s.date}','${s.id}')">
          <div style="width:5px;height:48px;border-radius:3px;flex-shrink:0;background:${info.color}"></div>
          <div style="flex:1">
            <div style="display:flex;align-items:center;gap:8px;margin-bottom:3px">
              <span style="font-size:15px;font-weight:800">${s.clientName || '— ללא לקוח —'}</span>
              <span style="font-size:13px;color:${info.color};font-weight:700">${info.label}</span>
            </div>
            <div style="font-size:13px;color:var(--text-muted)">${s.startTime}–${s.endTime}${dur?' · '+dur:''}</div>
            ${s.notes ? `<div style="font-size:13px;color:var(--text-muted);margin-top:3px">${s.notes}</div>` : ''}
          </div>
          ${statusBadge}
          <button onclick="event.stopPropagation();deleteSession('${s.id}')" style="border:none;background:none;color:var(--text-muted);cursor:pointer;font-size:18px;padding:2px 6px">×</button>
        </div>`;
    }).join('');
  }
}

function renderPendingBox() {
  const income   = load('income');
  const expenses = load('expenses');
  const plans    = load('plans');

  // ── פילטר לחודש הנוכחי בלבד ──
  const inMonth = date => {
    const d = new Date(date);
    return d.getFullYear() === curYear && d.getMonth() === curMonth;
  };

  // הכנסות החודש שלא שולמו
  const monthInc     = income.filter(i => inMonth(i.date));
  const unpaidInc    = monthInc.filter(i => (i.status || 'pending') !== 'paid');
  const paidInc      = monthInc.filter(i => (i.status || 'pending') === 'paid');
  const unpaidIncAmt = unpaidInc.reduce((s,i) => s + Number(i.amount), 0);
  const paidIncAmt   = paidInc.reduce((s,i) => s + Number(i.amount), 0);

  // תשלומים מתוכניות = תצוגה בלבד — כשמסמנים שולם הם נוספים להכנסות ונספרים שם
  const totalPending   = unpaidIncAmt;
  const totalCollected = paidIncAmt;
  const monthTotal     = totalPending + totalCollected;
  const incPct = monthTotal > 0 ? Math.round((totalCollected / monthTotal) * 100) : 0;

  // הוצאות החודש שלא שולמו + הוצאות חוזרות של החודש
  const monthKey2    = `${curYear}-${String(curMonth+1).padStart(2,'0')}`;
  const allRecurring = load('recurring_expenses');
  const activeRec    = allRecurring.filter(r => r.startMonth <= monthKey2 && (!r.endMonth || r.endMonth >= monthKey2));
  const unpaidRec    = activeRec.filter(r => !(r.paidMonths && r.paidMonths[monthKey2]));
  const paidRecAmt   = activeRec.filter(r => r.paidMonths && r.paidMonths[monthKey2]).reduce((s,r) => s + _recAmt(r, monthKey2), 0);
  const unpaidRecAmt = unpaidRec.reduce((s,r) => s + _recAmt(r, monthKey2), 0);

  const monthExp     = expenses.filter(e => inMonth(e.date));
  const unpaidExp    = monthExp.filter(e => !e.paid);
  const paidExpAmt   = monthExp.filter(e => e.paid).reduce((s,e) => s + Number(e.amount), 0) + paidRecAmt;
  const unpaidExpAmt = unpaidExp.reduce((s,e) => s + Number(e.amount), 0) + unpaidRecAmt;
  const totalExpMonth = paidExpAmt + unpaidExpAmt;
  const expPct = totalExpMonth > 0 ? Math.round((paidExpAmt / totalExpMonth) * 100) : 0;

  // ── עדכון DOM ──
  const set  = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
  const setW = (id, pct) => { const el = document.getElementById(id); if (el) el.style.width = pct + '%'; };

  set('pending-income-amt', fmtMoney(totalPending));
  set('pending-income-sub', totalPending === 0
    ? `הכל גבית החודש 🎉 — סה"כ ${fmtMoney(monthTotal)}`
    : `מתוך ${fmtMoney(monthTotal)} צפוי החודש`);
  set('pending-income-pct', incPct + '% גבוי');
  setW('pending-income-bar', incPct);

  const totalUnpaidExpCount = unpaidExp.length + unpaidRec.length;
  set('pending-expenses-amt', fmtMoney(unpaidExpAmt));
  set('pending-expenses-sub', totalUnpaidExpCount === 0
    ? `הכל שולם החודש 🎉 — סה"כ ${fmtMoney(totalExpMonth)}`
    : `מתוך ${fmtMoney(totalExpMonth)} הוצאות החודש`);
  set('pending-expenses-pct', expPct + '% שולם');
  setW('pending-expenses-bar', expPct);
}

