// ===== גיבוי ושחזור =====
function exportBackup() {
  const data = {};
  ALL_KEYS.forEach(k => {
    const v = localStorage.getItem('s_' + k);
    if (v) data[k] = JSON.parse(v);
  });
  const json = JSON.stringify(data, null, 2);
  const blob = new Blob([json], { type: 'application/json' });
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a');
  a.href     = url;
  a.download = 'elior-studio-backup-' + new Date().toISOString().slice(0,10) + '.json';
  a.click();
  URL.revokeObjectURL(url);
  toast('✅ גיבוי הורד בהצלחה');
}

function importBackup(event) {
  const file = event.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = e => {
    try {
      const data = JSON.parse(e.target.result);
      ALL_KEYS.forEach(k => {
        if (data[k] !== undefined) {
          localStorage.setItem('s_' + k, JSON.stringify(data[k]));
        }
      });
      // העלה הכל לענן
      pushAllToCloud();
      refreshAll();
      toast('✅ גיבוי יובא בהצלחה — כל הנתונים שוחזרו');
    } catch(err) {
      toast('❌ קובץ לא תקין');
    }
  };
  reader.readAsText(file);
  event.target.value = '';
}


// ===== PWA — Service Worker + Install =====
if ('serviceWorker' in navigator) {
  // Reload the page automatically when a new SW takes over. Three
  // overlapping signals so it works on every iOS quirk we've hit:
  //   1. controllerchange — fires when SW.claim() takes control.
  //   2. updatefound + statechange === 'activated' — older path.
  //   3. postMessage('sw-activated') — explicit ping from sw.js.
  // The 3-second debounce stops any pair of them from chaining into
  // an infinite reload loop.
  // SW auto-reload disabled: any reload during normal use causes a
  // visible flash of the iOS WebView snapshot before the new HTML
  // paints. Updates take effect on the next full app launch instead
  // (still fast — a few seconds — but invisible to the user).
  function _swForceReload() { /* intentionally a no-op */ }

  navigator.serviceWorker.register('/elior-studio-app/sw.js').then(reg => {
    reg.update();
    reg.addEventListener('updatefound', () => {
      const newWorker = reg.installing;
      newWorker.addEventListener('statechange', () => {
        if (newWorker.state === 'activated') _swForceReload();
      });
    });
  }).catch(() => {});
}

// ===== INSTALL APP =====
let _deferredInstall = null;
window.addEventListener('beforeinstallprompt', e => {
  e.preventDefault();
  _deferredInstall = e;
  maybeShowInstallBanner();
});

function isStandalone() {
  return window.matchMedia('(display-mode: standalone)').matches
      || window.navigator.standalone === true
      || document.referrer.includes('android-app://');
}

function isIOS() {
  return /iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream;
}

function maybeShowInstallBanner() {
  if (isStandalone()) return; // already installed
  if (localStorage.getItem('install_dismissed') === 'yes') return;
  const banner = document.getElementById('install-banner');
  const sub = document.getElementById('install-banner-sub');
  const btn = document.getElementById('install-btn');
  if (!banner) return;

  if (_deferredInstall) {
    // Android Chrome
    if (sub) sub.textContent = 'הוסף את אליאור רביד למסך הבית';
    if (btn) { btn.style.display = ''; btn.textContent = 'התקן'; }
  } else if (isIOS()) {
    // iOS Safari — show instructions modal
    if (sub) sub.textContent = 'באייפון: שתף ← הוסף למסך הבית';
    if (btn) { btn.style.display = ''; btn.textContent = 'הסבר'; }
  } else {
    // Not installable now — hide
    return;
  }
  banner.style.display = 'flex';
}

async function triggerInstall() {
  if (_deferredInstall) {
    _deferredInstall.prompt();
    const { outcome } = await _deferredInstall.userChoice;
    _deferredInstall = null;
    if (outcome === 'accepted') {
      dismissInstallBanner();
      toast('✅ האפליקציה הותקנה');
    }
  } else if (isIOS()) {
    openModal('ios-install');
  }
}

function dismissInstallBanner() {
  localStorage.setItem('install_dismissed', 'yes');
  const b = document.getElementById('install-banner');
  if (b) b.style.display = 'none';
}

// Try to show banner on app load (mobile only)
window.addEventListener('load', () => {
  if (window.innerWidth <= 768) {
    setTimeout(maybeShowInstallBanner, 3000);
  }
});

window.addEventListener('appinstalled', () => {
  dismissInstallBanner();
  toast('🎉 אליאור רביד הותקן בהצלחה');
});
(function() {
  try {
    const s = 180, c = document.createElement('canvas');
    c.width = c.height = s;
    const ctx = c.getContext('2d'), r = s*.21;
    ctx.beginPath();
    ctx.moveTo(r,0); ctx.lineTo(s-r,0); ctx.arcTo(s,0,s,r,r);
    ctx.lineTo(s,s-r); ctx.arcTo(s,s,s-r,s,r);
    ctx.lineTo(r,s); ctx.arcTo(0,s,0,s-r,r);
    ctx.lineTo(0,r); ctx.arcTo(0,0,r,0,r); ctx.closePath();
    const bg = ctx.createLinearGradient(0,0,s,s);
    bg.addColorStop(0,'#1a0a3d'); bg.addColorStop(.5,'#2d1470'); bg.addColorStop(1,'#0d0621');
    ctx.fillStyle=bg; ctx.fill();
    ctx.save(); ctx.clip();
    const glow=ctx.createRadialGradient(s*.38,s*.28,0,s*.5,s*.5,s*.75);
    glow.addColorStop(0,'rgba(140,100,255,0.35)'); glow.addColorStop(1,'rgba(0,0,0,0)');
    ctx.fillStyle=glow; ctx.fillRect(0,0,s,s); ctx.restore();
    const cx=s*.5,banY=s*.5,banR=s*.285,lw=s*.062,earR=s*.115,earIn=s*.065,lx=cx-banR,rx=cx+banR,ey=banY+s*.02;
    ctx.save(); ctx.shadowColor='rgba(120,80,255,0.6)'; ctx.shadowBlur=s*.06;
    ctx.beginPath(); ctx.arc(cx,banY,banR,Math.PI,0,false);
    ctx.strokeStyle='#fff'; ctx.lineWidth=lw; ctx.lineCap='round'; ctx.stroke(); ctx.restore();
    [lx,rx].forEach(ex=>{
      ctx.save(); ctx.shadowColor='rgba(120,80,255,0.5)'; ctx.shadowBlur=s*.05;
      ctx.beginPath(); ctx.arc(ex,ey,earR,0,Math.PI*2); ctx.fillStyle='#fff'; ctx.fill(); ctx.restore();
      ctx.beginPath(); ctx.arc(ex,ey,earIn,0,Math.PI*2);
      const cu=ctx.createRadialGradient(ex-earIn*.2,ey-earIn*.2,0,ex,ey,earIn);
      cu.addColorStop(0,'#4a1fa8'); cu.addColorStop(1,'#200d58'); ctx.fillStyle=cu; ctx.fill();
    });
    ctx.save(); ctx.shadowColor='rgba(160,120,255,0.8)'; ctx.shadowBlur=s*.05;
    ctx.fillStyle='#fff'; ctx.font=`900 ${s*.195}px Arial Black,Arial`;
    ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText('ER',cx,banY+banR*.62); ctx.restore();
    document.getElementById('apple-icon').href=c.toDataURL('image/png');
  } catch(e){}
})();

// ===== סימון אוטומטי כ"באיחור" =====
// כל פעם שפותחים את האפליקציה — מסנכרן את הסטטוס של הכנסות לפי התאריך:
// תאריך שעבר → "באיחור"; תאריך עתידי שמסומן כבאיחור → חוזר ל"ממתין".
function autoMarkOverdue() {
  const today = new Date(); today.setHours(0,0,0,0);
  const income = load('income');
  let changed = false;
  income.forEach(i => {
    const st = i.status || 'pending';
    if (st === 'paid') return; // ששולם נשאר ששולם
    const d = new Date(i.date); d.setHours(0,0,0,0);
    if (st === 'pending' && d < today) { i.status = 'overdue'; changed = true; }
    else if (st === 'overdue' && d >= today) { i.status = 'pending'; changed = true; }
  });
  if (!changed) return;
  save('income', income);
}

