// ── One fixed-costs system (4.10): the older "recurring_expenses" list
// (e.g. the previous flat's rent) duplicated fixed_costs and kept adding a
// phantom "נשאר להוציא". Each still-active recurring item is copied into
// fixed_costs (unless a same-named item already exists there) and ended, so
// it stops counting from now on. Data is kept (endMonth), nothing deleted.
// Idempotent: ended items are no longer active; folded ones are marked. ──
function fcFoldRecurring2610() {
  try {
  if (!firebaseReady) return;   // 6.10: only on top of real cloud data
    const rec = load('recurring_expenses') || [];
    if (!rec.length) return;
    const now = new Date(), cur = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0');
    const prevD = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const prev = prevD.getFullYear() + '-' + String(prevD.getMonth() + 1).padStart(2, '0');
    const fc = load('fixed_costs') || [];
    const has = n => fc.some(x => x && String(x.name || '').trim() === String(n || '').trim());
    let changed = 0, added = 0;
    rec.forEach(r => {
      if (!r || r.foldedToFixed) return;
      if (r.endMonth && r.endMonth < cur) return;            // already over
      const name = String(r.description || '').trim(); if (!name) return;
      if (!has(name)) {
        const cat = String(r.category || '');
        fc.push({ id: 'fc_rec_' + r.id, name, amount: Number(r.amount) || 0,
          group: /שכירות|חשמל|מים|ארנונה|גז/.test(cat + name) ? 'living' : 'service', note: '', until: '' });
        added++;
      }
      r.endMonth = (r.paidMonths && r.paidMonths[cur]) ? cur : prev;
      r.foldedToFixed = true; changed++;
    });
    if (!changed) return;
    save('recurring_expenses', rec);
    if (added) save('fixed_costs', fc);
  } catch (e) { console.warn('fcFoldRecurring2610', e); }
}
// ── New flat (10.2026): his personal outflows are now the transfer to the
