// ── עקביות נתונים ──

const _DB_REST = 'https://elior-studio-default-rtdb.firebaseio.com';
let _syncRestBusy = false;
function _syncFromCloud(reason) {
  // קודם שלח pending — אחר כך קח מהענן רק מה שאין pending עליו
  flushPending();
  // Plain-HTTPS REST, NOT the SDK: after iOS suspends the app the
  // Firebase WebSocket freezes and .once('value') hangs forever with
  // no error — the exact bug _waPullREST bypasses for the WhatsApp
  // page. This is why a "קבע" event sat in the cloud while the לוז
  // showed nothing until a full cold boot.
  if (_syncRestBusy) return;
  _syncRestBusy = true;
  (async () => {
    try {
      const meta = await fetch(_DB_REST + '/studio_meta.json', { cache: 'no-store' }).then(r => r.json()) || {};
      let changed = false;
      for (const key of ALL_KEYS) {
        if (_pending[key]) continue; // יש שינוי מקומי — אל תדרוס!
        const localTs = parseInt(localStorage.getItem('s_' + key + '_ts') || '0', 10);
        const cloudTs = parseInt(meta[key] || '0', 10);
        // Use cloud only if it's strictly newer than local
        // (covers replication lag + protects local changes)
        if (cloudTs > 0 && localTs > 0 && cloudTs <= localTs) continue;
        try {
          let val = await fetch(_DB_REST + '/studio_data/' + key + '.json', { cache: 'no-store' }).then(r => r.json());
          if (val === null || val === undefined) continue;
          let fcKeep = false;
          if (key === 'fixed_costs') {   // keep any item this device has a newer version of
            const merged = _fcMerge(val, JSON.parse(localStorage.getItem('s_fixed_costs') || '[]'));
            if (JSON.stringify(merged) !== JSON.stringify(val)) { val = merged; fcKeep = true; }
          }
          const cur  = localStorage.getItem('s_' + key);
          const next = JSON.stringify(val);
          if (cur !== next) {
            localStorage.setItem('s_' + key, next);
            if (cloudTs > 0) { localStorage.setItem('s_' + key + '_ts', String(cloudTs)); localStorage.setItem('s_' + key + '_base', String(cloudTs)); }
            changed = true;
            if (fcKeep) { _markDirty(key, val); _pushKey(key); }
          } else if (cloudTs > 0) {
            localStorage.setItem('s_' + key + '_ts', String(cloudTs));
            localStorage.setItem('s_' + key + '_base', String(cloudTs));
          }
        } catch (_) {}
      }
      if (changed) { refreshAll(); console.log('🔄', reason); }
      // Drain remote-command queue over REST too — the SDK child_added
      // listener rides the same frozen socket, so without this an
      // event's Google-Calendar mirror + "בוצע" receipt waited for a
      // cold boot as well.
      try {
        const q = await fetch(_DB_REST + '/whatsapp/cmdqueue.json', { cache: 'no-store' }).then(r => r.json());
        if (q && typeof q === 'object' && typeof _waCmdApply === 'function') {
          for (const k of Object.keys(q)) { try { _waCmdApply(k, q[k]); } catch (_) {} }
        }
      } catch (_) {}
      // Drain the bank inbox — the nightly Discount scraper (GitHub
      // Action) drops REAL-NAMED transactions into /bank_inbox; pull
      // them into the pending-tx queue with names + categories, then
      // delete from the cloud. One toast for the whole batch.
      try { await _bankInboxDrain(); } catch (_) {}
      try { await _growPaidDrain(); } catch (_) {}
    } catch (_) {}
    _syncRestBusy = false;
  })();
}

// Categories that default to a PERSONAL tag on bank debits (Elior
// 31.7); everything else defaults to business. Always toggleable per
// transaction via the chip on the row.
const _TX_PERSONAL_CATS = ['מזון', 'בילוי', 'בגדים', 'בריאות'];
function bankCreditsList() { try { return load('bank_credits') || []; } catch (_) { return []; } }
function bankCreditsSave(a) { save('bank_credits', a); }

async function _bankInboxDrain() {
  const q = await fetch(_DB_REST + '/bank_inbox.json', { cache: 'no-store' }).then(r => r.json());
  if (!q || typeof q !== 'object') return;
  let seen = [];
  try { seen = JSON.parse(localStorage.getItem('bank_seen') || '[]'); } catch (_) {}
  const arr = txList();
  const credits = bankCreditsList();
  let added = 0, creditsAdded = 0;
  for (const k of Object.keys(q)) {
    const t = q[k] || {};
    if (seen.indexOf(k) === -1 && Number(t.amount) > 0) {
      const name = String(t.name || '').trim();
      if (t.kind === 'credit') {
        // money IN — goes to the approval list on the income page
        if (!credits.some(c => c.id === 'bc_' + k)) {
          credits.push({ id: 'bc_' + k, date: t.date || new Date().toISOString().slice(0, 10), amount: Number(t.amount), name: name });
          creditsAdded++;
        }
      } else {
        const guess = name ? _txGuessCategory(name) : { cat: 'אחר', icon: '💳' };
        const item = {
          id: 'tx_bank_' + k,
          ts: new Date().toISOString(),
          amount: Number(t.amount),
          merchant: name || 'תנועה ללא שם',
          date: t.date || new Date().toISOString().slice(0, 10),
          category: guess.cat,
          icon: '🏦',
          raw: 'בנק דיסקונט · ' + (name || '')
        };
        _txApplyRule(item);
        item.tag = _TX_PERSONAL_CATS.indexOf(item.category) !== -1 ? 'אישי' : 'עסקי';
        if (!arr.some(x => x.id === item.id)) { arr.push(item); added++; }
      }
      seen.push(k);
    }
    fetch(_DB_REST + '/bank_inbox/' + k + '.json', { method: 'DELETE' }).catch(() => {});
  }
  if (added || creditsAdded) {
    if (added) txSaveAll(arr);
    if (creditsAdded) bankCreditsSave(credits);
    if (seen.length > 800) seen = seen.slice(-800);
    localStorage.setItem('bank_seen', JSON.stringify(seen));
    const parts = [];
    if (added) parts.push(added + ' הוצאות');
    if (creditsAdded) parts.push(creditsAdded + ' כניסות');
    toast('🏦 מהבנק: ' + parts.join(' · '));
    if (window.haptic) window.haptic.success();
    if (typeof renderExpenses === 'function') renderExpenses();
    if (creditsAdded && typeof renderIncome === 'function') { try { renderIncome(); } catch (_) {} }
  } else if (Object.keys(q).length) {
    localStorage.setItem('bank_seen', JSON.stringify(seen));
  }
}

// ── Bank credits card (income page): exact-amount match to a pending
//    income → one tap marks it paid; no match → approve as new income.
function renderBankCredits() {
  const wrap = document.getElementById('bank-credits-card');
  if (!wrap) return;
  const credits = bankCreditsList();
  if (!credits.length) { wrap.innerHTML = ''; return; }
  const income = load('income') || [];
  const rows = credits.map(c => {
    const match = income.find(i => (i.status || 'pending') !== 'paid' && Math.abs(Number(i.amount) - c.amount) < 0.01);
    const idEsc = c.id.replace(/'/g, "\\'");
    const who = (c.name || 'העברה בנקאית').replace(/[<>&]/g, '');
    const action = match
      ? `<button class="fx-name-btn" onclick="bankCreditPaid('${idEsc}')">סמן שולם${match.clientName ? ' · ' + match.clientName.replace(/[<>&'"]/g, '') : ''}</button>`
      : `<button class="fx-name-btn" onclick="bankCreditAdd('${idEsc}')">הוסף כהכנסה</button>`;
    return `<div class="fx-row">
      <div class="fx-body">
        <div class="fx-title">${who}</div>
        <div class="fx-meta">${c.date.split('-').reverse().slice(0, 2).join('.')}${match ? ' · תואם להכנסה ממתינה' : ' · אין התאמה'}</div>
      </div>
      ${action}
      <button class="tx-mini-btn reject" onclick="bankCreditDismiss('${idEsc}')" title="הסר">×</button>
      <div class="fx-amt" style="color:var(--green)">+${fmtMoney(c.amount)}</div>
    </div>`;
  }).join('');
  wrap.innerHTML = `<div class="fx-card">
    <div class="fx-head"><div class="fx-head-title">🏦 נכנס לבנק — לאישור שלך</div></div>
    ${rows}
  </div>`;
}
window.bankCreditPaid = function(cid) {
  const credits = bankCreditsList();
  const c = credits.find(x => x.id === cid); if (!c) return;
  const income = load('income') || [];
  const match = income.find(i => (i.status || 'pending') !== 'paid' && Math.abs(Number(i.amount) - c.amount) < 0.01);
  if (!match) { toast('ההכנסה התואמת כבר לא ממתינה'); return; }
  match.status = 'paid';
  match.paidAt = new Date().toISOString();
  save('income', income);
  bankCreditsSave(credits.filter(x => x.id !== cid));
  if (window.haptic) window.haptic.success();
  try { mptConfetti(['💰', '🪙', '✨', '⭐']); } catch (_) {}
  toast('💰 ' + fmtMoney(c.amount) + ' נגבה — כל הכבוד!');
  refreshAll();
};
window.bankCreditAdd = function(cid) {
  const credits = bankCreditsList();
  const c = credits.find(x => x.id === cid); if (!c) return;
  if (!confirm('להוסיף הכנסה של ' + fmtMoney(c.amount) + (c.name ? ' מ-' + c.name : '') + '?')) return;
  const income = load('income') || [];
  income.push({
    id: genId(), date: c.date, amount: c.amount, clientId: '',
    clientName: c.name || '', description: (c.name || 'העברה בנקאית') + ' · מהבנק',
    category: 'אחר', notes: 'זוהה אוטומטית מדיסקונט', status: 'paid',
    paidAt: new Date().toISOString()
  });
  income.sort((a, b) => new Date(b.date) - new Date(a.date));
  save('income', income);
  bankCreditsSave(credits.filter(x => x.id !== cid));
  if (window.haptic) window.haptic.success();
  toast('✓ נוספה הכנסה — ' + fmtMoney(c.amount));
  refreshAll();
};
window.bankCreditDismiss = function(cid) {
  bankCreditsSave(bankCreditsList().filter(x => x.id !== cid));
  renderBankCredits();
};
