function doLogin() {
  const val = document.getElementById('login-pass').value;
  if (val === PASS) {
    document.getElementById('login-screen').classList.add('hidden');
    document.getElementById('login-pass').value = '';
    document.getElementById('mode-screen').classList.remove('hidden');
    try { renderLobbyTasks(); } catch(e) {}
    try { refreshLobbyGreeting(); } catch(e) {}
    try { yearGoalsLobby(); } catch(e) {}
  } else {
    const err = document.getElementById('login-err');
    err.textContent = '❌ סיסמא שגויה';
    document.getElementById('login-pass').value = '';
    document.getElementById('login-pass').focus();
    setTimeout(() => err.textContent = '', 2000);
  }
}

// Capacitor wraps the app in a Capacitor:// (iOS) or http://localhost
// (Android) WebView — both expose `window.Capacitor`. Inside the native
// app, the device itself is already personal, so the password gate adds
// nothing but friction (and pops the keyboard the moment you open it).
// Auto-skip straight to the lobby.
(function autoLoginOnNative() {
  if (!window.Capacitor || !window.Capacitor.isNativePlatform || !window.Capacitor.isNativePlatform()) return;
  const skip = () => {
    const login = document.getElementById('login-screen');
    const mode  = document.getElementById('mode-screen');
    if (!login || !mode) return;
    login.classList.add('hidden');
    mode.classList.remove('hidden');
    try { renderLobbyTasks(); } catch(e) {}
    try { refreshLobbyGreeting(); } catch(e) {}
    try { yearGoalsLobby(); } catch(e) {}
  };
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', skip);
  } else {
    skip();
  }
})();

