// Human-readable day: היום / מחר / יום חמישי השבוע / יום שלישי שבוע הבא
function _waHumanDay(ds, withDate) {
  try {
    const names = ['ראשון', 'שני', 'שלישי', 'רביעי', 'חמישי', 'שישי', 'שבת'];
    const now = new Date();
    const t0 = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const d = new Date(ds + 'T12:00:00');
    const diff = Math.round((new Date(d.getFullYear(), d.getMonth(), d.getDate()) - t0) / 86400000);
    const dm = d.getDate() + '.' + (d.getMonth() + 1);
    let label;
    if (diff === 0) label = 'היום';
    else if (diff === 1) label = 'מחר';
    else if (diff === 2) label = 'מחרתיים';
    else {
      const weekOff = Math.floor((t0.getDay() + diff) / 7);
      label = 'יום ' + names[d.getDay()] + (weekOff === 0 ? ' השבוע' : weekOff === 1 ? ' שבוע הבא' : '');
    }
    return withDate ? label + ' · ' + dm : label;
  } catch (_) { return ds; }
}
