  for (const p in _waRenames) if (hit(_waRenames[p])) return p;
  const cl = (load('clients') || []).find(x => hit(x.name) && x.phone);
  if (cl) return _waPhone(cl.phone);
  for (const p in _waNames) if (hit(_waNames[p])) return p;
