  if (fbtn) fbtn.textContent = showAll ? 'מציג הכל' : 'לקוחות ולידים';
  // While a fresh pull is in flight, an empty box shows "מסנכרן…"
  // instead of a triumphant "אין הודעות" — so a mid-work glance never
  // reads a not-yet-loaded list as "nothing waiting".
  const syncing = '<div class="mp-empty" style="padding:10px 0">⏳ מסנכרן…</div>';
  topEl.innerHTML = topWait.length
    ? topWait.map(c => _waRow(c, true)).join('')
    : (_waSyncing ? syncing : '<div class="mp-empty" style="padding:10px 0">🎉 אין הודעות שמחכות מלקוחות.</div>');
  newEl.innerHTML = newWait.length
    ? newWait.map(c => _waRow(c, true)).join('')
    : (_waSyncing ? syncing : '<div class="mp-empty" style="padding:10px 0">אין פניות חדשות.</div>');
  // "כל הלקוחות" fold: answered client conversations + marked clients
  // with no recent messages. The <details> open state lives in static
