  const inList = {};
  _waConvs.forEach(c => { if (c.cls === 'client') inList[c.phone] = true; });
  const extra = Object.keys(_waCliMarks).filter(p => _waCliMarks[p] === true && !inList[p]);
  const sumEl = document.getElementById('wa-all-clients-sum');
  if (sumEl) sumEl.textContent = 'כל הלקוחות (' + (rest.length + extra.length + topWait.length) + ')';
  const foldEl = document.getElementById('wa-all-clients');
