    const t = m.time ? ymd + 'T' + m.time.replace(':', '') + '00' : ymd, e = m.time ? (() => { const [H, M] = m.time.split(':').map(Number), z = H * 60 + M + 60; return ymd + 'T' + p(Math.floor(z / 60) % 24) + p(z % 60) + '00'; })() : ymd;
