  const cur = new Date(_scheduleDate + 'T00:00:00'), start = new Date(cur); start.setDate(cur.getDate() - cur.getDay());
  const todayK = dailyDateStr(), manual = load('schedule') || [];
  // v562: one long strip of days you scroll left/right (no arrows)
