  try { (window._eventKitCache || []).forEach(ev => ev && ev.date && has.add(ev.date)); (window._icsEventsCache || []).forEach(ev => ev && ev.date && has.add(ev.date));
    (typeof _gcalEventsCache !== 'undefined' && _gcalEventsCache || []).forEach(e => { const st = e && e.status !== 'cancelled' && e.start && (e.start.dateTime || e.start.date); if (st) has.add(String(st).slice(0, 10)); }); } catch (_) {}
