function renderSchedule() {
  const listEl  = document.getElementById('schedule-list');
  const labelEl = document.getElementById('schedule-date-label');
  const todayBtn = document.getElementById('schedule-today-btn');
  const picker  = document.getElementById('schedule-date-picker');
  if (!listEl) return;
  if (labelEl) {
    // Keep the overlay <input type=date> child intact — set the
    // label text without wiping the picker.
    const label = _scheduleDateLabel(_scheduleDate);
    if (picker) {
      labelEl.firstChild && labelEl.firstChild.nodeType === 3
        ? labelEl.firstChild.nodeValue = label
        : labelEl.insertBefore(document.createTextNode(label), picker);
    } else {
      labelEl.textContent = label;
    }
  }
  if (picker) picker.value = _scheduleDate;
  if (todayBtn) todayBtn.style.display = (_scheduleDate === dailyDateStr()) ? 'none' : '';

  // Manual items + Google events for the displayed date, merged
  // into one chronological list. Google events keep a flag so we
  // can disable edit/delete on them (only Google itself can edit).
  const manualItems = (load('schedule') || [])
    .filter(it => it.date === _scheduleDate)
    .map(it => Object.assign({}, it, { _source: 'manual' }));
  // De-dup: every manual item we already pushed to EventKit has its
  // gcalEventId stamped on it (returned by Cal.createEvent). The
  // matching EventKit event will reappear on the next refresh —
  // skip it so the row doesn't render twice.
  const claimedGcalIds = new Set(
    manualItems.filter(it => it.gcalEventId).map(it => String(it.gcalEventId))
  );
  const gcalRaw = gcalEventsForDate(_scheduleDate)
    .filter(e => !claimedGcalIds.has(String(e.id || '').replace(/^ek_/, '')));
  const gcalItems = gcalRaw.map(e => {
    const startDt = (e.start && e.start.dateTime) || '';
    const time = startDt ? startDt.split('T')[1].slice(0, 5) : '00:00';
    return {
      id:      'gcal_' + e.id,
      date:    _scheduleDate,
      time:    time,
      title:   e.summary || '(אירוע ללא שם)',
      _source: 'gcal',
      _gcalId: e.id
    };
  });
  const items = manualItems.concat(gcalItems).sort((a, b) => a.time.localeCompare(b.time));
  if (_spSkin()) { _schedSpent(items, listEl); return; }

  if (!items.length) {
    listEl.innerHTML =
      '<div class="empty-state" style="padding:32px 18px;text-align:center;color:var(--text-muted)">' +
        '<svg style="width:42px;height:42px;opacity:0.4;margin-bottom:10px"><use href="#ic-calendar"/></svg>' +
        '<div style="font-size:15px;font-weight:600">פנוי ' + (_scheduleDate === dailyDateStr() ? 'היום' : 'ביום הזה') + '</div>' +
        '<div style="font-size:12.5px;margin-top:4px">הוסף פעילות חדשה למעלה</div>' +
      '</div>';
    return;
  }

  listEl.innerHTML = items.map(it => {
    const { color } = _scheduleProximity(it.date, it.time);
    const isGcal = (it._source === 'gcal');
    // EventKit items (id prefix `gcal_ek_…`) are editable round-trip
    // via the IosCalendar plugin. ICS / OAuth items stay read-only.
    const isEditable = !isGcal || (typeof it.id === 'string' && it.id.indexOf('gcal_ek_') === 0);
    const tap = isEditable
      ? 'onclick="editScheduleItem(\'' + it.id + '\')"'
      : '';
    const cursor = isEditable ? 'pointer' : 'default';
    const leftStripe = isGcal ? 'border-right:3px solid #4285f4;' : '';
    const trashBtn = isEditable
      ? '<button class="row-icon-btn" onclick="event.stopPropagation(); deleteScheduleItem(\'' + it.id + '\')" title="מחק" style="background:transparent;border:1px solid var(--border);border-radius:8px;width:32px;height:32px;display:inline-flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0">' +
          '<svg style="width:14px;height:14px;color:#b8442e"><use href="#ic-trash"/></svg>' +
        '</button>'
      : '<span style="width:32px;height:32px;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0" title="אירוע מ-Google — ערוך ב-Google Calendar">' +
          '<svg viewBox="0 0 24 24" width="14" height="14" style="opacity:0.7">' +
            '<rect x="3" y="5" width="18" height="16" rx="2" fill="none" stroke="#4285f4" stroke-width="2"/>' +
            '<line x1="3" y1="10" x2="21" y2="10" stroke="#4285f4" stroke-width="2"/>' +
          '</svg>' +
        '</span>';
    return (
      '<div class="schedule-row" ' + tap + ' style="display:flex;align-items:center;gap:12px;padding:12px 14px;border:1.5px solid var(--border);' + leftStripe + 'border-radius:14px;background:var(--surface);margin-bottom:10px;box-shadow:0 2px 8px rgba(0,0,0,0.04);cursor:' + cursor + ';transition:transform .15s,border-color .15s,box-shadow .15s" ' +
           (isEditable ? 'onmouseover="this.style.borderColor=\'var(--accent)\'" onmouseout="this.style.borderColor=\'var(--border)\'"' : '') + '>' +
        '<span style="width:11px;height:11px;border-radius:50%;background:' + color + ';box-shadow:0 0 8px ' + color + '55;flex-shrink:0"></span>' +
        '<div style="font-family:Rubik,sans-serif;font-weight:800;font-size:18px;color:' + (isGcal ? '#4285f4' : 'var(--accent)') + ';min-width:54px;letter-spacing:-0.02em">' + it.time + '</div>' +
        '<div style="flex:1;font-size:15px;font-weight:700;color:var(--text);min-width:0">' + _escHtml(it.title) + '</div>' +
        trashBtn +
      '</div>'
    );
  }).join('');
}

function _escHtml(s) {
  return String(s).replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
}

function changeDailyDate(dir) {
  const d = new Date(_dailyDate + 'T00:00:00');
  d.setDate(d.getDate() + dir);
  _dailyDate = dailyDateStr(d);
  renderDaily();
}

function goDailyToday() { _dailyDate = dailyDateStr(); renderDaily(); }

function addDailyTask() {
  const inp = document.getElementById('daily-input');
  const text = (inp?.value || '').trim();
  if (!text) { inp?.focus(); return; }
  askReminderTime(text, function(remindAt) {
    const all = load('daily_tasks');
    const task = { id: genId(), date: _dailyDate, text, done: false, createdAt: new Date().toISOString() };
    if (remindAt) task.remindAt = remindAt.toISOString();
    all.push(task);
    save('daily_tasks', all);
    if (remindAt) _scheduleDailyTaskNotif(task);
    if (inp) { inp.value = ''; inp.focus(); }
    renderDaily();
  });
}

function toggleDailyDone(id) {
  const all = load('daily_tasks');
  const t = all.find(x => x.id === id);
  if (t) { t.done = !t.done; save('daily_tasks', all); renderDaily(); }
}

function deleteDailyTask(id) {
  save('daily_tasks', load('daily_tasks').filter(t => t.id !== id));
  renderDaily();
}

// ===== LOBBY TASKS — visible before picking a mode =====
function _lobbyRelativeDate(date) {
  const today = dailyDateStr();
  if (date === today) return '';
  const d1 = new Date(date + 'T00:00:00');
  const d2 = new Date(today + 'T00:00:00');
  const diff = Math.round((d2 - d1) / 86400000);
  if (diff === 1) return 'אתמול';
  if (diff > 0 && diff < 7) return 'לפני ' + diff + ' ימים';
  if (diff < 0) return 'מחר';
  return d1.toLocaleDateString('he-IL', {day:'numeric', month:'numeric'});
}

function _lobbyOpenTasks() {
  const today = dailyDateStr();
  const open = load('daily_tasks').filter(t => !t.done && t.date <= today);
  // Manually dragged priority first (lower order = higher up = more urgent),
  // then anything without an order falls back to date / creation time.
  open.sort((a,b) => {
    const ao = typeof a.order === 'number' ? a.order : 9e9;
    const bo = typeof b.order === 'number' ? b.order : 9e9;
    if (ao !== bo) return ao - bo;
    return a.date.localeCompare(b.date) || new Date(a.createdAt||0) - new Date(b.createdAt||0);
  });
  return open;
}

function renderLobbyTasks() {
  const listEl = document.getElementById('lobby-tasks-list');
  if (!listEl) return;
  const open = _lobbyOpenTasks();
  const countEl = document.getElementById('lobby-tasks-count');
  if (countEl) {
    if (!open.length) countEl.textContent = '☀️ הכל סגור';
    else if (open.length === 1) countEl.textContent = 'משימה אחת פתוחה';
    else countEl.textContent = open.length + ' פתוחות';
  }
  // Adaptive density: tighten the rest of the lobby as task count grows
  const ms = document.getElementById('mode-screen');
  if (ms) {
    ms.classList.remove('density-cozy', 'density-medium', 'density-tight');
    if (open.length >= 5) ms.classList.add('density-tight');
    else if (open.length >= 3) ms.classList.add('density-medium');
    else ms.classList.add('density-cozy');
  }
  if (!open.length) {
    listEl.innerHTML = '<div class="lobby-empty">אין משימות פתוחות. מה רוצה להוסיף?</div>';
    return;
  }
  const max = 5;
  const visible = open.slice(0, max);
  const overflow = open.length - max;
  listEl.innerHTML = visible.map(t => {
    const rel = _lobbyRelativeDate(t.date);
    const dateChip = rel ? '<div class="lobby-task-date">' + rel + '</div>' : '';
    const safeId = t.id.replace(/'/g, "\\'");
    return '<div class="lobby-task" data-task-id="' + t.id + '" onclick="toggleLobbyTask(event,\'' + safeId + '\')">' +
      '<div class="lobby-task-handle" aria-label="גרור לסידור">⋮⋮</div>' +
      '<div class="lobby-task-check"></div>' +
      '<div class="lobby-task-text">' + _escHtml(t.text) + '</div>' +
      dateChip +
      '<button class="lobby-task-edit-btn" onclick="editLobbyTask(event,\'' + safeId + '\')" aria-label="ערוך"><svg viewBox="0 0 24 24" style="width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round"><use href="#ic-edit"/></svg></button>' +
    '</div>';
  }).join('') + (overflow > 0 ? '<div class="lobby-task-more">ועוד ' + overflow + ' משימות</div>' : '');
  _initLobbySortable();
}

// Inline text editing — click the ✏️ button, the text turns into an
// input pre-filled and focused. Enter/blur saves, Escape cancels.
function editLobbyTask(ev, id) {
  if (ev) { ev.stopPropagation(); ev.preventDefault(); }
  const row = (ev && ev.target && ev.target.closest('.lobby-task')) || document.querySelector('.lobby-task[data-task-id="' + id + '"]');
  if (!row) return;
  const textEl = row.querySelector('.lobby-task-text');
  if (!textEl || row.querySelector('.lobby-task-edit-input')) return;
  const original = textEl.textContent;
  const input = document.createElement('input');
  input.type = 'text';
  input.className = 'lobby-task-edit-input';
  input.value = original;
  input.maxLength = 200;
  textEl.replaceWith(input);
  // Temporarily disable Sortable on this row so the keyboard interaction
  // doesn't get hijacked by long-press detection.
  const list = document.getElementById('lobby-tasks-list');
  if (list && list._sortable) list._sortable.option('disabled', true);
  let committed = false;
  function commit(saveIt) {
    if (committed) return; committed = true;
    const newText = (input.value || '').trim();
    if (saveIt && newText && newText !== original) {
      const all = load('daily_tasks');
      const t = all.find(x => x.id === id);
      if (t) { t.text = newText; save('daily_tasks', all); }
      if (document.getElementById('daily-list')) { try { renderDaily(); } catch(e){} }
    }
    if (list && list._sortable) list._sortable.option('disabled', false);
    renderLobbyTasks();
  }
  input.addEventListener('blur', function() { commit(true); });
  input.addEventListener('keydown', function(e) {
    if (e.key === 'Enter') { e.preventDefault(); commit(true); }
    else if (e.key === 'Escape') { e.preventDefault(); committed = true; renderLobbyTasks(); }
  });
  setTimeout(function() { input.focus(); input.select(); }, 10);
}

function _initLobbySortable() {
  const list = document.getElementById('lobby-tasks-list');
  if (!list || typeof Sortable === 'undefined') return;
  if (list._sortable) { try { list._sortable.destroy(); } catch(e){} }
  list._sortable = Sortable.create(list, {
    handle: '.lobby-task-handle',
    animation: 180,
    ghostClass: 'lobby-task-ghost',
    chosenClass: 'lobby-task-chosen',
    dragClass: 'lobby-task-drag',
    forceFallback: true,   // use Sortable's own drag implementation — more
    fallbackOnBody: true,  // reliable on iOS PWA than the HTML5 drag-and-drop
    fallbackTolerance: 4,
    filter: '.lobby-task-more',
    onEnd: function() {
      // Persist whatever order is now visible. Only the visible rows
      // (top 5) get explicit orders so dragging stays local to the
      // "above the fold" list.
      const rows = Array.from(list.querySelectorAll('.lobby-task'));
      const ids = rows.map(el => el.getAttribute('data-task-id'));
      const all = load('daily_tasks');
      ids.forEach((id, i) => {
        const t = all.find(x => x.id === id);
        if (t) t.order = i;
      });
      save('daily_tasks', all);
      // Re-sort the main daily page if it's mounted
      if (document.getElementById('daily-list')) { try { renderDaily(); } catch(e){} }
    },
  });
}

function addLobbyTask() {
  const inp = document.getElementById('lobby-task-input');
  const text = (inp && inp.value || '').trim();
  if (!text) { if (inp) inp.focus(); return; }
  // Ask for reminder time, then save.
  askReminderTime(text, function(remindAt) {
    _saveLobbyTask(text, remindAt);
    if (inp) { inp.value = ''; inp.focus(); }
  });
}

function _saveLobbyTask(text, remindAt) {
  const today = dailyDateStr();
  const all = load('daily_tasks');
  const orders = all.filter(t => !t.done && typeof t.order === 'number').map(t => t.order);
  const nextOrder = orders.length ? Math.max.apply(null, orders) + 1 : 0;
  const task = { id: genId(), date: today, text, done: false, order: nextOrder, createdAt: new Date().toISOString() };
  if (remindAt) task.remindAt = remindAt.toISOString();
  all.push(task);
  save('daily_tasks', all);
  if (remindAt) _scheduleDailyTaskNotif(task);
  renderLobbyTasks();
  if (document.getElementById('daily-list')) { try { renderDaily(); } catch(e){} }
}

async function _scheduleDailyTaskNotif(task) {
  if (!window.Capacitor || !window.Capacitor.isNativePlatform || !window.Capacitor.isNativePlatform()) return;
  if (!task.remindAt) return;
  const at = new Date(task.remindAt);
  if (at <= new Date()) return;
  const LN = window.Capacitor.Plugins && window.Capacitor.Plugins.LocalNotifications;
  if (!LN) return;
  const numId = Math.abs(task.id.split('').reduce((h, c) => (h * 31 + c.charCodeAt(0)) | 0, 0));

  // Format the body like "מתוזמן ל-14:30 · יום ראשון". iOS already
  // shows "Ravid Studio" as the source above the title, so the title
  // is just the task text, no brand prefix needed.
  const days = ['ראשון','שני','שלישי','רביעי','חמישי','שישי','שבת'];
  const sameDay = at.toDateString() === new Date().toDateString();
  const tomorrow = new Date(); tomorrow.setDate(tomorrow.getDate() + 1);
  const isTomorrow = at.toDateString() === tomorrow.toDateString();
  const time = String(at.getHours()).padStart(2,'0') + ':' + String(at.getMinutes()).padStart(2,'0');
  const dayLabel = sameDay ? 'היום' : isTomorrow ? 'מחר' : 'יום ' + days[at.getDay()];
  const bodyText = `מתוזמן ל-${time} · ${dayLabel}`;

  try {
    await LN.cancel({ notifications: [{ id: numId }] }).catch(() => {});
    await LN.schedule({
      notifications: [{
        id: numId,
        title: task.text,
        subtitle: 'Maestro',
        body: bodyText,
        schedule: { at: at, allowWhileIdle: true },
        sound: _notifSound(),
        actionTypeId: 'TASK_REMINDER',
        group: 'task-reminders',
        threadIdentifier: 'task-reminders',
        summaryArgument: 'תזכורות משימות',
        extra: { dailyTaskId: task.id }
      }]
    });
  } catch (e) { console.warn('daily task notif failed', e); }
}

// One-time setup: register the "סיימתי / דחה 10 דק'" action buttons
// and wire up the listener that handles taps on them.
async function _setupNativeNotifActions() {
  if (!window.Capacitor || !window.Capacitor.isNativePlatform || !window.Capacitor.isNativePlatform()) return;
  const LN = window.Capacitor.Plugins && window.Capacitor.Plugins.LocalNotifications;
  if (!LN) return;
  try {
    await LN.registerActionTypes({
      types: [{
        id: 'TASK_REMINDER',
        actions: [
          { id: 'done',   title: 'סיימתי' },
          { id: 'snooze', title: 'דחה 10 דק׳' }
        ]
      }]
    });
  } catch (e) {}
  try {
    LN.addListener('localNotificationActionPerformed', async function(event) {
      const action = event && event.actionId;
      const extra  = (event && event.notification && event.notification.extra) || {};
      const taskId = extra.dailyTaskId;
      if (!taskId) return;
      if (action === 'done') {
        const all = load('daily_tasks');
        const t = all.find(function(x) { return x.id === taskId; });
        if (t) { t.done = true; save('daily_tasks', all); }
        try { renderDaily(); } catch(_) {}
        try { renderLobbyTasks(); } catch(_) {}
      } else if (action === 'snooze') {
        const all = load('daily_tasks');
        const t = all.find(function(x) { return x.id === taskId; });
        if (t) {
          t.remindAt = new Date(Date.now() + 10 * 60 * 1000).toISOString();
          save('daily_tasks', all);
          _scheduleDailyTaskNotif(t);
        }
      }
    });
  } catch (e) {}
}
if (window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform()) {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', _setupNativeNotifActions);
  } else {
    _setupNativeNotifActions();
  }
}

// ===== Face ID lock =====
// Calls @aparajita/capacitor-biometric-auth — the plugin is auto-
// registered with Capacitor's bridge as "BiometricAuthNative" after
// `npx cap sync ios`. We invoke `internalAuthenticate` directly so we
// don't need to load the plugin's ESM wrapper.
window.FACE_ID_PREF_KEY = 'face_id_enabled_v1';
window.getFaceIdEnabled = function() {
  // 9.10: ON unless he explicitly turned it off — a wiped localStorage
  // (app reinstall/update) must never silently drop the lock.
  try { return localStorage.getItem(window.FACE_ID_PREF_KEY) !== '0'; }
  catch (e) { return true; }
};
window.setFaceIdEnabled = function(on) {
  try { localStorage.setItem(window.FACE_ID_PREF_KEY, on ? '1' : '0'); }
  catch (e) {}
};
window.handleFaceIdToggle = async function(btn) {
  const isNative = !!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform());
  if (!isNative) {
    if (typeof toast === 'function') toast('Face ID זמין רק באפליקציה'); else alert('Face ID זמין רק באפליקציה');
    return;
  }
  const turningOn = !window.getFaceIdEnabled();
  if (turningOn) {
    // Verify Face ID actually works before persisting the preference —
    // otherwise the user could lock themselves out if biometry isn't
    // enrolled.
    const ok = await window._tryBiometricAuth('אישור הפעלת Face ID');
    if (!ok) {
      if (typeof toast === 'function') toast('הפעלת Face ID נכשלה'); else alert('הפעלת Face ID נכשלה');
      return;
    }
  }
  window.setFaceIdEnabled(turningOn);
  btn.classList.toggle('on', turningOn);
};
window._tryBiometricAuth = async function(reason) {
  // BiometricBridge is our own native Swift plugin (LAContext-based),
  // registered with the Capacitor bridge from BridgeViewController.
  const BA = window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.BiometricBridge;
  if (!BA) {
    if (typeof toast === 'function') toast('Face ID לא זמין במכשיר הזה');
    return false;
  }
  try {
    await BA.authenticate({
      reason:      reason || 'פתח את אליאור רביד',
      cancelTitle: 'בטל'
    });
    return true;
  } catch (e) {
    return false;
  }
};
// welcome screen copy (shown on the lock screen before Face ID)
window.flWelcomeFill = function() {
  const d = new Date(), h = d.getHours();
  const hello = h < 5 ? 'לילה טוב' : h < 12 ? 'בוקר טוב' : h < 17 ? 'צהריים טובים' : h < 21 ? 'ערב טוב' : 'לילה טוב';
  const lines = [
    'המנצח לא משמיע אף צליל.<br>הוא דואג שכולם ינגנו נכון.',
    'הכל מסודר ומחכה לך.<br>הראש פנוי למוזיקה.',
    'פחות ניהול, יותר מוזיקה.',
    'כל הפקה גדולה מתחילה ביום רגיל.',
    'האולפן שלך, בקצב שלך.',
    'יום טוב ליצור משהו שיישאר.',
    'הלקוחות, ההפקות והכסף —<br>הכל במקום אחד, בשקט.',
    'מה שחשוב היום כבר מחכה בפנים.'
  ];
  const days = ['ראשון','שני','שלישי','רביעי','חמישי','שישי','שבת'];
  const months = ['בינואר','בפברואר','במרץ','באפריל','במאי','ביוני','ביולי','באוגוסט','בספטמבר','באוקטובר','בנובמבר','בדצמבר'];
  const set = (id, html) => { const el = document.getElementById(id); if (el) el.innerHTML = html; };
  set('fl-date', 'יום ' + days[d.getDay()] + ', ' + d.getDate() + ' ' + months[d.getMonth()]);
  set('fl-hello', hello + ', <b>אליאור</b>');
  set('fl-line', lines[Math.floor(Math.random() * lines.length)]);
};
let _faInFlight = false;
window.tryFaceId = async function() {
  // Serialize: a resume can fire visibilitychange more than once, and
  // two parallel LAContext prompts cancel each other ("צריך פעמיים").
  if (_faInFlight) return;
  _faInFlight = true;
  try {
    const t0 = Date.now();
    let ok = await window._tryBiometricAuth('פתח את אליאור רביד');
    // An INSTANT failure (<800ms) means iOS refused because the app
    // wasn't fully active yet — not that the user failed or canceled.
    // One silent retry after the scene settles fixes it invisibly.
    if (!ok && Date.now() - t0 < 800) {
      await new Promise(r => setTimeout(r, 450));
      ok = await window._tryBiometricAuth('פתח את אליאור רביד');
    }
    document.documentElement.classList.toggle('face-id-locked', !ok);
  } finally { _faInFlight = false; }
};
// ===== Home-screen Widget bridge =====
// Pushes a single GENERIC payload into the App Group container that
// the WidgetKit extension reads from. Every visible piece of text
// and colour comes from this JSON — the Swift widget is a "dumb"
// renderer. That means future widget content/colour tweaks (new
// header text, new color logic, more/less items) can be done by
// editing the JS below without rebuilding the IPA.
//
// Wire format the widget understands:
//   { headerTitle, headerSubtitle, accent,
//     emptyTitle, emptyText, emptyEmoji,
//     items: [
//       { id, title, subtitle, dotColor, urgency }
//     ] }
window._buildWidgetPayload = function() {
  // 1. Today's items from EVERY source — manual schedule, EventKit
  //    (Google Calendar via iOS sync), sorted by time with proximity
  //    colours. The widget renders whichever list is non-empty.
  const todayStr = (typeof dailyDateStr === 'function') ? dailyDateStr() : new Date().toISOString().slice(0,10);
  const manualRaw = (load('schedule') || [])
    .filter(it => it && it.date === todayStr && it.title);
  const manual = manualRaw.map(it => ({ id: String(it.id || ''), title: it.title, time: it.time }));
  // De-dup against EventKit by the gcalEventId we stamped at create-time.
  const claimedEkIds = new Set(
    manualRaw.filter(it => it.gcalEventId).map(it => String(it.gcalEventId))
  );
  const fromEk = (window._eventKitCache || [])
    .filter(ev => ev && ev.date === todayStr && ev.title && !claimedEkIds.has(String(ev.id || '')))
    .map(ev => ({ id: 'ek_' + ev.id, title: ev.title, time: ev.time }));
  const sched = manual.concat(fromEk).sort((a, b) =>
    String(a.time || '').localeCompare(String(b.time || ''))
  );
  const schedItems = sched.map(it => {
    const prox = (typeof _scheduleProximity === 'function')
      ? _scheduleProximity(todayStr, it.time)
      : { color: '#a78bfa', urgency: 1 };
    return {
      id:       String(it.id || ''),
      title:    String(it.title || ''),
      subtitle: String(it.time || ''),
      dotColor: prox.color,
      urgency:  prox.urgency
    };
  });
  // 2. Fall back to open daily-tasks if the schedule is empty for today.
  let items, headerTitle, emptyTitle, emptyText;
  if (schedItems.length) {
    items       = schedItems;
    headerTitle = 'הלוז של היום';
    emptyTitle  = 'פנוי היום';
    emptyText   = 'אין פעילויות מתוכננות';
  } else {
    const openTasks = (load('daily_tasks') || []).filter(t => t && !t.done && t.text);
    items = openTasks.map(t => ({
      id:       String(t.id || ''),
      title:    String(t.text || ''),
      subtitle: '',
      dotColor: '#d99e66',
      urgency:  1
    }));
    headerTitle = 'המשימות שלי';
    emptyTitle  = 'הכל בוצע';
    emptyText   = 'אין משימות פתוחות';
  }
  // 3. Lock-screen accessory copy — keep it short and concrete.
  //    Title gets its own (potentially wrapping) line; the time and
  //    "+X more" hint live on the secondary line so the title isn't
  //    competing with metadata for horizontal space.
  let lockTitle, lockSubtitle;
  if (schedItems.length) {
    const upcoming = schedItems.find(it => (it.urgency || 0) > 0) || schedItems[0];
    lockTitle = upcoming.title;
    const time = upcoming.subtitle || '';
    const moreCount = schedItems.length - 1;
    const moreTxt = moreCount > 0 ? ' · +' + moreCount + ' היום' : '';
    lockSubtitle = (time ? time : 'הפעילות הקרובה') + moreTxt;
  } else if (items.length) {
    lockTitle    = items[0].title;
    lockSubtitle = items.length === 1
      ? 'משימה אחת פתוחה'
      : items.length + ' משימות פתוחות';
  } else {
    lockTitle    = 'אליאור רביד';
    lockSubtitle = 'פנוי היום';
  }
  return {
    headerTitle:    headerTitle,
    headerSubtitle: '',
    accent:         '#d99e66',
    emptyTitle:     emptyTitle,
    emptyText:      emptyText,
    emptyEmoji:     '✓',
    lockTitle:      lockTitle,
    lockSubtitle:   lockSubtitle,
    items:          items
  };
};

window.syncTasksToWidget = function(_unused) {
  const isNative = !!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform());
  if (!isNative) return;
  const Bridge = window.Capacitor.Plugins && window.Capacitor.Plugins.TaskWidgetBridge;
  if (!Bridge) return;
  try {
    const payload = window._buildWidgetPayload();
    // Two paths for forward-compat: new flexible payload + the
    // legacy `tasks` array (the old Swift code in shipped builds
    // still reads this). Once everyone is on the new build, the
    // tasks-array path becomes a no-op.
    if (typeof Bridge.syncPayload === 'function') {
      Bridge.syncPayload({ payload: payload }).catch(function() {});
    }
    if (typeof Bridge.syncTasks === 'function') {
      Bridge.syncTasks({ tasks: payload.items.map(it => ({
        id: it.id, title: it.title, done: false
      })) }).catch(function() {});
    }
  } catch (e) {}
};
// Push the current snapshot once at startup so a freshly-installed
// widget has data before the user creates/toggles anything.
(function pushInitialWidgetSync() {
  const isNative = !!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform());
  if (!isNative) return;
  function attempt() {
    try { window.syncTasksToWidget(); } catch (e) {}
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', attempt);
  } else {
    attempt();
  }
})();

// ===== Haptic Feedback =====
// Thin wrapper around @capacitor/haptics. All methods are no-ops on
// the web build / when permission/plugin missing — so callers can
// fire-and-forget without guards.
// v605: Maestro's own notification sound (file is bundled in the iOS app)
// every scheduled notification gets the chosen sound unless it set one
(function () { let tries = 0; const wrap = () => { const LN = window.Capacitor && Capacitor.Plugins && Capacitor.Plugins.LocalNotifications;
  if (!LN || !LN.schedule) { if (++tries < 20) setTimeout(wrap, 500); return; } if (LN._mzWrapped) return; const orig = LN.schedule.bind(LN);
  LN.schedule = o => { try { (o && o.notifications || []).forEach(n => { if (!n.sound || n.sound === 'default') n.sound = _notifSound(); if (n.sound === 'default') delete n.sound; }); } catch (_) {} return orig(o); }; LN._mzWrapped = 1; };
  setTimeout(wrap, 300); })();
const _NOTIF_SOUNDS = [['maestro-signature.wav', 'חתימה'], ['maestro-marimba.wav', 'מאסטרו'], ['maestro-breath.wav', 'נשימה'], ['maestro-drop.wav', 'טיפה'], ['default', 'צליל רגיל של האייפון']];
function _notifSound() { try { const v = localStorage.getItem('notif_sound'); if (v && _NOTIF_SOUNDS.some(x => x[0] === v)) return v; } catch (_) {} return 'maestro-signature.wav'; }
function _notifSoundName() { const f = _notifSound(); return (_NOTIF_SOUNDS.find(x => x[0] === f) || [0, ''])[1]; }
window.notifSoundPick = function() {
  const cur = _notifSound();
  spentSheet('צליל ההתראות', 'נשמע בכל התראה של Maestro', _NOTIF_SOUNDS.map(([f, n]) => ({ label: (f === cur ? '✓ ' : '') + n, pri: f === cur, run: () => {
    try { localStorage.setItem('notif_sound', f); } catch (_) {}
    const el = document.getElementById('notif-sound-name'); if (el) el.textContent = n;
    toast('צליל: ' + n + ' · שולח התראת בדיקה'); try { testNotification(); } catch (_) {}
    // reschedule everything already queued with the new sound
    try { fcScheduleReminders(); } catch (_) {} try { srScheduleNotif(); } catch (_) {} try { planScheduleNotif(); } catch (_) {}
  } })));
};
window.haptic = (function() {
  function getPlugin() {
    return window.Capacitor &&
           window.Capacitor.Plugins &&
           window.Capacitor.Plugins.Haptics;
  }
  return {
    tap:     function() { const H = getPlugin(); if (H && H.impact)         H.impact({ style: 'LIGHT'  }).catch(function(){}); },
    medium:  function() { const H = getPlugin(); if (H && H.impact)         H.impact({ style: 'MEDIUM' }).catch(function(){}); },
    heavy:   function() { const H = getPlugin(); if (H && H.impact)         H.impact({ style: 'HEAVY'  }).catch(function(){}); },
    success: function() { const H = getPlugin(); if (H && H.notification)   H.notification({ type: 'SUCCESS' }).catch(function(){}); },
    warn:    function() { const H = getPlugin(); if (H && H.notification)   H.notification({ type: 'WARNING' }).catch(function(){}); },
    error:   function() { const H = getPlugin(); if (H && H.notification)   H.notification({ type: 'ERROR'   }).catch(function(){}); },
    select:  function() { const H = getPlugin(); if (H && H.selectionStart) H.selectionStart().catch(function(){}); },
    light:   function() { const H = getPlugin(); if (H && H.impact)         H.impact({ style: 'LIGHT'  }).catch(function(){}); }
  };
})();
// v600: a soft tap under the finger on every press in the new design (throttled)
(function () {
  let last = 0;
  document.addEventListener('click', e => {
    if (document.documentElement.getAttribute('data-skin') !== 'spent') return;
    const t = e.target && e.target.closest && e.target.closest('button, .fz-row, .ex-cat, .notif-toggle, .fcs-tick, .fz-focus, .payment-step, .oz-nav button, a');
    if (!t) return; const n = Date.now(); if (n - last < 70) return; last = n;
    try { window.haptic.tap(); } catch (_) {}
  }, true);
})();

// v600: big numbers count up to their value (only when the value changes; respects reduced motion)
(function () {
  const reduce = () => { try { return matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (_) { return false; } };
  const last = new Map();
  const run = el => {
    if (el._cnt) return; const txt = el.textContent; const m = /^([^\d-]*)(-?[\d,]+)(.*)$/.exec(txt); if (!m) return;
    const to = Number(m[2].replace(/,/g, '')); if (!isFinite(to)) return;
    const key = (el.closest('[id]') || {}).id + '|' + (el.className || '');
    const from = last.has(key) ? last.get(key) : 0; last.set(key, to);
    if (from === to || reduce() || Math.abs(to) < 10) return;
    el._cnt = 1; const t0 = performance.now(), D = 650, fmt = n => m[1] + Math.round(n).toLocaleString('en-US') + m[3];
    const step = t => { const k = Math.min(1, (t - t0) / D), e = 1 - Math.pow(1 - k, 3); el.textContent = fmt(from + (to - from) * e); if (k < 1) requestAnimationFrame(step); else { el.textContent = txt; el._cnt = 0; } };
    requestAnimationFrame(step);
  };
  const scan = root => { if (document.documentElement.getAttribute('data-skin') !== 'spent') return; (root.querySelectorAll ? root : document).querySelectorAll('.fz-big .n').forEach(run); };
  new MutationObserver(ms => ms.forEach(mu => mu.addedNodes.forEach(n => { if (n.nodeType === 1) { if (n.matches && n.matches('.fz-big .n')) run(n); else if (n.querySelector) scan(n); } }))).observe(document.documentElement, { childList: true, subtree: true });
})();

// ===== App-icon badge =====
// Computes a single number representing "you should look at this"
// — open tasks + overdue items — and asks the OS to draw it on the
// app icon. Called whenever the relevant data changes.
window.updateAppBadge = function() {
  const isNative = !!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform());
  if (!isNative) return;
  const Bridge = window.Capacitor.Plugins && window.Capacitor.Plugins.TaskWidgetBridge;
  if (!Bridge || !Bridge.setBadge) return;
  try {
    const today = (typeof dailyDateStr === 'function') ? dailyDateStr() : new Date().toISOString().slice(0,10);
    const tasks = load('daily_tasks') || [];
    // "Open" tasks dated today or earlier, not done.
    const openTasks = tasks.filter(function(t) {
      return t && !t.done && t.text && (!t.date || t.date <= today);
    });
    // Schedule items still upcoming today.
    const sched = (load('schedule') || []).filter(function(it) {
      return it && it.date === today;
    });
    const upcomingSched = sched.filter(function(it) {
      if (!it.time) return false;
      return new Date(it.date + 'T' + it.time + ':00').getTime() > Date.now();
    });
    const count = openTasks.length + upcomingSched.length;
    Bridge.setBadge({ count: count }).catch(function(){});
  } catch (e) {}
};

// ===== Quick Actions (long-press app icon) =====
// Cold launch: TaskWidgetBridge.consumePendingShortcut() returns the
// shortcut type the AppDelegate stashed before the WebView booted.
// Warm launch: BridgeViewController dispatches an 'app-shortcut'
// CustomEvent on window. Both paths converge on _handleShortcut.
window._handleShortcut = function(type) {
  if (!type) return;
  if (type === 'com.ravidstudio.app.add-income') {
    // Navigate to income page + open the add-income modal if available.
    try { if (typeof showPage === 'function') showPage('income'); } catch (e) {}
    setTimeout(function() {
      try { if (typeof openModal === 'function') openModal('income'); } catch (e) {}
    }, 80);
  } else if (type === 'com.ravidstudio.app.add-task') {
    try { if (typeof showPage === 'function') showPage('daily'); } catch (e) {}
    setTimeout(function() {
      const inp = document.getElementById('daily-input');
      if (inp) inp.focus();
    }, 100);
  } else if (type === 'com.ravidstudio.app.add-schedule') {
    try { if (typeof showPage === 'function') showPage('schedule'); } catch (e) {}
    setTimeout(function() {
      const inp = document.getElementById('schedule-title-input');
      if (inp) inp.focus();
    }, 100);
  }
};
window.addEventListener('app-shortcut', function(ev) {
  const type = ev && ev.detail && ev.detail.type;
  window._handleShortcut(type);
});
(function consumeColdLaunchShortcut() {
  const isNative = !!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform());
  if (!isNative) return;
  function attempt() {
    const Bridge = window.Capacitor.Plugins && window.Capacitor.Plugins.TaskWidgetBridge;
    if (!Bridge || !Bridge.consumePendingShortcut) return;
    Bridge.consumePendingShortcut()
      .then(function(res) {
        if (res && res.type) window._handleShortcut(res.type);
      })
      .catch(function(){});
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', attempt);
  } else {
    attempt();
  }
})();

(function setupFaceIdLock() {
  const isNative = !!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform());
  if (!isNative) return;
  // Arm the lock immediately on first script execution (before the
  // user can see the lobby), then run Face ID. The CSS gates the
  // overlay behind html.face-id-locked, so adding the class blocks
  // every interaction until biometry succeeds.
  function armAndAuth() {
    if (!window.getFaceIdEnabled()) return;
    document.documentElement.classList.add('face-id-locked');
    // No automatic prompt: the welcome screen shows first and the
    // "לכניסה" button starts Face ID.
    try { window.flWelcomeFill(); } catch (e) {}
  }
  armAndAuth();
  // Re-lock whenever the app comes back from background. iOS keeps
  // the WebView alive across home-button taps, so without this the
  // user only authenticates once per cold launch.
  document.addEventListener('visibilitychange', function() {
    if (!window.getFaceIdEnabled()) return;
    if (document.visibilityState === 'hidden') {
      // Cover BEFORE backgrounding: the app-switcher snapshot then
      // shows the branded lock screen, and on return there is no
      // blurred-content limbo while the WebView wakes up. Privacy
      // bonus: business data never appears in the app switcher.
      document.documentElement.classList.add('face-id-locked');
    } else {
      armAndAuth();
    }
  });
})();

function toggleLobbyTask(ev, id) {
  // Ignore clicks that originate from interactive children (drag handle,
  // edit button, or the inline-edit input) so they don't double-fire as
  // a "toggle done".
  if (ev && ev.target && (
        ev.target.closest('.lobby-task-handle') ||
        ev.target.closest('.lobby-task-edit-btn') ||
        ev.target.closest('.lobby-task-edit-input')
      )) return;
  const all = load('daily_tasks');
  const t = all.find(x => x.id === id);
  if (!t) return;
  t.done = !t.done;
  save('daily_tasks', all);
  const row = ev && ev.currentTarget;
  if (row && t.done) {
    row.classList.add('done');
    row.querySelector('.lobby-task-check').textContent = '✓';
    setTimeout(renderLobbyTasks, 220);
  } else {
    renderLobbyTasks();
  }
  if (document.getElementById('daily-list')) { try { renderDaily(); } catch(e){} }
}

function renderDaily() {
  const listEl = document.getElementById('daily-list');
  if (!listEl) return;
  const lblEl = document.getElementById('daily-date-label');
  const todayBtn = document.getElementById('daily-today-btn');

  const isToday = _dailyDate === dailyDateStr();
  const d = new Date(_dailyDate + 'T00:00:00');
  const dateText = d.toLocaleDateString('he-IL', { weekday: 'long', day: 'numeric', month: 'long' });
  if (lblEl) lblEl.textContent = (isToday ? 'היום · ' : '') + dateText;
  if (todayBtn) todayBtn.style.display = isToday ? 'none' : 'inline-flex';

  const items = load('daily_tasks').filter(t => t.date === _dailyDate);
  items.sort((a, b) => {
    if (a.done !== b.done) return a.done ? 1 : -1;
    return new Date(a.createdAt || 0) - new Date(b.createdAt || 0);
  });

  const total = items.length;
  const done = items.filter(t => t.done).length;

  if (total === 0) {
    listEl.innerHTML = `<div class="empty-state"><div class="ei"><svg><use href="#${isToday ? 'ic-sun-max' : 'ic-moon'}"/></svg></div><p>${isToday ? 'בוקר טוב! מה על הסדר היום?' : 'אין משימות ליום הזה'}</p></div>`;
    return;
  }

  const pct = Math.round((done / total) * 100);
  const allDone = done === total;
  const banner = `
    <div style="background:linear-gradient(135deg,var(--surface) 0%,var(--accent-light) 100%);border:1px solid var(--border-glow);border-radius:14px;padding:16px 18px;margin-bottom:18px;display:flex;align-items:center;gap:14px;flex-wrap:wrap">
      <div style="width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,var(--accent),var(--accent2));display:flex;align-items:center;justify-content:center;font-size:22px;flex-shrink:0;box-shadow:0 6px 18px var(--accent-glow)">${allDone ? '🎉' : '☀️'}</div>
      <div style="flex:1;min-width:160px">
        <div style="font-size:13px;font-weight:900;color:var(--text)">${allDone ? 'סיימת הכל — כל הכבוד, ביג׳ונדון!' : 'הסדר יום שלך'}</div>
        <div style="font-size:12px;color:var(--text-muted);margin-top:2px">${done} מתוך ${total} בוצעו</div>
      </div>
      <div style="font-size:26px;font-weight:900;color:var(--accent);font-variant-numeric:tabular-nums">${pct}%</div>
    </div>`;

  const cards = items.map(t => `
    <div class="task-card${t.done ? ' task-done' : ''}" style="margin-bottom:10px">
      <div style="display:flex;align-items:center;gap:12px">
        <button onclick="toggleDailyDone('${t.id}')" class="task-check${t.done ? ' checked' : ''}" title="${t.done ? 'בטל ביצוע' : 'סמן כבוצע'}">${t.done ? '✓' : ''}</button>
        <span class="task-title-text" style="flex:1;min-width:0;${t.done ? 'text-decoration:line-through;opacity:0.6' : ''}">${_escHtml(t.text)}</span>
        <button onclick="deleteDailyTask('${t.id}')" title="מחק" style="border:none;background:none;color:var(--text-muted);cursor:pointer;font-size:18px;padding:2px 4px;flex-shrink:0;opacity:0.6;transition:opacity .15s" onmouseover="this.style.opacity='1'" onmouseout="this.style.opacity='0.6'">×</button>
      </div>
    </div>`).join('');

  listEl.innerHTML = banner + cards;
}

// ===== DRAG & DROP AUDIO ON SKETCH/SONG DETAIL =====
(function() {
  const overlay = document.createElement('div');
  overlay.className = 'drag-overlay';
  overlay.innerHTML = `<div class="drag-overlay-inner">
    <div style="font-size:64px;margin-bottom:10px">🎵</div>
    <div style="font-size:22px;font-weight:800;color:var(--text)">שחרר כדי להעלות</div>
    <div style="font-size:14px;color:var(--text-muted);margin-top:6px">הקובץ ייכנס לשיר/סקיצה הפתוחים</div>
  </div>`;
  document.body.appendChild(overlay);

  let dragCounter = 0;
  document.addEventListener('dragenter', e => {
    if (!_curMusicId) return;
    if (!e.dataTransfer?.types?.includes('Files')) return;
    e.preventDefault();
    dragCounter++;
    overlay.classList.add('active');
  });
  document.addEventListener('dragleave', e => {
    dragCounter--;
    if (dragCounter <= 0) { dragCounter = 0; overlay.classList.remove('active'); }
  });
  document.addEventListener('dragover', e => {
    if (!_curMusicId) return;
    if (e.dataTransfer?.types?.includes('Files')) e.preventDefault();
  });
  document.addEventListener('drop', e => {
    overlay.classList.remove('active');
    dragCounter = 0;
    if (!_curMusicId) return;
    const file = e.dataTransfer?.files?.[0];
    if (!file || !file.type.startsWith('audio/')) return;
    e.preventDefault();
    // Synthesize an event-like object compatible with uploadMusicAudio
    const fakeEvt = { target: { files: [file], value: '' } };
    uploadMusicAudio(fakeEvt, _curMusicType, _curMusicId);
  });
})();